void solve() {
    int n;
	cin >> n;
    vector<int> a(n);
    rep(i, n) {
        cin >> a[i];
        -- a[i];
    }
    set<int> se;
    for(int i = 1; i < n; ++ i) se.insert(i);
    vector<int> ans(1, 0);
    for(int i = 1; i < n - 1; ++ i) {
        auto ite = se.begin();
        if(*ite == a[ans.back()]) ++ ite;
        ans.push_back(*ite);
        se.erase(ite);
    }
    int b = *se.begin();
    if(b != a[ans.back()]) {
        ans.push_back(b);
        out(ans);
    }
    set<int> pool;
    while(ans.size() and a[ans.back()] == b) {
        pool.insert(ans.back());
        ans.pop_back();
    } 
    if(pool.size() == 1) {
        if(n == 2) fail();
        vector<int> p;
        p.push_back(b);
        p.push_back(*pool.begin());
        p.push_back(ans.back());
        ans.pop_back();
        sort(all(p));
        auto tmp = ans;
        vector<int> res = {n + 1};
        do {
            for(int x: p) tmp.push_back(x);
            bool ok = 1;
            rep(i, n - 1) {
                if(tmp[i + 1] == a[tmp[i]]) ok = 0;
            }
            if(ok) chmin(res, tmp);
            rep(i, 3) tmp.pop_back();
        } while(next_permutation(all(p)));
        ans = res;
    } else {
        ans.push_back(b);
        while(pool.size()) {
            auto ite = pool.begin();
            if(*ite == a[ans.back()]) ++ ite;
            ans.push_back(*ite);
            pool.erase(ite);
        }
    }
    out(ans);
}

