#define N 100010
inline int read(){
	int x=0,f=1;
	char c=getchar();
	while(c<'0'||c>'9'){
		if(c=='-')f=-1;
		c=getchar();
	}
	while(c>='0'&&c<='9'){
		x=(x<<1)+(x<<3)+c-'0';
		c=getchar();
	}
	return x*f;
}
int n,a[N],cnt[N],p[N],vis[N],las;
int main(){
	n=read();
	for(int i=1;i<=n;++i){
		p[i]=i;
		a[i]=read();
		++cnt[a[i]];
	}
	if(n==2)return !printf("-1\n");
	for(int i=1;i<=n;++i){
		if(a[las]==p[i]){
			swap(p[i],p[i+1]);
		}
		int u=p[i];
		if(vis[a[u]]){
			if(i==n-2&&a[p[i+1]]==p[i+2]&&a[p[i+2]]==p[i+1]){
				if(p[i+1]==a[las]){
					swap(p[i],p[i+2]);
				}
				else{
					swap(p[i],p[i+1]);
				}
			}
		}
		else if(cnt[a[u]]==n-i){
			for(int j=i+1;j<=n;++j){
				if(p[j]==a[u]){
					for(int k=j;k>i;--k){
						swap(p[k],p[k-1]);
					}
					break;
				}
			}
		}
		printf("%d ",p[i]);
		vis[p[i]]=1;
		--cnt[a[p[i]]];
		las=p[i];
	}
	return 0;
}

