  std::vector<i32> to(N);
  for (auto &x: to) {
    std::cin >> x;
    --x;
  }
  std::set<i32> remain;
  for (auto i: range(0, N)) {
    remain.insert(i);
  }
  std::vector<i32> ans;
  ans.reserve(N);
  i32 bad = -1;
  while (remain.size() > 8) {
    auto itr = remain.begin();
    if (bad == *itr) ++itr;
    bad = to[*itr];
    ans.push_back(*itr);
    remain.erase(itr);
  }
  std::vector<i32> order(remain.begin(), remain.end());
  do {
