      if (bad2 == x) {
        ok = false;
        break;
      }
      bad2 = to[x];
    }
    if (ok) {
      for (auto x: order) {
        ans.push_back(x);
      }
      break;
    }
  } while (std::next_permutation(order.begin(), order.end()));
  if (ans.size() == N) {
    for (auto i: range(0, N)) {
      std::cout << ans[i] + 1 << " \n"[i + 1 == N];
