bool check() {
	vector<ll> nw;
	for (auto c : ans) nw.push_back(c);
	for (auto c : way) nw.push_back(c);

	bool k = true;
	for (int j = 1; j < nw.size(); j++) {
		ll v = nw[j - 1], u = nw[j];
		if (vec[v - 1] == u) k = false;
	}

	return k;
}

void find(int left) {
	if (left == 0) {
		if (check()) {
			if (a.size() == 0) {
				a = way;
			}
			else {
				for (int j = 0; j < way.size(); j++) {
					if (a[j] > way[j]) {
						a = way;
						break;
					}
					if (way[j] > a[j]) {
						break;
					}
				}

			}
		}
	}
	else {
		vector<ll> can;
		for (auto cur : s2) can.push_back(cur);

		for (auto cur : can) {
			s2.erase(cur);
			way.push_back(cur);
			find(left - 1);
			way.pop_back();
			s2.insert(cur);
		}
	}
}

