		for (int i = 0;i < 6;i++) {
			if (A[sa] != ss[0] && A[ss[0]] != ss[1] && A[ss[1]] != ss[2]) {
				for (int j = 0;j < 3;j++)B[x + 1 + j] = ss[j];
				S = { -1,-2,-3,-4 };
				return -1;
			}
			next_permutation(all(ss));
		}
		S.insert(sa);
		return sa;
	}
	if (y == A[B[x]]) {
		S.erase(S.begin());

		B[x + 1] = *S.begin();
		S.erase(S.begin());
		S.insert(y);
	}
	else {
		S.erase(S.begin());
		B[x + 1] = y;
	}

	j = dfs(x + 1);
	if (j < 0)return j;
	if (A[B[x]] == j) {
		S.insert(B[x]);
		return j;
	}
	else {
		B[x + 1] = j;
		S.erase(j);
		dfs(x + 1);
		return -1;
	}
}

