int get2(int x)
{
    auto it = mm2.lower_bound({x, -1});
    return (*it).second;
}

int ch(int lst, int x, int t)
{
    if (a[lst] == x)
    {
        return 0;
    }
    int cn = get2(x);
    mm.erase({cn, x});
    mm2.erase({x, cn});
    if (t == 0)
    {
        int nxt = a[x];
        if (!used[nxt])
        {
            int cnnxt = get2(nxt);
            mm.erase({cnnxt, nxt});
            mm.insert({cnnxt - 1, nxt});
            mm2.erase({nxt, cnnxt});
            mm2.insert({nxt, cnnxt - 1});
        }
        return 1;
    }
    auto it = mm.end();
    it--;
    if ((*it).first == mm.size())
    {
        mm.insert({cn, x});
        mm2.insert({x, cn});
        return 0;
    }
    mm.insert({cn, x});
    mm2.insert({x, cn});
    return 1;
}

