  }

  vector<int> from(n, -1), cycle(n, -1), cycle_size(n);
  vector<vector<int>> cycle_nodes(n);
  for (int i = 0; i < n; i++) {
    if (from[i] != -1) continue;
    queue<int> q;
    int k = i;
    while (true) {
      from[k] = i;
      q.push(k);
      if (from[a[k]] == -1) {
        k = a[k];
      } else {
        if (from[a[k]] == i) {
          while (q.front() != a[k]) q.pop();
          while (!q.empty()) {
            cycle[q.front()] = a[k];
            cycle_nodes[a[k]].push_back(q.front());
            q.pop();
          }
          cycle_size[a[k]] = cycle_nodes.size();
        }
        break;
      }
    }
  }

  vector<int> r;
  set<int> s;
  for (int i = 0; i < n; i++) s.insert(i);
