void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    S V<ll> alist; alist.pb(-1LL); llina(alist, n);

    if (n == 2) {
        cout << -1 << endl;
        return;
    }

    S ll checked[100005];
    memset(checked, 0, sizeof(checked));
    ll check_id = 1LL;
    S V<ll> loops;

    srep (s, 1, n+1) {
        ll v = s;
        for ( ; ; ) {
            if (checked[v]) {
                if (checked[v] == check_id) loops.pb(v);
                break;
            }
            checked[v] = check_id;
            v = alist[v];
        }
        check_id++;
    }

    S V<t2> loop2list;
    S bool loop2flag[100005];
    memset(loop2flag, 0, sizeof(loop2flag));


    for (auto v1 : loops) {
        ll v2 = alist[v1];
        if (alist[v2] == v1) {
            loop2list.pb(t2(v1, v2));
            loop2flag[v1] = true;
            loop2flag[v2] = true;
        }
    }

    debug_printf("---- loop2list\n");
    debug_print(loop2list);

    S bool added[100005];
    memset(added, 0, sizeof(added));
    S V<ll> leftlist;
    S V<ll> centerlist;
    S V<ll> rightlist;

    srep (s, 1, n+1) {
        ll v = s;
        while (!loop2flag[v] && !added[v]) {
            centerlist.pb(v);
            added[v] = true;
        }
    }
    reverse(ALL(centerlist));

    debug_printf("---- centerlist\n");
    debug_print(centerlist);

    for (auto loop2 : loop2list) {
        ll v1 = get<0>(loop2);
        ll v2 = get<1>(loop2);
        leftlist.pb(v1);
        rightlist.pb(v2);
    }

    S V<ll> anslist;
    for (auto v : leftlist) anslist.pb(v);
    for (auto v : centerlist) anslist.pb(v);
    for (auto v : rightlist) anslist.pb(v);

    assert(anslist.size() == n);

    rep (i, n) {
        cout << anslist[i] << ((i == n-1) ? "" : " ");
    }
    cout << endl;
}

