    vector<int> seq(n);
    cin>>seq;
    set<int> free;
    for(int i=2;i<=n;i++){
        free.insert(i);
    }
    function<bool(vector<int>&, set<int>&)> dfs = [&](vector<int> &curr, set<int> &left){
        if(left.size()==0){
            return true;
        }
        for(auto it = left.begin();it!=left.end();it++){
            int val = *it;
            if(val == seq[curr.back()-1]){
                continue;
            }
            curr.pb(val);
            free.erase(prev(++it));
            if(!dfs(curr, free)){
                curr.pop_back();
                free.insert(val);
                --it;
            }
            else{
