template <size_t n,class T>
struct heap{
    size_t sz;
    T e;
    T a[n+1];
    bool v[n+1];
    size_t hp[n+1],idx[n+1];
    explicit heap(T e = numeric_limits<T>::max())
            :sz{},e(e),a(),v(),hp(),idx(){
        fill(v+1,v+1+n,false);
        fill(a+1,a+1+n,e);
        fill(hp+1,hp+1+n,-1u);
        fill(idx+1,idx+1+n,-1u);

    }
    void prioritize(size_t i,T x){
        size_t s=idx[i];
        if(a[i]<x){
            while((s<<1u)<=sz){
                if((s<<1u)==sz){
                    if(x>a[hp[s<<1u]]){
                        hp[s]=hp[s<<1u];
                        idx[hp[s]]=s;
                        s<<=1u;
                    }
                    break;
                }
                if(x<=min(a[hp[s<<1u]],a[hp[(s<<1u)^1u]])) break;
                if((s<<1u)<sz&&a[hp[s<<1u]]>a[hp[(s<<1u)^1u]]){
                    hp[s]=hp[(s<<1u)^1u];
                    idx[hp[s]]=s;
                    s<<=1u;
                    s^=1u;
                }
                else{
                    hp[s]=hp[s<<1u];
                    idx[hp[s]]=s;
                    s<<=1u;
                }
            }
        }
        else{
            while(s>1&&x<a[hp[s>>1u]]){
                hp[s]=hp[s>>1u];
                idx[hp[s]]=s;
                s>>=1u;
            }
        }
        a[i]=x;
        hp[s]=i;
        idx[i]=s;
    }
    void Push(size_t i,T x){
        if(!v[i]){
            v[i]=true;
            ++sz;
            hp[sz]=i;
            idx[i]=sz;
        }
        prioritize(i,x);
    }
    void push(size_t i,T x){Push(i+1,x);}
    void pop(){
        const size_t t=hp[1];
        if(sz==1){
            hp[1]=-1u;
            a[t]=e;
            idx[t]=-1u;
            --sz;
            return;
        }
        idx[t]=-1u;
        idx[hp[sz]]=1;
        hp[1]=hp[sz];
        hp[sz]=-1u;
        T x=a[hp[1]];
        a[hp[1]]=a[t];
        a[t]=e;
        --sz;
        v[t]=false;
        prioritize(hp[1],x);
    }
    T top(){
        return hp[1]-1;
    }
};

