const int MAX_N = 1 << 19;

// セグメント木を持つグローバル配列
int nn, dat[2 * MAX_N - 1];

// 初期化
void init(int n_){
    // n_が小さいときの変な挙動を防ぐ
    if(n_ < 10)n_ = 10;
    // 簡単のため要素数を2のべき乗に
    nn = 1;
    while(nn < n_)nn *= 2;

    // 全ての値をINT_MAXに
    for(int i = 0; i < 2 * nn - 1; i++)dat[i] = INT_MAX;
}

// k番目の値(0-indexed)をaに変更
void update(int k, int a){
    // 葉の接点
    k += nn - 1;
    dat[k] = a;
    // 登りながら更新
    while(k > 0){
        k = (k - 1) / 2;
        dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
    }
}

// [a,b)の最小値を求める
// 後ろのほうの引数は、計算の簡単のための引数。
// kは節点の番号、l, rはその節点が[l, r)に対応づいていることを表す。
// したがって、外からはquery(a, b, 0, 0, nn)として呼ぶ。
int query(int a, int b, int k, int l, int r){
    // [a, b)と[l, r)が交差しなければ、INT_MAX
    if (r <= a || b <= l)return INT_MAX;

    // [a, b)が[l, r)を完全に含んでいれば、この節点の値
    if (a <= l && r <= b)return dat[k];
    else {
        // そうでなければ、2つの子の最小値
        int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
        int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }
}


int main() {
    int n;
    cin >> n;
    init(n);

    int a[n];
    rep(i,n)cin >> a[i];

    if(n == 2){
        cout << "-1" << endl;
        return 0;
    }

    int ans[n] = {};

    rep(i,n+1){
        update(i,0);
    }
    rep(i,n){
        int tmp = query(a[i],a[i]+1,0,0,nn);
        tmp--;
        update(a[i],tmp);
    }

    int ng = -1;
    priority_queue<int,vector<int>,greater<int>> que;
    srep(i,1,n+1){
        que.push(i);
    }
    int use[n+1] = {};
    rep(i,n){
        if(i == n - 3){
            int b[3];
            rep(j,3){
                b[j] = que.top();
                que.pop();
            }
            do {
                rep(j,3){
                    ans[n-3+j] = b[j];
                }
                int flag = 1;
                rep(i,n-1){
                    if(ans[i+1] == a[ans[i]-1])flag = 0;
                }
                if(flag)break;
            } while( next_permutation(b,b+3) );     // 次の順列を生成
            break;
        }else{
            int ma = -query(0,n+1,0,0,nn);
            if(ma == n - i - 1){
                int l = 0, r = n;
                while(l+1<r){
                    int m = (l+r)/2;
                    if(-query(0,m+1,0,0,nn) == ma){
                        r = m;
                    }else{
                        l = m;
                    }
                }
                ans[i] = r;
                use[r] = 1;
                srep(ii,i+1,n){
                    while(use[que.top()] == 1){
                        que.pop();
                    }
                    if(ii == i+1){
                        int keep = que.top();
                        if(a[ans[i]-1] == keep){
                            que.pop();
                            while(use[que.top()] == 1){
                                que.pop();
                            }
                            ans[ii] = que.top();
                            que.pop();
                            que.push(keep);
                        }else{
                            ans[ii] = keep;
                            que.pop();
                        }
                    }else{
                        ans[ii] = que.top();
                        que.pop();
                    }
                }
                break;
            }else{
                int x;
                if(que.top() == ng){
                    int keep = que.top();
                    que.pop();
                    x = que.top();
                    que.pop();
                    que.push(keep);
                }else{
                    x = que.top();
                    que.pop();
                }
                ans[i] = x;
                ng = a[x-1];
                int tmp = query(ng,ng+1,0,0,nn);
                tmp++;
                update(ng,tmp);
            }
        }
    }


    rep(i,n)cout << ans[i] << ' ';
    cout << endl;
    return 0;
}

