        a[i]--;
        in[a[i]].first++;
        in[i].second = i;
    }
    SegmentTree<pair<int, int>> seg(in, f, unit);
    set<int> unused;
    for (int i = 0; i < n; ++i) {
        unused.insert(i);
    }
    vector<int> ret;
    int ng = -1;
    for (int i = 0; i < n - 5; ++i) {
        auto mx = seg.query(0, n);
        if (mx.first == n - i - 1) {
            cout << -1 << "\n";
            return 0;
        }
        if (mx.first >= n - i - 2) {
            if (ng == mx.second) {
                cout << -1 << "\n";
                return 0;
            }
            ret.push_back(mx.second);
            unused.erase(mx.second);
            ng = a[mx.second];
            seg.update(mx.second, {-1, mx.second});
            int k  = a[mx.second];
            auto u = seg.query(k, k + 1);
            seg.update(u.second, {u.first - 1, u.second});
        } else {
            auto it = unused.begin();
            if (*it == ng)
                it = next(it);
            int i = *it;
            ret.push_back(i);
            unused.erase(i);
            ng = a[i];
            seg.update(i, {-1, i});
            int k  = a[i];
            auto u = seg.query(k, k + 1);
            seg.update(u.second, {u.first - 1, u.second});
        }
    }
    vector<int> rest;
    for (auto &u : unused) {
        rest.push_back(u);
    }
    do {
        bool ok = true;
        for (int i = 0; i < (int)rest.size(); ++i) {
            if (ng == rest[i])
                ok = false;
            ng = a[rest[i]];
        }
        if (ok) {
            for (auto &r : rest) {
                ret.push_back(r);
            }
            break;
        }
    } while (next_permutation(rest.begin(), rest.end()));
    if ((int)ret.size() != n) {
        cout << -1 << "\n";
        return 0;
    }
    for (int i = 0; i < n; ++i) {
        if (i)
            cout << " ";
        cout << ret[i] + 1;
    }
    cout << "\n";
    return 0;
}

