        in[i].second = i;
    }
    SegmentTree<pair<int, int>> seg(in, f, unit);
    set<int> unused;
    for (int i = 0; i < n; ++i) {
        unused.insert(i);
    }
    vector<int> ret;
    int ng = -1;
    for (int i = 0; i < n - 5; ++i) {
        auto mx = seg.query(0, n);
        // if (mx.first == n - i - 1) {
        //     cout << -1 << "\n";
        //     return 0;
        // }

        auto it = unused.begin();
        if (*it == ng)
