VInt f(VInt v)
{
	int n = SIZE(v);
	v.push_back(-1);
	if (n <= 2) return VInt(1, -1);

	VInt res;
	VInt used(n, 0);
	int last = n;
	int cnt = 0;
	int i, j;
	FOR(i, 0, n - 7)
	{
		FOR(j, cnt, n)
			if (used[j] == 0 && v[last] != j)
				break;

		if (j == n) throw 0;
		last = j;
		used[j] = 1;
		while (used[cnt] != 0) ++cnt;
		res.push_back(j);
	}

	VInt w;
	FOR(i, 0, n) if (used[i] == 0) w.push_back(i);
	sort(ALL(w));
	do
	{
		FOR(i, 1, SIZE(w))
			if (v[w[i - 1]] == w[i])
				break;
		if (v[last] != w[0] && i == SIZE(w)) 
		{
			res.insert(res.end(), ALL(w));
			FOR(i, 0, n) ++res[i];
			return res;
		}
	} while (next_permutation(ALL(w)));
	throw 0;
}

