        cout << -1 << '\n';
        return 0;
    }
    set<int> S;
    for (int i = 0; i < N; i++) S.insert(i);
    vector<int> ans;
    int ban = -1;
    for (int i = 0; i < N; i++) {
        int rest = N - i;
        int choice = -1;
        for (auto item : S) {
            if (item == ban) {
                continue;
            }
            if (M[A[item]] == rest - 1 && S.count(A[item])) {
                choice = A[item];
                goto DONE;
            }
            choice = item;
            break;
        }
