int main() {
  // なもりグラフみたいになっているんですが
  // 基本的には普通にとってもよい
  // 残しちゃダメなやつ: 長さ2のループ1つ

  // 最後の数頂点はうくなので全探索をします

  // これは嘘で, ある1頂点に向かうやつだけのこってもダメです
  // そのような形になったやつは除去していく必要がある
  // ある1頂点に向かうやつ+長さ2のループがめんどい

  // 入次数が残り頂点数のやつがある か？　だと信じています

  int N;
  cin >> N;
  vector< int > A(N);

  vector< int > in(N);

  for(int i = 0; i < N; i++) {
    cin >> A[i];
    --A[i];
    in[A[i]]++;
  }
  multiset< int > XX;
  for(int i = 0; i < N; i++) {
    XX.emplace(in[i]);
  }


  auto solve_uku = [&](vector< int > rest, int last) {

    sort(begin(rest), end(rest));
    do {
      int las = last;
      bool ng = false;
      for(int i = 0; i < rest.size(); i++) {
        if(rest[i] == las) ng = true;
        las = A[rest[i]];
      }
      if(!ng) return rest;
    } while(next_permutation(begin(rest), end(rest)));

    if(N == 2) {
      cout << -1 << endl;
      exit(0);
    }

    throw 0;
    exit(0);
  };

  set< int > st;
  for(int i = 0; i < N; i++) st.emplace(i);
  vector< int > ans;
  int ng = -1;
  while(st.size() >= 10 && *XX.rbegin() + 1 < st.size()) {
    auto it = st.begin();
    if(*it == ng) ++it;
    ans.emplace_back(*it);
    ng = A[*it];
    XX.erase(XX.find(in[A[*it]]));
    in[A[*it]]--;
    XX.emplace(in[A[*it]]);
    st.erase(it);
  }

  if(st.size() > 10) {
    int p = -1;
    for(int i : st) {
      if(in[i] + 1 == st.size()) p = i;
    }
    assert(A[p] != ng);
    bool first = true;
    while(st.size() >= 10) {
      auto it = first ? st.find(p) : st.begin();
      if(*it == ng) ++it;
      ans.emplace_back(*it);
      ng = A[*it];
      in[A[*it]]--;
      st.erase(it);
      first = false;
    }
  }


  vector< int > B;
  for(auto &rest : st) {
    B.emplace_back(rest);
  }
  auto ans2 = solve_uku(B, ng);

  for(auto &p : ans) cout << p + 1 << " ";
  for(auto &p : ans2) cout << p + 1 << " ";

  cout << endl;
}

