int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll N;
  cin>>N;
  vector<ll> A(N),cnt(N,0);
  rep(i,N){
  	cin>>A[i];
  	A[i]--;
    cnt[A[i]]++;
  }

  if(N==2){
  	cout<<"-1"<<endl;
  	return 0;
  }

  vector<bool> used(N,false);
  vector<ll> res(N);
  set<ll> st;
  rep(i,N){
    st.insert(i);
  }
  ll x=-1;
  rep(i,N-3){
    ll rest=N-i;
  	ll crt=-1;
  	ll Ax=-1;
  	if(x!=-1)Ax=A[x];

    ll mn=*st.begin();
    if(cnt[A[mn]]==rest-1){
      crt=A[mn];
    }else{
      if(Ax==mn){
        auto it=*st.begin();
        it++;
        crt=it;
      }else{
        crt=mn;
      }
    }

  	used[crt]=true;
    st.erase(st.find(crt));
  	res[i]=crt;
  	x=crt;
    cnt[A[x]]--;
  }
  vector<ll> ps;
  rep(i,N){
  	if(used[i])continue;
  	ps.push_back(i);
  }
  do{
  	vector<ll> resb=res;
  	rep(i,3){
  		resb[N-3+i]=ps[i];
  	}
  	bool ok=true;
  	rep(i,N-1){
  		if(A[resb[i]]==resb[i+1])ok=false;
  	}
  	if(ok){
  		res=resb;
  		break;
  	}
  }while(next_permutation(all(ps)));

  rep(i,N)cout<<res[i]+1<<" ";
  cout<<endl;

  return 0;
}

