    i64 q = -1;
    rep(i,0,N) {
      if(cnt[i] == N - 1) {
        q = i;
        break;
      }
    }
    if(q != -1) {
      vector<i64> ans;
      vector<i64> vis(N);
      ans.push_back(q);
