int N, K, a[100000];
pair<int, int>tree[1 << 18];
set<int>st;
vector<int>res;


void update(int x, int t) {
	x += (1 << 17);
	tree[x].first = t;
	while (x) {
		x /= 2;
		tree[x] = max(tree[x + x], tree[x + x + 1]);
	}
}

bool func(int x) {
	if (x == N - 1) {
		if (a[res.back()] == *st.begin())return false;
		res.push_back(*st.begin());
		return true;
	}
	else {
		if (tree[1].first == N - x - 1) {
			auto p = tree[1];
			if (!res.empty() && a[res.back()] == p.second)return false;
			st.erase(p.second);
			res.push_back(p.second);
			update(p.second, 0);
			update(a[p.second], tree[(1 << 17) + a[p.second]].first - 1);
			if (func(x + 1))return true;
			res.pop_back();
			st.insert(p.second);
			update(a[p.second], tree[(1 << 17) + a[p.second]].first + 1);
			update(p.second, p.first);
		}
		else {
			auto it = st.begin();
			while (it != st.end()) {
				auto it2 = it;
				it2++;
				int t = *it;
				if (!(!res.empty() && a[res.back()] == t)) {
					st.erase(it);
					res.push_back(t);
					int k = tree[t + (1 << 17)].first;
					update(t, 0);
					update(a[t], tree[(1 << 17) + a[t]].first - 1);
					if (func(x + 1))return true;
					res.pop_back();
					st.insert(t);
					update(a[t], tree[(1 << 17) + a[t]].first + 1);
					update(t, k);
				}
				it = it2;
			}
		}
	}
	return false;
}

