vector<set<int>> ip;

// ip[x] := x のことが嫌いな人の集合
// x を右隣に置きたくない人の集合

bool check(const vector<int> &res) {
  for(int i = 0; i + 1 < res.size(); i++) {
    if(res[i + 1] == p[res[i]]) return false;
  }
  return true;
}

const int NOKORI = 5;

// res は確定，rem を全探索
void last(vector<int> &res, vector<int> &rem) {
  do {
    if(check(rem)) {
      for(int i = 0; i < res.size(); i++) cout << res[i] + 1 << " ";
      for(int i = 0; i < rem.size(); i++) cout << rem[i] + 1 << " ";
      cout << endl;
      return;
    }
  }while(next_permutation(ALL(rem)));
  cout << -1 << endl;
  return;
}


void solve() {
  if(N <= NOKORI) {
    vector<int> res, rem(N);
    for(int i = 0; i < N; i++) rem[i] = i;
    last(res, rem);
    return;
  }

  vector<int> res;
  set<int> rem;
  for(int i = 0; i < N; i++) rem.insert(i);
  while(N - (int)res.size() > NOKORI) {
    int dame = -1;
    if(res.size() > 0) dame = p[res.back()];


    // とりあえず貪欲に
    int ne = -1;
    for(auto it : rem) {
      if(it == dame) continue;
      ne = it;
      break;
    }

    // ne を選んでしまうと詰むときは取り替える
    if(ip[p[ne]].size() + res.size() == N - 1) {
      ne = p[ne];
    }

    // ne を選ぶ
    // drken さん，ここら辺が綺麗すぎる
    res.push_back(ne);
    rem.erase(ne);
    ip[p[ne]].erase(ne);
  }

  vector<int> vrem;
  for(int i = 0; i < N; i++) if(rem.count(i)) vrem.push_back(i);
  last(res, vrem);
}

