template<typename T>
struct segment_tree {
    int n;
    T zero;
    std::vector<T> data;
    int get_size(int n_) const {
        int ret = 1;
        while (ret < n_) { ret <<= 1; }
        return ret;
    }
    segment_tree(int n_, T zero = T()) : n(get_size(n_)), zero(zero), data(n << 1, zero) {}
    template<typename I> segment_tree(I begin, I end, T zero = T())
        : n(get_size(end - begin)), zero(zero), data(n << 1) {
        std::copy(begin, end, data.begin() + n);
        for (int i = n - 1; i > 0; i--) { data[i] = data[i << 1] + data[(i << 1) + 1]; }
    }
    void set(int i, const T &x) {
        data[i += n] = x;
        while (i >>= 1) { data[i] = data[i << 1] + data[(i << 1) + 1]; }
    }
    T operator[](int i) const { return data[i + n]; }
    T get_sum(int l, int r) const {
        if (l < 0) { l = 0; }
        if (r > n) { r = n; }
        T a = zero, b = zero;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) { a = a + data[l++]; }
            if (r & 1) { b = data[--r] + b; }
        }
        return a + b;
    }
};
struct max_monoid {
    pint val;
    max_monoid() : val({LLONG_MIN, LLONG_MIN}) {}
    max_monoid(pint val) : val(val) {}
    bool operator==(const max_monoid &rhs) const { return val == rhs.val; }
    bool operator!=(const max_monoid &rhs) const { return std::rel_ops::operator!=(*this, rhs); }
    max_monoid &operator+=(const max_monoid &rhs) {
        val = std::max(val, rhs.val);
        return *this;
    }
    max_monoid operator+(const max_monoid rhs) const { return max_monoid(*this) += rhs; }
};

