bool dfs(int N, int depth,vector<int>&A,vector<int>&ans, set<int>&cand) {
	if (depth == N)return true;
	int l = -1;
	int sz = cand.size();
	REP(_, sz+1) {
		auto itr = cand.upper_bound(l);
		if (itr == cand.end())return false;
		l = *itr;
		if (depth == 0) {
			ans.push_back(l);
			cand.erase(l);
			if (dfs(N, depth + 1, A, ans, cand))return true;
			else {
				ans.pop_back();
				cand.insert(l);
			}
		}
		else {
			if (A[ans[depth-1]] == l)continue;
			else {
				ans.push_back(l);
				cand.erase(l);
				if (dfs(N, depth + 1, A, ans, cand))return true;
				else{
					ans.pop_back();
					cand.insert(l);
				}
			}
		}
	}
}

