	while (!ok) {
		ok = true;
		int pos = 0;
		REP(i, N) {
			if (A[i] == i) {
				pos = i;
				ok = false;
				break;
			}
		}
		if (!ok) {
			int j = mt() % N;
			swap(A[pos], A[j]);
		}
	}
	REP(i, N)A[i]++;
	print(N);
