	set<int>cand;
	REP(i, N) {
		A[i]--;
		cand.insert(i);
	}
	if (N == 2) {
		print(-1); return;
	}
	vector<int>ans;
	ans.push_back(0);
	cand.erase(0);
	FOR(i, 1, N) {
