bool kek(vi a) {
    int n = a.size();
    int fr = -1;
    vi ns(n);
    fori (i, n) {
        ns[i] = i + 1;
    }

    vi p = ns;
    int ans = -1;
    do {
        bool ok = fr != p[0];
        fori (i, n - 1) {
            if (p[i + 1] == a[p[i] - 1]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            if (ans == -1) {
                ans = p[0];
            } else if (ans != p[0]) {
                return true;
            }
        }
    } while (next_permutation(ALL(p)));

    return false;
}

vi naive(const vi & a, vi ns, int fr) {
    a.size();
    int n = ns.size();
    sort(ALL(ns));
    vi p = ns;
    vi ans = {};
    do {
        bool ok = fr != p[0];
        fori (i, n - 1) {
            if (p[i + 1] == a[p[i] - 1]) {
                ok = false;
                break;
            }
        }
        if (ok) {
            if (ans.empty()) {
                ans = p;
            } else if (ans > p) {
                ans = p;
            }
        }
    } while (next_permutation(ALL(p)));

    return ans;
}

