template<typename M>
struct SegmentTree {

  /**
  * @brief コンストラクタ. O(n)
  * @param[in] n セグ木のサイズ.
  * @param[in] f モノイドの演算.
  * @param[in] e モノイドの単位元.
  * @details 使い方
  *   e.g. Range Minimum
  *   SegmentTree<int> segt(
  *            n,
  *            [](int a,int b){ return min(a+b); },
  *            INF);
  *               // 全て単位元で初期化される.
  */
  SegmentTree(
    int n,
    const function<M(M,M)>& f,
    const M& e) : n(n), f(f), e(e) {
    sz = 1;
    while (sz < n) sz <<= 1;
    data.assign(2 * sz, e);
  }

  /**
  * @brief 全体に初期値を入れる. O(n)
  * @param[in] v 要素モノイドのvector. 初期化する.
  * @details 使い方
  *   segt.build(vector<int>(n, 0));
  */
  void build(const vector<M>& v) {
    assert(v.size() <= n);
    for (int i = 0; i < v.size(); ++i) {
      data[i + sz] = v[i];
    }
    for (int i = sz-1; i > 0; --i) {
      data[i] = f(data[2 * i], data[2 * i + 1]);
    }
  }

  /**
  * @brief 指定した位置に更新クエリを実行する. O(log n)
  * @param[in] k 位置k の要素に作用させる.
  * @param[in] q 値x をq(x) で更新する.
  * @details 使い方
  *   e.g. Add Query
  *   int i, x; // 位置i をx を足したい.
  *   segt.update(i, [&](int a){ return a + x; });
  *
  *   e.g. Update Query
  *   int i, x; // 位置i をx に更新したい.
  *   segt.update(i, [&](int a){ return x; });
  */
  template<class UpdateQuery>
  void update(int k, const UpdateQuery &q) {
    k += sz;
    data[k] = q(data[k]);
    while (k >>= 1) {
      data[k] = f(data[2 * k], data[2 * k + 1]);
    }
  }

  /**
  * @brief 指定した区間に取得クエリを実行する. O(log n)
  * @param[in] l, r 区間[l, r) を取得する.
  * @return 取得した値.
  * @details 使い方
  *   e.g. Range Minimum
  *   int l, r; // 区間[l, r) のminを取得したい.
  *   cout << segt.query(l, r) << endl;
  */
  M query(int a, int b) const {
    return query(a, b, 1, 0, sz);
  }

  /**
  * @brief 指定したindexの要素を取得. O(1)
  * @param[in] i 取得したい要素のindex
  * @return 取得した値.
  */
  M operator[](int k) const {
    return data[k + sz];
  }

  /**
  * @brief vector みたいに出力.
  */
  friend ostream& operator<<(ostream& os, SegmentTree& s) {
    os << "[";
    for (int i = 0; i < s.n; ++i) {
      if (i) os << " ";
      os << s[i];
    }
    return os << "]";
  }

private:
  int n, sz;
  vector<M> data;
  const function<M(M,M)> f;
  const M e;

  M query(int a, int b, int k, int l, int r) const {
    if (r <= a || b <= l) {
      return e;
    } else if (a <= l && r <= b) {
      return data[k];
    } else {
      return f(query(a,b,2*k,  l,(l+r)/2),
               query(a,b,2*k+1,(l+r)/2,r));
    }
  }
};

bool cancons = true;

vi ans;
void sch(int n, int k, vi &a, SegmentTree<int> &st, map<int, int> &mp) {
  if(!cancons) return;
  if(k == n) return;
  if(n - k <= 3) {
    vi rem;
    while(1) {
      int tmp = st.query(0, n);
      if(tmp == INF) break;
      rem.push_back(tmp);
      st.update(tmp, [](int x){return INF;});
    }

    //cout << ans << endl;
    //cout << rem << endl;

    bool ok = false;
    REP(i, 6) {
      bool nowok = true;
      nowok &= ans.empty() || a[ans.back()] != rem[0];
      REP(j, SZ(rem)-1) {
        nowok &= a[rem[j]] != rem[j+1];
      }
      if(nowok) {
        ok = true;
        break;
      }
      next_permutation(ALL(rem));
    }

    cancons = ok;
    REP(i, SZ(rem)) ans.push_back(rem[i]);
  } else {
    //cout << st << endl;
    int preva = INF;
    if(!ans.empty()) {
      preva = st[a[ans.back()]];
      st.update(a[ans.back()], [](int x) {return INF;});
    }
    int idx = st.query(0, n);
    if(mp[idx] == n-k-1) {
      st.update(idx, [](int x){return INF;});
      int prev = idx;
      idx = st.query(0, n);
      st.update(prev, [&](int x){return prev;});
    }

    st.update(idx, [](int x){return INF;});
    if(!ans.empty()) st.update(a[ans.back()], [&](int x){return preva;});
    ans.push_back(idx);
    mp[a[idx]]--;
    sch(n, k+1, a, st, mp);
  }
}

