bool search_path(ll current,vector<ll> &A, set<ll> &remain, vector<ll> &path){
    // cout << remain.size() << " " << current << endl;
    if (remain.empty()){
        path.push_back(current);
        return true;
    }

    for(auto r: remain){
        if (A[current] == r){
            continue;
        }
        remain.erase(r);
        bool is_clear = search_path(r,A,remain,path);
        remain.insert(r);
        if (is_clear){
            path.push_back(current);
            return true;
        }else{
            path.clear();
        }
    }
    return false;
}
