        cout << -1 << endl;
        return 0;
    }

    set<LL> rest;
    for(LL i = 0; i < n; ++i){
        rest.insert(i);
    }
    vector<LL> ans;
    for(LL i = 0; i+3 < n; ++i){
        for(LL cur: rest){
            if(indegree[cur] >= n-1-i){
                continue;
            }
            if(i > 0 && a[ans[ans.size()-1]] == cur){
                continue;
            }
            ans.push_back(cur);
            indegree[a[cur]] -= 1;
            break;
        }
        rest.erase(ans[ans.size()-1]);
    }
    assert(rest.size() == 3);
    vector<LL> tri(rest.begin(), rest.end());
    solve3(ans, a, tri);
    for(LL i = 0; i < n; ++i){
        cout << ans[i]+1 << ((i+1==n)?"\n":" ");
    }
    return 0;
}

