	if(i==n) return true;

	int x=Deg.rbegin()->second;
	if(deg[x]==n-i-1){
		if(i==0 || bad[ans[i-1]]!=x){
			int y=bad[x];
			bool b=V.count(y);

			Deg.erase({deg[x],x});
			if(b){
				Deg.erase({deg[y],y});
				deg[y]--;
				Deg.emplace(deg[y],y);
			}
			V.erase(x);

			ans[i]=x;
			if(dfs(i+1)) return true;

			V.emplace(x);
			if(b){
				Deg.erase({deg[y],y});
				deg[y]++;
				Deg.emplace(deg[y],y);
			}
			Deg.emplace(deg[x],x);
		}
		return false;
	}

	for(int x=*V.begin();x<n;x=*V.upper_bound(x)){
		if(i==0 || bad[ans[i-1]]!=x){
			int y=bad[x];
			bool b=V.count(y);

			Deg.erase({deg[x],x});
			if(b){
