//配列AとBのconvolution
//畳み込み演算をする
vector<mint>fold(vector<mint>A, vector<mint>B) {
	//static_assert(mint::mod == 998244353LL, "MODと原始根を貼りなおしてください。");
	vector<mint>C(A.size() + B.size());
	int logN = 0;
	while (C.size() > (1 << logN))++logN;
	C.resize(1 << logN);
	A.resize(1 << logN);
	B.resize(1 << logN);
	vector<mint>dC(C.size());
	mint root = m_pow(mint(3), (mint::mod - 1) >> logN);
	vector<mint>zeta{};
	zeta.push_back(root);
	zeta.push_back(root);
	zeta.reserve(1 << logN);
	for (int i = 1; i < (1 << logN) - 1; ++i) {
		zeta.push_back(root * zeta.back());
	}
	zeta.front() = zeta.back() * root;
	auto dA = FFTraw<mint>(A, logN, zeta);
	auto dB = FFTraw<mint>(B, logN, zeta);
	for (int i = 0; i < C.size(); ++i) {
		dC[i ? C.size() - i : 0] = dA[i] * dB[i];
	}
	C = FFTraw<mint>(dC, logN, zeta);
	for (mint& elm : C)elm *= ~mint(1LL << logN);
	return C;
}
