V<ll> ans;

bool solve() {
    ll N;
    cin >> N;
    V<ll> A(N);
    V<ll> cnt(N);
    for (ll &e : A) {
        cin >> e;
        e--;
        cnt[e]++;
    }

    if (N == 2) return false;

    map<ll, set<ll>> cnt_mp;
    set<ll> rest;
    for (ll i = 0; i < N; i++) {
        cnt_mp[cnt[i]].insert(i);
        rest.insert(i);
    }

    auto push = [&](ll val) {
        ll dl = A[val];
        ll c = cnt[dl];
        cnt_mp[c].erase(dl);
        cnt_mp[c - 1].insert(dl);
        cnt[dl]--;
        ans.push_back(val);
        cnt_mp[cnt[val]].erase(val);
        rest.erase(val);
    };

    for (ll i = 0; i < N - 5; i++) {
        ll oth = N - i - 1;
        auto ite = cnt_mp.find(oth);
        ll val;
        if (ite != cnt_mp.end() && ite->second.size()) {
            val = *(ite->second.begin());
        } else {
            val = *(rest.begin());
            if (ans.size() && A[ans.back()] == val) {
                ll tmp = val;
                rest.erase(val);
                val = *(rest.begin());
                rest.insert(tmp);
            }
        }
        push(val);
    }

    V<ll> lis;
    for (ll e : rest) lis.push_back(e);
    sort(ALL(lis));
    bool ok = true;
    do {
        ok = true;
        if (ans.size()) {
            ll d = ans.back();
            if (A[d] == lis.front()) continue;
        }
        for (ll i = 0; i + 1 < lis.size(); i++) {
            ll a = lis[i], b = lis[i + 1];
            if (A[a] == b) ok = false;
        }
        if (ok) break;
    } while (next_permutation(ALL(lis)));
    if (!ok) return false;
    for (ll e : lis) ans.push_back(e);
    return true;
}

int main() {
    if (solve()) {
        for (ll i = 0; i < ans.size(); i++) cout << ans[i] + 1 << " \n"[i + 1 == ans.size()];
    } else {
        cout << -1 << endl;
    }
    return 0;
}

