bool check(const vector<int> &res) {
	REP(i, res.size() - 1) {
		if (res[i + 1] == p[res[i]])return false;
	}
	return true;
}

void last(vector<int> &res, vector<int> &rem) {
	do {
		if (res.size() > 0 && rem[0] == p[res.back()])continue;
		if (check(rem)) {
			REP(i, res.size())cout << res[i] + 1 << " ";
			REP(i, rem.size())cout << rem[i] + 1 << " ";
			cout << endl;
			return;
		}
	} while (next_permutation(rem.begin(), rem.end()));
	cout << -1 << endl;
	return;
}

const int REM = 5;
void solve() {
	cin >> N;
	p.resize(N);
	ip.assign(N, set<int>());
	REP(i, N) {
		cin >> p[i];
		p[i]--;
		ip[p[i]].insert(i);
	}
	if (N <= REM) {
		vector<int>res, rem(N);
		REP(i, N)rem[i] = i;
		last(res, rem);
		return;
	}
	vector<int>res;
	set<int>rem;
	REP(i, N)rem.insert(i);
	while (N - res.size() > REM) {
		int bad = -1;
		if (res.size() > 0)bad = p[res.back()];

		//Greedy
		int nxt = -1;
		for (auto it : rem) {
			if (it == bad)continue;
			nxt = it;
			break;
		}
		//nxtを選ぶと詰むとき
		if (ip[p[nxt]].size() + res.size() == N - 1) {
			nxt = p[nxt];
		}
		res.push_back(nxt);
		rem.erase(nxt);
		ip[p[nxt]].erase(nxt);
	}
	vector<int>vrem;
	REP(i, N)if (rem.count(i))vrem.push_back(i);
	last(res, vrem);
}



