                ans.push_back(true_s);
                rs.erase(rs.lower_bound(P(cnt[true_s],true_s)));

                se.erase(true_s);

                ban=a[true_s];
                if(se.find(a[true_s])!=se.end()){
                    rs.erase(rs.lower_bound(P(cnt[a[true_s]],a[true_s])));
