constexpr const int maxn = 1 << 17;
int a[maxn], cnt[maxn], ans[maxn], vis[maxn];
set<int> have[maxn], wait;

void game_over() { cout << "-1" << endl; exit(0); }

int choice(int x) {
	wait.erase(x);
	have[cnt[x]].erase(x);
	vis[x] = 1;
	int y = a[x];
	if (vis[y]) return x;
	have[cnt[y]].erase(y);
	have[--cnt[y]].insert(y);
	return x;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int n;
	cin >> n;
	rep(i, 1, n + 1) cin >> a[i], ++cnt[a[i]];
	rep(i, 1, n + 1) have[cnt[i]].insert(i);
	rep(i, 1, n + 1) wait.insert(i);
	rep(i, 1, n + 1) {
		if (have[n - i].empty()) {
			if (a[ans[i - 1]] == *wait.cbegin()) {
				ans[i] = choice(*next(wait.cbegin()));
			} else {
				ans[i] = choice(*wait.cbegin());
			}
		} else if (int(have[n - i].size()) != 1) {
			game_over();
		} else {
			ans[i] = choice(*have[n - i].cbegin());
		}
	}
	rep(i, 1, n + 1) cout << ans[i] << " \n"[i == n];
}

