using pii = pair<int, int>;
static constexpr int INF = 1000000000;
struct range_query_behavior {
	using value_type = pii;
	value_type identity() const { return make_pair(-INF, 0); }
	value_type merge(const value_type& a, const value_type& b) const {
		return std::max(a, b);
	}
};
int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<int> a(n);
	vector<pii> init(n);
	for(int i = 0; i < n; ++i){
		cin >> a[i];
		--a[i];
		++init[a[i]].first;
		init[i].second = i;
	}
	loquat::segment_tree<range_query_behavior> st(init.begin(), init.end());
	set<int> pq;
	for(int i = 0; i < n; ++i){ pq.insert(i); }
	vector<int> b;
	while(pq.size() > 5){
		int x = -1;
		const auto p = st.query(0, n);
		if(p.first == pq.size() - 1){
			x = p.second;
		}else if(!b.empty() && a[b.back()] == *(pq.begin())){
			x = *(std::next(pq.begin()));
		}else{
			x = *(pq.begin());
		}
		pq.erase(x);
		b.push_back(x);
		const auto q = st.query(a[x], a[x] + 1);
		if(q.first > 0){ st.update(a[x], pii(q.first, a[x])); }
		st.update(x, pii(-INF, 0));
	}
	const int m = min<int>(pq.size(), n);
	while(!pq.empty()){
		b.push_back(*(pq.begin()));
		pq.erase(b.back());
	}
	bool possible = false;
	do {
		bool accept = true;
		for(int i = 0; i < m; ++i){
			const int j = n - m + i;
			if(j == 0){ continue; }
			if(a[b[j - 1]] == b[j]){ accept = false; }
		}
		if(accept){
			possible = true;
			break;
		}
	} while(next_permutation(b.end() - m, b.end()));
	if(!possible){
		cout << -1 << endl;
	}else{
		for(const auto x : b){
			cout << (x + 1) << " ";
		}
		cout << endl;
	}
	return 0;
}

