struct state{
  int x,v;
  state(int X=0,int V=0){x=X;v=V;}
  bool operator < (const state &p)const{return v<p.v||v==p.v&&x<p.x;}
};
set<state>sdeg,sid;
int tmp[N+9],ct;
int vis[N+9];
int ans[N+9];

bool Dfs_ans(int k,int last){
  if (k>n) return 1;
  for (int i=1;i<=ct;++i)
	if (!vis[i]&&a[last]^tmp[i]){
	  vis[i]=1;
	  ans[k]=tmp[i];
	  if (Dfs_ans(k+1,tmp[i])) return 1;
	  vis[i]=0;
	}
  return 0;
}

void Get_ans(){
  if (n==2) return;
  ans[0]=1;
  for (int i=1;i<=n;++i){
	sdeg.insert(state(i,deg[i]));
	sid.insert(state(i,i));
  }
  int last=0;
  for (int i=1;i<=n-5;++i){
	int t=sdeg.begin()->x;
	if (deg[t]<n-i) t=sid.begin()->x;
	if (t==a[last]) t=(++sid.begin())->x;
	ans[i]=last=t;
	sdeg.erase(state(t,deg[t]));
	sid.erase(state(t,t));
	if (sid.find(state(a[t],a[t]))!=sid.end()){
	  sdeg.erase(state(a[t],deg[a[t]]));
	  sdeg.insert(state(a[t],--deg[a[t]]));
	}
  }
  for (set<state>::iterator it=sid.begin();it!=sid.end();++it) tmp[++ct]=it->x;
  Dfs_ans(max(n-4,1),last);
}

void work(){
  Get_ans();
}

void outo(){
  if (!ans[0]) puts("-1");
  else{
	for (int i=1;i<=n;++i)
	  printf("%d ",ans[i]);
    puts("");
  }
}

int main(){
  into();
  work();
  outo();
  return 0;
}

