constexpr inline long long imod(const long long a, const long long b)
{
	return (a >= 0) ? (a % b) : (a % b + b);
}

template<long long>class modint;

//modintが引数の繰り返し2乗法
template<long long MOD>
constexpr modint<MOD> m_pow(modint<MOD> x, long long n);

//modの整数クラス
template <long long MOD = 998244353>
class modint
{
public:
	constexpr modint operator+(const modint& other)const
	{
		return modint(a + other.a >= MOD ? a + other.a - MOD : a + other.a, true);
	}
	constexpr modint operator-(const modint& other)const
	{
		return modint(a - other.a < 0 ? a - other.a + MOD : a - other.a, true);
	}
	constexpr modint operator*(const modint& other)const
	{
		return modint(imod(a * other.a, MOD), true);
	}
	constexpr modint operator+=(const modint& other)
	{
		a = a + other.a >= MOD ? a + other.a - MOD : a + other.a;
		//return modint(a, true);
		return *this;
	}
	constexpr modint operator-=(const modint& other)
	{
		a = a - other.a < 0 ? a - other.a + MOD : a - other.a;
		//return modint(a, true);
		return *this;
	}
	constexpr modint operator*=(const modint& other)
	{
		a = imod(a * other.a, MOD);
		//return modint(a, true);
		return *this;
	}
	constexpr modint operator+()const
	{
		return *this;
	}
	constexpr modint operator-()const
	{
		return modint(MOD - a >= MOD ? -a : MOD - a, true);
	}
	constexpr modint& operator++()
	{
		*this += 1;
		return *this;
	}
	constexpr modint operator++(int)
	{
		auto tmp = *this;
		*this += 1;
		return tmp;
	}
	constexpr modint& operator--()
	{
		*this -= 1;
		return *this;
	}
	constexpr modint operator--(int)
	{
		auto tmp = *this;
		*this -= 1;
		return tmp;
	}
	constexpr modint operator~()const
	{
		return m_pow<MOD>(*this, phi - 1);
	}
	constexpr modint& operator=(const modint& other)
	{
		a = other.a;
		return *this;
	}
	constexpr operator long long()const
	{
		return a;
	}
	constexpr explicit operator int()const
	{
		return (int)a;
	}
	constexpr modint(long long a_) :a(imod(a_, mod)) {}
	constexpr modint() : a(0) {}
	static constexpr long long mod = MOD;
private:
	static constexpr long long e_phi() {
		//無効な値は無視
		static_assert(MOD >= 2, "MODの値は2以上にしてください");
		//オイラー関数Φ(mod)を計算する
		long long res = MOD, tmp = MOD;
		for (LL i = 2; i * i <= MOD; ++i)
		{
			if (MOD % i == 0)
			{
				res = res / i * (i - 1);
				for (; tmp % i == 0; tmp /= i);
			}
		}
		if (tmp != 1)res = res / tmp * (tmp - 1);
		return res;
	}
public:
	static constexpr long long phi = modint<MOD>::e_phi();
private:
	//static long long e_phi;
	long long a;
	constexpr modint(long long a_, bool) : a(a_) {}
};



//mintの累乗
//x^nを計算します
template<long long MOD>
constexpr modint<MOD> m_pow(modint<MOD> x, long long n)
{
	modint<MOD> res = 1;
	while (n > 0)
	{
		if (n & 1)res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}



