//内部で使用する関数
//arrをFFTする
//arr.size() == (1 << logN)
//rootは(1 << logN)乗すると1になる数で、
//roots[i]はrootのi乗(roots.size() == 1 << logN)
template <typename G>
vector<G> FFTraw(vector<G>arr, int logN, const vector<G>& roots) {
	int N = 1 << logN;
	assert(arr.size() == N);
	vector<G>res[2];
	res[0].resize(N);
	res[1].resize(N);
	for (int i = 0; i < N; ++i) {
		int num = 0;
		for (int b = 0; b < logN; ++b) {
			num <<= 1;
			if (i & (1 << b))num++;
		}
		res[0][i] = (arr[num]);
	}
	//for (int i = 0; i < N; ++i)arr[i] = res[i];
	for (LL i = 0; i < logN; ++i) {
		for (int dex = 0; dex < N; ++dex) {
			int mot = dex ^ (1 << i);
			int lef = min(mot, dex);
			int rht = max(mot, dex);
			res[(i + 1) & 1][dex] = res[i & 1][lef] + res[i & 1][rht] * roots[((LL)dex << (logN - i - 1)) % N];
		}
		//for (int i = 0; i < N; ++i)arr[i] = res[i];
	}
	return res[logN & 1];
}

