    ios::sync_with_stdio(false);
    istream& in(cin);
    ostream& out(cout);
    int n;
    in>>n;
    if(n==2) return cout<<-1<<endl,0;
    heap<100000,int> hp;
    vector<int> a(n),c(n);
    for(auto&i:a) in>>i,--c[--i];
    fr(i,n) hp.push(i,c[i]);
    vector<int> ans(n-3);
    set<int> st;
    fr(i,n) st.insert(i);
    int ng=-1;
    fr(i,n-3){
        int j=hp.top();
        //cout<<j<<" "<<-hp.pri(j)<<endl;
        if(-hp.pri(j)==n-1-i){
            ans[i]=j;
            hp.pop();
            hp.push(a[j],hp.pri(j)+1);
            st.erase(j);
            ng=a[j];
        }
        else{
            auto it=st.begin();
            j=*it;
            ++it;
            int J=*it;
            if(j==ng) j=J;
            //cout<<i<<"#"<<j<<endl;
            st.erase(j);
            hp.push(j,INT_MIN);
            //cout<<hp.pri(hp.top())<<" & "<<hp.top()<<endl;
            hp.pop();
            ng=a[j];
            ans[i]=j;
            if(hp.pri(a[j])!=INT_MAX) hp.push(a[j],hp.pri(a[j])+1);
            /*fr(k,n) cout<<hp.pri(k)<<" ";
            cout<<endl;*/
        }
    }
    auto it=st.begin();
    vector<int> p(3),P={0,1,2};
    fr(i,3) p[i]=*(it++);
    do{
        if(p[P[0]]==ng) continue;
        if(a[p[P[0]]]==p[P[1]]) continue;
        if(a[p[P[1]]]==p[P[2]]) continue;
        fr(i,3) ans.emplace_back(p[P[i]]);
        break;
    }while(next_permutation(P.begin(),P.end()));
    fr(i,n) cout<<ans[i]+1<<" ";
    cout<<endl;
}

