			kind -= 1;
		}
		bool last_one_kind = (count[last] == 0 && kind == 1);

		if(last_one_kind) {

			int target = -1;
			for(int i = 0; i < n + 1; i++) {
				if(count[i] > 0) {
					target = i;
				}
			}
			assert(target != -1);

			priority_queue<int> tmp;
			while(!rem.empty()) {
				int v = rem.top();
				rem.pop();
				if(-v != target){
					tmp.push(v);
				}
			}
			swap(tmp, rem);

			ans.push_back(target);
			last = target;

			continue;
		}

		int x = (last < n ? xs[last] : n);

		array<int,3> vs;
		for(int i = 0; i < 3; i++) {
			vs[i] = -rem.top();
			rem.pop();
		}

		int used = 0;
		while(used < 3 && (vs[used] == x || vs[used] == last)) {
			used += 1;
		}
		assert(used < 3);

		for(int i = 0; i < 3; i++) {
			if(i != used) {
				rem.push(-vs[i]);
			}
		}

		int v = vs[used];
		ans.push_back(v);
		last = v;
	}

	vector<int> right(rem.size());
	const int rlen = right.size();

	for(int i = 0; i < rlen; i++) {
		right[i] = -rem.top();
		rem.pop();
	}

	sort(right.begin(), right.end());

	while(true) {

		if(right[rlen - 1] != n) {
			if(!next_permutation(right.begin(), right.end())) {
				break;
			}
			continue;
		}

		bool ok = true;
		for(int i = 0; i < rlen; i++) {
			int p = (i == 0) ? last : right[i - 1];
			if(p < n && xs[p] == right[i]) {
				ok = false;
			}
		}

		if(ok) {
			for(int i = 0; i < rlen; i++) {
				ans.push_back(right[i]);
			}
			break;
		}

		if(!next_permutation(right.begin(), right.end())) {
			break;
		}
	}

	if(ans.size() < n) {
		printf("-1\n");
		return 0;
	}

	for(int i = 0; i < n; i++) {
		printf("%d%c", ans[i] + 1, i == n - 1 ? '\n' : ' ');
	}

	return 0;
}

