class Solver {
 public:
  int n;
  vector<int> a;
  Solver(LL n) : n(n), a(n){};

  void solve() {
    vector<int> cnt(n), ans;
    vector<vector<int>> memo(n);
    set<int> rem;
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
      a[i]--;
      cnt[a[i]]++;
      rem.insert(i);
    }
    for (int i = 0; i < n; ++i) {
      memo[cnt[i]].push_back(i);
    }
    for (int i = 0; i < n; ++i) {
      int nxt = -1;
      for (auto p : memo[n - i - 1]) {
        if (cnt[p] == n - i - 1) {
          //assert(nxt == -1);
          nxt = p;
        } else if (cnt[p] > 0) {
          memo[cnt[p]].push_back(p);
        }
      }
      if (nxt != -1) {
        ans.push_back(nxt);
        cnt[a[nxt]]--;
        cnt[nxt] = -1;
        rem.erase(nxt);
      } else {
        if (n == n - 3) {
          set<int> rem2(rem);
          if (ans.size() > 0) {
            rem2.erase(a[ans.back()]);
          }
          vector<int> tmp, pr;
          for (auto x : rem) {
            tmp.push_back(x);
          }
          sort(tmp.begin(), tmp.end());
          for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
              if (j == i) continue;
              pr.push_back(tmp[j]);
            }
            if (a[pr[0]] == pr[1] && a[pr[1]] == pr[0]) {
              if (rem2.count(tmp[i])) rem2.erase(tmp[i]);
            }
          }
          int nxt = *rem2.begin();
          ans.push_back(nxt);
          cnt[a[nxt]]--;
          cnt[nxt] = -1;
          rem.erase(nxt);
          continue;
        }
        auto it = rem.begin();
        if (ans.size() > 0 && *it == a[ans.back()])
          it++;
        if (it == rem.end()) {
          cout << -1 << endl;
          return;
        }
        int tmp = *it;
        ans.push_back(tmp);
        cnt[a[tmp]]--;
        cnt[tmp] = -1;
        rem.erase(tmp);
      }
    }

    for (int i = 0; i < n; ++i) {
      cout << ans[i] + 1 << ' ';
    }
    cout << endl;
  }
};

