struct segtree_in{
  ll M=1;
  vector<vll> dat;
  segtree_in(ll N, vll num){
    while(M<N) M*=2;
    for(int i=0;i<M*2-1;i++)  dat.push_back(num);
  }
  void update(vll x, int k, int l=0, int r=-1){
    if(r==-1) r = M;
    k+=M-1;
    dat[k] = x;
    while(k>0) {
      k = (k-1)/2;
      dat[k] = (dat[k*2+1][0]>dat[k*2+2][0]?dat[k*2+1]:dat[k*2+2]);
    }
  }
  vll query(int a, int b=-1, int k=0, int l=0, int r=-1){
    if(r==-1) r = M;
    if(b==-1) b = M;
    if(r<=a || b<=l) return vll{-1, 0};
    if(a<=l && r<=b) return dat[k];
    vll A = query(a, b, k*2+1, l, (l+r)/2);
    vll B = query(a, b, k*2+2, (l+r)/2, r);
    return (A[0]>B[0]?A:B);
  }
};
