int main(int argc, char const *argv[]) {
  ll n;std::cin >> n;
  vll a(n+1), uke(n+1, 0), ans;
  re(i, n) {
    std::cin >> a[i+1];
    uke[a[i+1]]++;
  }
  segtree_in segin(n+1, vll{-1, -1});
  set<ll> s;
  rep(i, 1, n+1) {
    segin.update(vll{uke[i], i}, i);
    s.insert(i);
  }

  for(int i=0;i<n;i++){
    vll k = segin.query(1, n+1);
    if(k[0]==n-i){
      std::cout << -1 << '\n';
      while(true) k[1]++;
      return 0;
    }
    ll p;
    if(k[0]==n-1-i&&(i==0||a[ans[i-1]]!=k[1])) p = k[1];
    else {
      auto itr = s.begin();
      if(i!=0&&a[ans[i-1]]==*itr) itr++;
      p = *itr;
    }
    segin.update(vll{-1, p}, p);
    if(i>0) {
      ll to = a[ans[i-1]];
      uke[to]--;
      vll g = segin.query(to, to+1);
      segin.update(vll{g[0]-1, to}, to);
    }
    ans.push_back(p);
    s.erase(p);
  }
  re(i, n) std::cout << ans[i] << (i==n-1?"\n":" ");
  return 0;
}

