bool dfs(int n, int now, const vi &a, set<int> &st, vi &res) {
  //cout << now << endl;
  //printv(res);
  //if(now == n) return true;

  bool ok = false;
  for(auto &e: st) {
    if(now == -1 || a[now] != e) {
      res.push_back(e+1);
      if(SZ(res) == n) return true;
      st.erase(e);
      bool tmp = dfs(n, e, a, st, res);
      if(tmp) {
        ok = true;
        break;
      } else {
        st.insert(e);
        res.pop_back();
      }
    }
  }
  return ok;
}

