int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    vector<int> ng(N);
    // (x, j) -> jはx個のngをもつ
    set<P, greater<P>> ngs;
    set<int> cards;
    for(int i = 0; i < N; i++) {
        int a;
        cin >> a;
        a--;
        A[i] = a;
        ng[a]++;
        cards.insert(i);
    }
    for(int i = 0; i < N; i++) {
        ngs.insert({ng[i], i});
    }
    vector<int> ans;
    // 最後のカード
    int l = -1;
    for(int n = N - 1; n >= 0; n--) {
        P p = *ngs.begin();
        int j;
        if(p.first == n) { // 先端にしないといけないやつ
            j = p.second;
        } else {
            bool cycle_flag = false;
            if(n == 2) {
                // 循環が起きそうなら排除
                for(int a : cards) {
                    for(int b : cards) {
                        if(A[a] == b && A[b] == a) {
                            for(int i : {a, b}) {
                                if(l < 0 || A[l] != i) {
                                    j = i;
                                    break;
                                }
                            }
                            cycle_flag = true;
                        }
                    }
                }
            }
            if(!cycle_flag) { // 先端を辞書順最小で決める
                for(int i : cards) {
                    if(l < 0 || A[l] != i) {
                        j = i;
                        break;
                    }
                }
            }
        }
        // カードjを取り出す
        ans.push_back(j);
        cards.erase(j);
        ngs.erase({ng[j], j});
        int k = A[j];
        if(ngs.count({ng[k], k})) {
            ngs.erase({ng[k], k});
            ng[k]--;
            ngs.insert({ng[k], k});
        }
        l = j;
    }

    // validate
    for(int i = 0; i < N - 1; i++) {
        if(A[ans[i]] == ans[i + 1]) {
            cout << -1 << endl;
            return 0;
        }
    }

    string delim = "";
    for(int a : ans) {
        cout << delim << a + 1;
        delim = " ";
    }
    return 0;
}

