bool check(vector<int> candidate) {
    for (int i = 1; i < n; ++i) {
        if (candidate[i] == a[candidate[i - 1]])
            return false;
    }

    return true;
}


void solve() {
    if (n == 2) {
        puts("-1");
        return;
    }

    for (int i = 1; i <= n; ++i) {
        degIn[i] = n - 1;
    }

    for (int i = 1; i <= n; ++i) {
        --degIn[a[i]];
    }

    set<int> lexiOrder;
    set<pair<int, int> > degOrder;
    for (int i = 1; i <= n; ++i) {
        lexiOrder.insert(i);
        degOrder.insert({degIn[i], i});
    }

    int offset = 0;
    vector<int> res;
    while (lexiOrder.size() > 3) {
        auto minDegIn = degOrder.begin();
        auto seMinDegIn = degOrder.begin();
        ++seMinDegIn;

        int cur;
        if (minDegIn->first - offset == 0) {
            res.push_back(minDegIn->second);
            cur = res.back();
            degOrder.erase(minDegIn);
            lexiOrder.erase(res.back());
        }
        else {
            if (res.empty() || *lexiOrder.begin() != a[res.back()]) {
                cur = *lexiOrder.begin();
            }
            else {
                auto tmp = lexiOrder.begin();
                ++tmp;
                cur = *tmp;
            }

            res.push_back(cur);
            lexiOrder.erase(cur);
            degOrder.erase({degIn[cur], cur});
        }

        degOrder.erase({degIn[a[cur]], a[cur]});
        ++degIn[a[cur]];
        ++offset;
        degOrder.insert({degIn[a[cur]], a[cur]});
    }

    for (auto x : lexiOrder) {
        res.push_back(x);
    }

    while (!check(res)) {
        next_permutation(res.end() - 3, res.end());
    }

    for (auto x : res)
        cout << x << ' ';
    cout << '\n';
}


