		}
		bucket[indeg[u]].erase(u);
		if (bucket[indeg[nxt[u]]--].erase(nxt[u]))
			bucket[indeg[nxt[u]]].insert(nxt[u]);
		q.push(u);
		prev = u;
	}

	if (!flag) cout << -1;
	else while (!q.empty()) cout << q.front() + 1 << ' ', q.pop();
}

