        cnt[a[i]].first++;
    }
    for (int i = 0;i < n;++i) cnt[i].second = i;
    for (int i = 0;i < n;++i) if (cnt[i].first == 0) cnt[i].first = -1000;
    SegmentTree seg(cnt);
    if (n == 2) {
        cout << -1 << endl;
        return 0;
    }
    P m = seg.getmax(0,n);
    set<int> st;
    for (int i = 0;i < n;++i) st.insert(i);
    vector<int> ans(n);
    if (m.first == n-1) {
        st.erase(m.second);
        ans[0] = m.second;
        seg.update(m.second,P(-1000,m.second));
        int d = seg.getmax(a[m.second],a[m.second]+1).first-1;
        if (d == 0) d = -1000;
        seg.update(a[m.second],P(d,a[m.second]));
        // seg.update(a[m.second],P(seg.getmax(a[m.second],a[m.second]+1).first-1,a[m.second]));
        m = seg.getmax(0,n);
    } else {
        int c = *st.begin();
        ans[0] = c;
        st.erase(c);
        int d = seg.getmax(a[c],a[c]+1).first-1;
        if (d == 0) d = -1000;
        seg.update(a[c],P(d,a[c]));
        m = seg.getmax(0,n);
    }
    // p_ary(ans,0,n);
    // cout << m.first << " " << m.second << endl;
    // for (int i = 0;i < n;++i) cout << seg.getmax(i,i+1).first << " ";
    // cout << endl;
    for (int i = 1;i < n;++i) {
        if (m.first == n-i-2 && a[ans[i-1] != m.second]) {
            st.erase(m.second);
            ans[i] = m.second;
            seg.update(m.second,P(-100000,m.second));
            int d = seg.getmax(a[m.second],a[m.second]+1).first-1;
            if (d == 0) d = -1000;
            seg.update(a[m.second],P(d,a[m.second]));
            // seg.update(a[m.second],P(seg.getmax(a[m.second],a[m.second]+1).first-1,a[m.second]));
            m = seg.getmax(0,n);
        } else {
            auto it = st.begin();
            if (a[ans[i-1]] == *it) ++it;
            int c = *it;
            ans[i] = c;
            st.erase(c);
            int d = seg.getmax(a[c],a[c]+1).first-1;
            if (d == 0) d = -1000;
            seg.update(a[c],P(d,a[c]));
            // seg.update(a[c],P(seg.getmax(a[c],a[c]+1).first-1,a[c]));
            m = seg.getmax(0,n);
        }
    }
    // p_ary(ans,0,n);
    for (int i = 0;i < n;++i) cout << ans[i]+1 << " \n"[i == n-1];
}

