int main(void){
	int n;
	cin >> n;
	vector<int> a(n);
	rep(i, n) cin >> a[i], a[i]--;

	set<int> unused;
	rep(i, n) unused.insert(i);

	vector<int> in(n);
	rep(i, n) in[a[i]]++;

	using pii = pair<int, int>;
	set<pii> in_degree;

	rep(i, n) in_degree.insert(pii(in[i], i));

	vector<int> b;

	auto opr = [&](int idx){
		if (unused.find(a[idx]) != end(unused)) {
			in_degree.erase(pii(in[a[idx]], a[idx]));
			in[a[idx]]--;
			in_degree.insert(pii(in[a[idx]], a[idx]));
		}
		unused.erase(idx);
		in_degree.erase(pii(in[idx], idx));
	};

	rep(i, n){
		const auto required = *prev(end(in_degree));

		if(required.first == n - 1 - i) {
			b.push_back(required.second);
			opr(required.second);
			continue;
		}

		auto it = begin(unused);
		const int ban = (b.empty() ? -1 : a[b.back()]);

		if(*it != ban) {
			b.push_back(*it);
			opr(*it);
		} else {
			auto it2 = next(it);
			b.push_back(*it2);
			opr(*it2);
		}
	}


	bool ok = true;
	rep(i, n - 1) if(a[b[i]] == b[i + 1]) ok = false;

	if(ok) {
		rep(i, n) cout << (i?" ":"") << b[i] + 1;
		cout << endl;
	} else {
		cout << -1 << endl;
	}


	return 0;
}

