    MaxSegTree hate(n);
    vector<int> a(n);
    rep(i,n){
        cin >>a[i];
        --a[i];
        hate.add(a[i],1);
    }

    priority_queue<int, vector<int>, greater<int>> pq;
    rep(i,n) pq.push(i);

    int pre = -1;
    vector<int> ans(n,-1);
    rep(i,n){
        vector<int> buf;
        while(!pq.empty()){
            int x = pq.top();
            pq.pop();

            hate.add(a[x],-1);
            hate.add(x,-INF);

            // dbg(hate.query(0,n));
            // dbg(n-1-i);
            if(hate.query(0,n) >= n-i || (pre!=-1 && a[pre]==x)){
                buf.pb(x);
                hate.add(a[x],1);
                hate.add(x,INF);
                continue;
            }

            // dbg(i);dbg(x+1);
            pre = x;
            ans[i] = x;
            break;
        }
        if(ans[i]==-1){
            cout << -1 << "\n";
            return 0;
        }

        for(int j:buf) pq.push(j);
    }

    rep(i,n) cout << ans[i]+1 << " \n"[i==n-1];
    return 0;
}

