        if (i && p[b[i - 1]] == b[i]) {
            b[i] = *next(st.begin());
        }
        st.erase(b[i]);
    }
    for (int i = max(0, n - 4); i < n; i++) {
        b[i] = *st.begin();
        st.erase(b[i]);
    }
    do {
        bool ok = true;
        for (int i = max(0, n - 10); i < n - 1; i++) {
            if (p[b[i]] == b[i + 1]) ok = false;
        }
        if (!ok) continue;
        for (int d: b) {
            pr.write(d + 1);
            pr.write(' ');
        }
        pr.writeln();
        return 0;
    } while (next_permutation(b.end() - l, b.end()));
    assert(false);
    return 0;
}

