  Node(int v = -1) {
    this->v = v;
  }
};

int N;
vector<int> A;

vector<int> find_path(int v, vector<int> &path, vector<bool> &visited) {
  if (visited[v]) return vector<int>();
  visited[v] = true;
  path.push_back(v);

  if (path.size() == N) {
    return path;
  }

  for (int u = 0; u < N; ++u) {
    if (A[v] == u) continue;

    vector<int> ret = find_path(u, path, visited);

    if (ret.size() == N) {
      return ret;
    }
  }

  visited[v] = false;
  path.pop_back();

  return path;
}

int main() {
  cin >> N;
  int a;
  map<int, int> counter;

  for (int i = 0; i < N; ++i) {
    cin >> a;
    ++counter[a - 1];
    A.push_back(a - 1);

    if (counter[a - 1] == N - 1) {
      assert(false);
    }
  }

  vector<bool> visited(N, false);
  vector<int> ans;

  for (int v = 0; v < N; ++v) {
    ans = find_path(v, ans, visited);

    if (ans.size() == N) break;
  }

  if (ans.size() != N) {
    cout << -1 << endl;
    return 0;
  }

  for (int i = 0; i < ans.size(); ++i) {
    cout << ans[i] + 1;

    if (i < N - 1) {
      cout << " ";
    }
  }

  cout << endl;

  return 0;
}

