int N, a[101010];
int cnt[101010];
int ans[101010];
bool used[101010];

void solve() {
    int nouse = -1;
    std::priority_queue<int, vector<int>, greater<int>> que;
    SegmentTree<int> seg(N, [](int a, int b) { return max(a, b); }, 0);
    FOR(N) {
        que.push(i);
        cnt[a[i]]++;
    }
    FOR(N) {
        seg.set(i, cnt[i]);
    }
    seg.build();
    if (N == 2) {
        cout << -1 << endl;
        return;
    }
    FOR(i, 0, N) {
        int t1;
        t1 = que.top();
        //cout << t1 << endl;
        while (used[t1] == true) {
            que.pop();
            t1 = que.top();
        }
        que.pop();
        int t2 = -1;
        if (i != N - 1) {
            //cout << t2 << endl;
            t2 = que.top();
            while (used[t2] == true) {
                que.pop();
                t2 = que.top();
                if (que.empty())
                    break;
            }
        }
        cerr << nouse << " " << t1 << " " << t2 << endl;
        if (i < N - 1 && seg.query(0, N) == N - i - 1) {
            que.push(t1);
            int tmp;
            FOR(n, 0, N) {
                if (seg[n] == N - i - 1) {
                    tmp = n;
                    break;
                }
            }
            ans[i] = tmp;
            int n = tmp;
            seg.update(a[n], seg[a[n]] - 1);
            seg.update(n, 0);
            used[n] = true;
            nouse = a[n];
        } else {
            if (nouse != t1) {
                ans[i] = t1;
            } else {
                ans[i] = t2;
                que.pop();
                que.push(t1);
            }
            int n = ans[i];
            seg.update(a[n], seg[a[n]] - 1);
            seg.update(n, 0);
            used[n] = true;
            nouse = a[n];
        }
    }
    FOR(N) {
        cout << ans[i] + 1 << " ";
    }
    cout << endl;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cin >> N;
    FOR(N) {
        cin >> a[i];
        a[i]--;
    }
    solve();
    return 0;
}

