	int n,m;
	int i,j,k;
	int a,b,c;
	cin>>n;
	if(n==2){
		cout<<-1<<endl;
		return 0;
	}
	memset(s,-1,sizeof(s));
	for(i=0;i<n;i++){
		cin>>t[i];
		t[i]--;
		m1[t[i]]++;
		m2[i]=1;
	}
	for(i=0;i<n;i++){
		auto itr=m1.begin();
		if(itr==m1.end())break;
		if(i==n-2){
			itr=m2.begin();
			a=itr->first;
			itr++;
			b=itr->first;
			if(a>b)swap(a,b);
			if(t[a]==b && t[b]==a){
				c=s[n-3];
				for(j=0;j<2;j++){
					for(k=n-1;k>=0;k--){
						if(s[k]==-1)continue;
						swap(s[k],s[k+1]);
						if(t[b]!=s[k+1] && (k==0 || t[s[k-1]]==b)){
							s[k]=b;
						}
					}
					b=a;
				}
				break;
			}
			if(t[b]==a || t[s[n-3]]==a)swap(a,b);
			s[n-2]=a,s[n-1]=b;
			break;
		}
		if(itr->second==1)itr++;
		if((itr->second)==n-i-1){
			s[i]=itr->first;
			m1.erase(itr);
			m2.erase(s[i]);
			if(m1.find(t[s[i]])!=m1.end()){
				m1[t[s[i]]]--;
				if(m1[t[s[i]]]==0)m1.erase(t[s[i]]);
			}
			continue;
		}
		itr=m2.begin();
		if(i>0 && t[s[i-1]]==itr->first)itr++;
		s[i]=itr->first;
		m1.erase(itr->first);
		m2.erase(itr);
		if(m1.find(t[s[i]])!=m1.end()){
			m1[t[s[i]]]--;
			if(m1[t[s[i]]]==0)m1.erase(t[s[i]]);
		}
	}
	for(i=0;i<n;i++){
		if(s[i]!=-1)used[s[i]]=true;
	}
	for(i=0,a=0;i<n;i++){
		if(s[i]!=-1)continue;
		for(;used[a];a++);
		s[i]=a,used[a]=true;
	}
	for(i=0;i<n;i++)s[i]++;
