vector<int> bestFactorial(int ban,vector<int>v) {
  vector<int> ret;

  assert(v.size()<=4 && v.size()>=3);
  do {
    if(v[0]==ban) {
      continue;
    }
    bool isGood = true;
    for(int i=0;i<v.size()-1;++i) {
      if(a[v[i]]==v[i+1]) {
        isGood = false;
        break;
      }
    }
    if(isGood) {
      if(ret.size()==0) {
        ret = v;
      } else {
        ret = min(ret,v);
      }
    }
  } while(next_permutation(v.begin(),v.end()));
  assert(ret.size()!=0);
  return ret;
}

