    uke[a[i+1]]++;
  }
  segtree_in segin(n+1, vll{-1000000000, -1});
  set<ll> s;
  rep(i, 1, n+1) {
    segin.update(vll{uke[i], i}, i);
    s.insert(i);
  }

  if(n==2){
    std::cout << -1 << '\n';
    return 0;
  }
  for(int i=0;i<n;i++){
    vll k = segin.query(1, n+1);
    ll p;
    if(k[0]==(n-1-i)&&(i==0||a[ans[i-1]]!=k[1])) p = k[1];
    else {
      auto itr = s.begin();
      if(i!=0&&a[ans[i-1]]==*itr) itr++;
      p = *itr;
    }
    segin.update(vll{-1000000000, -1}, p);

    if(i>0) {
      ll to = a[ans[i-1]];
      vll g = segin.query(to, to+1);
      segin.update(vll{g[0]-1, to}, to);
    }

    ans.push_back(p);
    s.erase(p);
  }
  re(i, n) std::cout << ans[i] << (i==n-1?"\n":" ");
  return 0;
}

