    REP(i, n) cin >> a[i], a[i]--;
    auto seg = make_segment_tree<pii>([](pii a, pii b) { return max(a, b); }, {-1, -1});
    vector<pii> in_dig(n);
    REP(i, n) {
        in_dig[i].second = i;
        in_dig[a[i]].first++;
    }
    seg.set_by_vector(in_dig);

    set<Int> s;
    REP(i, n) s.insert(i);
    vector<Int> ans;
    Int cur = n;
    REP(_, n) {
        if (cur != n) {
            auto p2 = seg.query(a[cur], a[cur] + 1);
            assert(p2.second == a[cur]);
            seg.update(a[cur], {p2.first - 1, a[cur]});
            seg.update(cur, {-1, cur});
        }
        Int nxt = -1;
        auto p = seg.query(0, n);
        if (p.first == (Int)s.size()) {
            dump(cur, p);
            cout << -1 << endl;
            return 0;
        } else if (p.first == (Int)s.size() - 1 && s.count(p.second)) {
            dump(cur, p);
            nxt = p.second;
        } else if (s.size() == 3) {
            int x = *(next(s.begin(), 0));
            int y = *(next(s.begin(), 1));
            int z = *(next(s.begin(), 2));
            if (a[x] == y && a[y] == x) {
                nxt = a[cur] == x ? y : x;
            } else if (a[y] == z && a[z] == y) {
                nxt = a[cur] == y ? z : y;
            } else if (a[z] == x && a[x] == z) {
                nxt = a[cur] == x ? z : x;
            } else {
                nxt = a[cur] == *s.begin() ? *next(s.begin()) : *s.begin();
            }
        } else {
            if (a[cur] == *s.begin()) {
                if (s.size() <= 1) no();
                nxt = *next(s.begin());
            } else {
                nxt = *s.begin();
            }
        }
        if (cur == nxt || !s.count(nxt) || nxt == a[cur]) {
            cout << -1 << endl;
            return 0;
        }
        cur = nxt;
        ans.push_back(cur);
        s.erase(cur);
    }
    dump(ans);
    assert(s.size() == 0 && ans.size() == n);
    for (Int x : ans) cout << x + 1 << " ";
    cout << endl;
}

