struct MaxSegTree{
    int n; vector<ll> dat;
    // 初期化
    MaxSegTree(int _n){
        n=1;
        while(n<_n) n*=2;
        dat=vector<ll>(2*n-1,0);
    }

    void add(int k, ll a){
        k+=n-1;
        dat[k]+=a;
        //更新
        while(k>0){
            k=(k-1)/2;
            dat[k]=max(dat[2*k+1],dat[2*k+2]);
        }
    }
    // 内部的に投げられるクエリ
    ll _query(int a, int b, int k, int l, int r){
        if(r<=a || b<=l) return 0;

        if(a<=l && r<=b) return dat[k];

        ll vl=_query(a,b,2*k+1,l,(l+r)/2);
        ll vr=_query(a,b,2*k+2,(l+r)/2,r);
        return max(vl,vr);
    }
    // [a,b)
    ll query(int a, int b){
        return _query(a,b,0,0,n);
    }
};

const int INF = 191919;

int main(){
    int n;
    cin >>n;

    MaxSegTree hate(n);
    vector<int> a(n);
    rep(i,n){
        cin >>a[i];
        --a[i];
        hate.add(a[i],1);
    }

    priority_queue<int, vector<int>, greater<int>> pq;
    rep(i,n) pq.push(i);

    int pre = -1;
    vector<int> ans(n,-1);
    int idx = 0;
    rep(i,n-5){
        vector<int> buf;
        while(!pq.empty()){
            int x = pq.top();
            pq.pop();

            hate.add(a[x],-1);
            hate.add(x,-INF);

            // dbg(hate.query(0,n));
            // dbg(n-1-i);
            if(hate.query(0,n) >= n-1-i || (pre!=-1 && a[pre]==x)){
                buf.pb(x);
                hate.add(a[x],1);
                hate.add(x,INF);
                continue;
            }

            // dbg(i);dbg(x+1);
            pre = x;
            ans[idx] = x;
            break;
        }
        if(ans[idx]==-1){

            cout << -1 << "\n";
            return 0;
        }

        for(int j:buf) pq.push(j);
        ++idx;
    }

    vector<int> rem;
    while(!pq.empty()){
        rem.pb(pq.top());
        pq.pop();
    }

    bool found = false;
    do{
        bool ok = true;
        int pp = pre;
        for(int i:rem){
            if(pp!=-1 && a[pp] == i){
                ok = false;
                break;
            }
            pp = i;
        }

        if(ok){
            found = true;
            for(int i:rem) ans[idx++] = i;
            break;
        }
    }while(next_permutation(all(rem)));

    if(!found) cout << -1 << "\n";
    else rep(i,n) cout << ans[i]+1 << " \n"[i==n-1];
    return 0;
}

