    };
    sort(res.begin() + res.size() - 3, res.end());
    while(!check()) {
      assert(next_permutation(res.begin() + n - 3, res.end()));
    }
  } else {
    res.push_back(c);
    while(cur.size()) {
      int c = *cur.begin();
      if(a[res.back()] == c) c = *next(cur.begin());
      cur.erase(c);
      res.push_back(c);
