            ng[t]++;
        }
        SegTree<int> ngt(N, 0);
        SegTree<int> exist(N, 0);
        for(int i=0;i<N;i++){
            ngt.update(i, ng[i]);
            exist.update(i, 1);
        }
        if(N == 2){
            cout << -1 << endl;
            continue;
        }
        int prev = -1;
        vector<int> res;
        for(int i=0;i<N;i++){
            int sel = -1;
            if(i == N-3){
                vector<int> rest;
                for(int j=0;j<N;j++) if(exist.get(j, j+1) == 1) rest.push_back(j);
                for(int j=0;j<3;j++){
                    for(int k=j+1;k<3;k++){
                        if(b[rest[j]] == rest[k] && b[rest[k]] == rest[j]){
                            sel = (prev != rest[j] ? rest[j] : rest[k]);
                        }
                    }
                }
            }
            if(sel == -1){
                if(i != N-1 && ngt.get(0, N) == N-1-i){
