                        if(exist.get(0, mid) == 1) R = mid;
                        else L = mid;
                    }
                    sel = R-1;
                    if(del) exist.update(prev, 1);
                }
            }
            ngt.update(sel, 0);
            ng[b[sel]]--;
            ngt.update(b[sel], ng[b[sel]]);
            exist.update(sel, 0);
            prev = b[sel];
            res.push_back(sel+1);
        }
