auto solve_k(ll n, const VL& v, ll f) {
	dump(f);
	bool ok = true;
	priority_queue<ll, VL, std::greater<ll>> q;
	FOR(i, 0, n)if (i != f) { q.emplace(i); }
	list<ll> ans{f};
	ll now = f;
	REP(_, n - 1) {
		ll t = q.top();
		if (v[now] == t) {
			if (q.size() == 1) {
				ok = false;
				break;
			}
			q.pop();
			ll t2 = q.top();
			now = t2;
			ans.emplace_back(t2);
			q.pop();
			q.emplace(t);
		} else {
			now = t;
			ans.emplace_back(now);
			q.pop();
		}
	}
	if (ok) { return ans; }
	ll t = q.top();
	if (v[t] != f) {
		ans.emplace_front(t);
		return ans;
	}
	return list<ll>();
}

auto solve(ll n, const VL& v) {
	REP(i, 10)if (i < n) {
		auto ans = solve_k(n, v, i);
		if (!ans.empty()) { return ans; }
	}
	return list<ll>();
}

