int cnt[128000];
set<pair<int,int>> s;
set<int> nums;

void choose(int pos, int v) {
  res[pos] = v;
  if (nums.find(a[v-1]) != nums.end()) {
    auto it = s.find(make_pair(cnt[a[v-1]], a[v-1]));
    pair<int,int> pa = *it;
    s.erase(it);
    pa.first -= 1;
    cnt[a[v-1]] -= 1;
    s.insert(pa);
  }
  nums.erase(v);
  s.erase(make_pair(cnt[v], v));
}

void rev_choose(int v) {
  if (nums.find(a[v-1]) != nums.end()) {
    auto it = s.find(make_pair(cnt[a[v-1]], a[v-1]));
    pair<int,int> pa = *it;
    s.erase(it);
    pa.first += 1;
    cnt[a[v-1]] += 1;
    s.insert(pa);
  }
  nums.insert(v);
  s.emplace(cnt[v], v);
}

bool solve(long long N, int p) {
  // REP(i,N) cout << res[i] << " \n"[i == N - 1];
  if (p == N) {
    REP(i,N) cout << res[i] << " \n"[i == N - 1];
    return true;
  }

  auto it = prev(s.end());
  if (it->first == N - p - 1 && (p == 0 || a[res[p-1]-1] != it->second)) {
    int ch = it->second;
    choose(p, ch);
    bool nex = solve(N, p + 1);
    if (nex) return true;
    rev_choose(ch);
  }

  auto top = *nums.begin();
  if (p == 0 || a[res[p-1]-1] != top) {
    choose(p, top);
    bool nex = solve(N, p + 1);
    if (nex) return true;
    rev_choose(top);
  }

  if (nums.size() <= 1) return false;

  auto sec = *next(nums.begin());

  if (p == 0 || a[res[p-1]-1] != sec) {
    choose(p, sec);
    bool nex = solve(N, p + 1);
    if (nex) return true;
    rev_choose(sec);
  }

  if (nums.size() <= 2) return false;

  auto thi = *next(next(nums.begin()));

  if (p == 0 || a[res[p-1]-1] != thi) {
    choose(p, thi);
    bool nex = solve(N, p + 1);
    if (nex) return true;
    rev_choose(thi);
  }

  return false;

