void solve(ll N,vector<ll> &ans,vector<ll> &A){
  for(int i=0;i<N;i++){ans[i]=i;}
  do{
    bool jd=true;
    for(int i=0;i+1<N;i++){
      jd&=A[ans[i]]!=ans[i+1];
    }
    if(jd){break;}
  }while(next_permutation(ans.begin(),ans.end()));
}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  ll N;
  cin>>N;
  vector<ll> A(N),ans(N,-1),cnt(N,0);
  set<ll> S;
  priority_queue<pll> Q;
  cin>>A;
  for(auto &I:A){I--; cnt[I]++; Q.push({cnt[I],I});}
  for(int i=0;i<N;i++){S.insert(i);}
  auto answer=[&](int i,int a){ans[i]=a; cnt[A[a]]--; S.erase(a);};
  if(N<=8){
    solve(N,ans,A);
    bool jd=true;
    for(int i=0;i+1<N;i++){
      jd&=A[ans[i]]!=ans[i+1];
    }
    for(auto &I:ans){I++;}
    if(jd){cout<<ans<<endl;}
    else{cout<<-1<<endl;}
    return 0;
  }
  for(int i=0;i+5<N;i++){
    while(!Q.empty()){
      pll u=Q.top();
      if(cnt[u.S]!=u.F || S.count(u.S)==0){Q.pop(); continue;}
      break;
    }
    if(!Q.empty() && cnt[Q.top().S]==N-i-1){
      answer(i,Q.top().S);
      for(int j=i+1;j<N;j++){
        answer(j,*S.lower_bound(-1LL));
      }
      for(auto &I:ans){I++;}
      cout<<ans<<endl;
      return 0;
    }
    ll k=*S.lower_bound(-1LL);
    if(i==0 || k!=A[ans[i-1]]){
      answer(i,k);
    }
    else{
      S.erase(k);
      ll k2=*S.lower_bound(-1LL);
      answer(i,k2);
      S.insert(k);
    }
  }
  vector<ll> rem;
  for(auto &I:S){rem.push_back(I);}
  assert(rem.size()==5);
  ll C=N-5;
  do{
    for(int i=0;i<5;i++){
      ans[C+i]=rem[i];
    }
    bool jd=true;
    for(int i=max(0LL,N-10);i+1<N;i++){
      jd&=A[ans[i]]!=ans[i+1];
    }
    if(jd){break;}
  }while(next_permutation(rem.begin(),rem.end()));
  bool jd=true;
  for(int i=0;i+1<N;i++){
    jd&=A[ans[i]]!=ans[i+1];
  }
  assert(jd);
  for(auto &I:ans){I++;}
  cout<<ans<<endl;

  return 0;
}

