#include "bits/stdc++.h"
using namespace std;

pair<int, int> INF = { -1000000000, -1 };

class SegmentTree {
private:
	vector<pair<int, int> > Node;
public:
	SegmentTree(vector<int>& V) : Node(V.size() * 2, INF) {
		for (int i = 0; i < V.size(); i++) {
			Node[i + V.size()] = { V[i], i };
		}
		for (int i = V.size() - 1; i >= 1; i--) {
			Node[i] = max(Node[i * 2], Node[i * 2 + 1]);
		}
	}
	void Update(int K, int X) {
		K += Node.size() / 2;
		Node[K].first = X;
		while (K >= 2) {
			K >>= 1;
			Node[K] = max(Node[K * 2], Node[K * 2 + 1]);
		}
	}
	pair<int, int> Query(int L, int R) {
		L += Node.size() / 2, R += Node.size() / 2;
		pair<int, int> ANS = INF;
		while (L < R) {
			if (L & 1) {
				ANS = max(ANS, Node[L]);
				L++;
			}
			if (R & 1) {
				ANS = max(ANS, Node[R - 1]);
				R--;
			}
			L >>= 1, R >>= 1;
		}
		return ANS;
	}
};

int main() {
