	for (int i = N - 1; i >= 0; i--) ST.push(i);
	for (int i = 0; i < N - 3; i++) {
		pair<int, int> P = Seg.Query(0, N);
		if (P.first == N - i - 1) {
			ANS.push_back(P.second);
			B[P.second] = false;
			Seg.Update(P.second, -1);
			C[A[P.second]]--;
			Seg.Update(A[P.second], C[A[P.second]]);
		}
		else {
			while (1) {
				if (B[ST.top()]) break;
				else ST.pop();
			}
			if (i == 0 || A[ANS[i - 1]] != ST.top()) {
				ANS.push_back(ST.top());
				B[ST.top()] = false;
				Seg.Update(ST.top(), -1);
				C[A[ST.top()]]--;
				Seg.Update(A[ST.top()], C[A[ST.top()]]);
				ST.pop();
			}
			else {
				int X = ST.top();
				ST.pop();
				while (1) {
					if (B[ST.top()]) break;
