typedef pair<ll,int> P;
ll const INF = INT64_MAX>>3;
struct SegmentTree {
private:
    int n;
    vector<P> node;
public:
    SegmentTree(vector<P> v) {
        int sz = v.size();
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2*n-1,P(INF,-1));
        for (int i = 0;i < sz;++i) node[i+n-1] = v[i];
        for (int i = n-2;i >= 0;--i) node[i] = max(node[2*i+1],node[2*i+2]);
    }

    void update(int x,P val) {
        x += (n-1);
        node[x] = val;
        while (x > 0) {
            x = (x-1)/2;
            node[x] = max(node[2*x+1],node[2*x+2]);
        }
    }

    P getmax(int a,int b,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return P(-INF,-1);
        if (a <= l && r <= b) return node[k];
        P vl = getmax(a,b,2*k+1,l,(l+r)/2);
        P vr = getmax(a,b,2*k+2,(l+r)/2,r);
        return max(vl,vr);
    }
};

