#define REP(i, n) for (int i = 0; (i) < (int)(n); ++ (i))
#define REP3(i, m, n) for (int i = (m); (i) < (int)(n); ++ (i))
#define REP_R(i, n) for (int i = (int)(n) - 1; (i) >= 0; -- (i))
#define REP3R(i, m, n) for (int i = (int)(n) - 1; (i) >= (int)(m); -- (i))
#define ALL(x) std::begin(x), std::end(x)
using namespace std;

vector<int> solve(int n, const vector<int> & a) {
    if (n == 2) return vector<int>();
    int first = -1;
    if (count(ALL(a), a[0]) == n - 1) first = a[0];
    if (count(ALL(a), a[1]) == n - 1) first = a[1];
    vector<int> b;
    set<int> available;
    vector<int> cur;
    REP (i, n) {
        available.insert(i);
    }
    REP (init, n) {
        if (first != -1 and init != first) continue;
        available.erase(init);
        cur.push_back(init);
        ([go = [&](auto go) {
            if (available.empty()) {
                b = cur;
                return;
            }
            for (auto it = available.begin(); it != available.end(); ++ it) {
                int i = *it;
                if (a[cur.back()] == i) continue;
                available.erase(it);
                cur.push_back(i);
                go(go);
                if (not b.empty()) break;
                cur.pop_back();
                it = available.insert(i).first;
            }
        }]() { return go(go); })();
        cur.pop_back();
        available.insert(init);
        if (not b.empty()) break;
    }
    assert (not b.empty());
    return b;
}

