        scanf("%d", &a[i]);
        -- a[i];
    }
    auto b = solve(n, a);
    if (b.empty()) {
        printf("%d\n", -1);
    } else {
        REP (i, n) {
            printf("%d%c", b[i] + 1, i + 1 < n ? ' ' : '\n');
        }
    }
    return 0;
}

