int res[128000];

bool solve(long long N, const std::vector<long long> &a, int p) {
  // REP(i,N) cout << res[i] << " \n"[i == N - 1];
  if (p == N) {
    REP(i,N) cout << res[i] << " \n"[i == N - 1];
    return true;
  }
  int top = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != top) {
    res[p] = top;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
  }

  if (que.empty()) return false;
  int sec = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != sec) {
    que.push(top);
    res[p] = sec;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
    que.pop();
  }

  if (que.empty()) return false;
  int thi = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != thi) {
    que.push(top);
    que.push(sec);
    res[p] = sec;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
    que.pop();
    que.pop();
  }

  if (que.empty()) return false;
  int fou = que.top();
  que.pop();
  if (p == 0 || a[res[p-1]-1] != thi) {
    que.push(top);
    que.push(sec);
    que.push(thi);
    res[p] = sec;
    bool nex = solve(N, a, p + 1);
    if (nex) return true;
    que.pop();
    que.pop();
    que.pop();
  }

  que.push(top);
  que.push(sec);
  que.push(thi);
  que.push(fou);
  return false;
}

