bool check(int n, vector<int> a, vector<int> p) {
    for (int i = 1; i < n; ++i) {
        if (p[i + 1] == a[p[i]])
            return false;
    }

    return true;
}


vector<int> bruteforce(int n, vector<int> p, vector<int> a, int offset=2) {
    vector<int> res(n + 1, n);

    while (true) {
        // PR(p, n);
        // debug(check(n, a, p));
        //  debug(offset)
        if (check(n, a, p))
            res = min(res, p);
        if (!next_permutation(p.begin() + offset, p.end()))
            break;
    }

    if (res == vector<int>(n + 1, n))
        return vector<int>(1, -1);
    return res;
}


