vector<int> solve(int n, vector<int> a) {

    set<int> s;
    for (int i = 1; i <= n; ++i)
        s.insert(i);

    vector<int> res(1, 1);
    s.erase(1);
    for (int i = 1; i < n - 5; ++i) {
        if (*s.begin() != a[res.back()]) {
            res.push_back(*s.begin());
        }
        else {
            auto it = s.begin();
            ++it;
            res.push_back(*it);
        }
        s.erase(res.back());
    }
    // PR0(res, res.size())

    vector<int> p;
    for (auto x : s)
        p.push_back(x);
    p.insert(p.begin(), res.back());
    p.insert(p.begin(), 0);
    // PR0(p, p.size())

    vector<int> tmp = bruteforce(6, p, a);
    if (tmp == vector<int>(1, -1))
        return tmp;
    tmp.erase(tmp.begin(), tmp.begin()+2);
    for (auto x : tmp) {
        if (x != 0)
            res.push_back(x);
    }

    return res;
}


