void solve() {
  set<long long> st;
  for(int i = 0; i < n; ++i) --v[i];
  for(int i = 0; i < n; ++i) st.insert(i);
  for(int i = 0; i < n; ++i) res.push_back(i);
  for(int i = 0; i < n; ++i) ++mp[v[i] - 1];
  for(int i = 0; i < n; ++i) {
    if(mp.size() == 1) {
