        p = now.first;
        res.push_back(p);
      }
      for(int j = i; j < n; ++j)
        if(j != p) res.push_back(j);
      return;
    }
    auto it = st.begin();
    if(v[res.back()] == *it) ++it;
    res.push_back(*it);
    --mp[v[*it] - 1];
    st.erase(*it);
  }
