          if (st.find(que.top().second) == st.end()) {
            // already removed
            que.pop();
            continue;
          }
          b[i] = que.top().second;
          que.pop();
          break;
        }
        if (b[i] == -1) {
          auto it = st.begin();
          if (i > 0 && a[b[i-1]] == *it) {
            ++it;
          }
          b[i] = *it;
        }
        st.erase(b[i]);
      }

      // brute-force search
      vector<int> vec;
      for(auto e: st) {
        vec.push_back(e);
      }

      do {
        b[n-3] = vec[0];
        b[n-2] = vec[1];
        b[n-1] = vec[2];
        debug(vec[0], vec[1], vec[2]);
        debug(a[b[n-4]], b[n-3]);
        if (a[b[n-4]] != b[n-3] && a[b[n-3]] != b[n-2] && a[b[n-2]] != b[n-1]) {
          for(auto e: b) {
            cout << e << ' ';
          }
          cout << endl;
          return;
        }
      } while (next_permutation(all(vec)));
    }
};

