vector<int> solve(int n, vector<int> a) {
    if (n <= 4) {
        vector<int> p(n + 1);
        for (int i = 1; i <= n; ++i)
            p[i] = i;
        return bruteforce(n, p, a);
    }

    set<int> s;
    for (int i = 1; i <= n; ++i)
        s.insert(i);

    vector<int> res(1, 1);
    s.erase(1);
    for (int i = 1; i < n - 3; ++i) {
        if (*s.begin() != a[res.back()]) {
            res.push_back(*s.begin());
        }
        else {
            auto it = s.begin();
            ++it;
            res.push_back(*it);
        }
        s.erase(res.back());
    }

    vector<int> p;
    for (auto x : s)
        p.push_back(x);
    p.insert(p.begin(), res.back());
    p.insert(p.begin(), 0);

    vector<int> tmp = bruteforce(4, p, a);
    tmp.erase(tmp.begin(), tmp.begin()+2);
    for (auto x : tmp) {
        if (x != 0)
            res.push_back(x);
    }

    return res;
}


