void solve3(vector<LL>& ans, vector<LL>& a, vector<LL>& tri){
    for(LL i = 0; i < 3; ++i){
        for(LL j = 0; j < 3; ++j){
            for(LL k = 0; k < 3; ++k){
                if(i == j || j == k || k == i) continue;
                if(ans.size() > 0 && a[ans[ans.size()-1]] == tri[i]) continue;
                if(a[tri[i]] != tri[j] && a[tri[j]] != tri[k]){
                    ans.push_back(tri[i]);
                    ans.push_back(tri[j]);
                    ans.push_back(tri[k]);
                    return;
                }
            }
        }
    }
}


int main(){
    LL n;
    cin >> n;
    vector<LL> a(n);
    vector<LL> indegree(n);
    for(LL i = 0; i < n; ++i){
        cin >> a[i];
        --a[i];
        indegree[a[i]] += 1;
    }
    if(n <= 2){
        cout << -1 << endl;
        return 0;
    }

    set<pair<LL,LL>> ordered;
    set<LL> rest;
    for(LL i = 0; i < n; ++i){
        rest.insert(i);
        ordered.insert(pair<LL,LL>(indegree[i], i));
    }
    vector<LL> used(n);
    vector<LL> ans;
    for(LL i = 0; i+3 < n; ++i){
        while(!ordered.empty()){
            LL val = ordered.rbegin()->first;
            LL key = ordered.rbegin()->second;
            if(used[key]){
                ordered.erase(--ordered.end());
                continue;
            }
            if(val != indegree[key]){
                ordered.erase(--ordered.end());
                ordered.insert(pair<LL,LL>(indegree[key], key));
                continue;
            }
            break;
        }
        if(!ordered.empty()){
            LL val = ordered.rbegin()->first;
            LL key = ordered.rbegin()->second;
            if(val == n-1-i){
                ans.push_back(key);
                used[key] = 1;
                indegree[a[key]] -= 1;
                rest.erase(key);
                continue;
            }
        }
        for(LL cur: rest){
            if(i > 0 && a[ans[ans.size()-1]] == cur){
                continue;
            }
            ans.push_back(cur);
            used[cur] = 1;
            indegree[a[cur]] -= 1;
            rest.erase(cur);
            break;
        }
    }
    assert(rest.size() == 3);
    vector<LL> tri(rest.begin(), rest.end());
    solve3(ans, a, tri);
    for(LL i = 0; i < n; ++i){
        cout << ans[i]+1 << ((i+1==n)?"\n":" ");
    }
    return 0;
}

