		// cout<<i<<" "<<p<<" "<<last<<endl;
		if(p == 0) continue;

		while(!cont.empty()){
			p32 t = cont.top();
			if(done[-t.fi] == 0) break;
			cont.pop();
		}
		while(!cont.empty() && cont.top().se == n-i){
			p32 t = cont.top();
			if(curr[-t.fi] == cont.top().se) break;
			cont.pop();
			cont.push(mp(t.fi,curr[t.fi]));
		}

		p32 t = cont.top();
		if(t.se == n-i-1){
			cont.pop();
			t.fi = -t.fi;
			done[t.fi] = 1;
			last = t.fi;
			curr[next[t.fi]]--;
			continue;
		}

		if(q.size() == 2){
			int t1 = q.top(); q.pop();
			int t2 = q.top(); q.pop();
			q.push(t2); q.push(t1);
			if(t1 == next[t2] && t2 == next[t1]){
				p = 0;
				continue;
			}
		}
		if(q.size() == 3){	
			int t1 = q.top(); q.pop();
			int t2 = q.top(); q.pop();
			int t3 = q.top(); q.pop();
			if(t2 == next[t3] && t3 == next[t2]){
				q.push(t3); q.push(t1); q.push(t2);
			}
			else{
				q.push(t3); q.push(t2); q.push(t1);
			}
		}
		int ta;
		while(true){
			ta = q.top();
			q.pop();
			if(done[ta]) continue;
			else break;
		}
		if(last != -1 && next[last] == ta){
			if(q.size() == 1){
				p = 0;
				continue;
			}
			int tn = q.top();
			q.pop();
			q.push(ta);
			ans.pb(tn);
			done[tn] = 1;
			last = tn;
		}
		else{
			ans.pb(ta);
			last = ta;
			done[ta] = 1;
		}
		curr[next[last]]--;
	}

	if(p){
		forstl(r,ans) cout<<r+1<<" ";
	}
	else{
		cout<<-1;
	}
	cout<<ln;

	return 0;
}

