int N, A[101010];
set<int> S;
vector<int> seq;
int hate_count[101010];
set<pair<int, int>> hate; // # of hater, id

void emit()
{
	for (int i = 0; i < N; ++i) printf("%d%c", seq[i] + 1, i == N - 1 ? '\n' : ' ');
	exit(0);
}

void solve(int);

void step(int n, int pre, int v)
{
	if (n >= 1 && A[pre] == v) return;
	seq.push_back(v);
	S.erase(v);
	hate.erase({hate_count[v], v});

	solve(n + 1);

	hate.insert({hate_count[v], v});
	S.insert(v);
	seq.pop_back();
}

void solve(int n)
{
	if (n == N) {
		emit();
	}
	int pre = -1;
	if (n >= 1) pre = seq[n - 1];
	bool flg = false;
	if (pre != -1) {
		int nx = A[pre];
		if (hate.count({hate_count[nx], nx})) {
			flg = true;
			hate.erase(make_pair(hate_count[nx], nx));
			--hate_count[nx];
			hate.insert(make_pair(hate_count[nx], nx));
		}
	}

	bool sr = false;
	if (hate.size() > 0) {
		auto last = *--hate.end();
		//printf("%d, %d %d\n", n, last.first, last.second);
		if (last.first >= N - n) {

		} else if (last.first == N - n - 1) {
			step(n, pre, last.second);
		} else {
			sr = true;
		}
	}
	sr = true;

	if (sr) {
		for (int v = *S.begin(); ; ) {
			step(n, pre, v);
			auto nxt = ++S.lower_bound(v);
			if (nxt == S.end()) break;
			v = *nxt;
		}
	}

	if (pre != -1 && flg) {
		int nx = A[pre];
		hate.erase(make_pair(hate_count[nx], nx));
		++hate_count[nx];
		hate.insert(make_pair(hate_count[nx], nx));
	}
}

int main()
{
	scanf("%d", &N);
	for (int i = 0; i < N; ++i) {
		scanf("%d", A + i); --A[i];
	}
	for (int i = 0; i < N; ++i) ++hate_count[A[i]];
	for (int i = 0; i < N; ++i) S.insert(i);
	for (int i = 0; i < N; ++i) hate.insert({hate_count[i], i});
	solve(0);

	puts("-1");
	return 0;
}

