    return;
  }
  std::vector<usize> a(n);
  for (auto &e : a) {
    e = scan<usize>() - 1;
  }
  std::set<usize> rem;
  for (const usize i : rep(0, n)) {
    rem.insert(i);
  }
  std::vector<usize> ideg(n, 0);
  for (const auto e : a) {
    ideg[e] += 1;
  }
  std::multiset<usize> degs;
  for (const auto e : ideg) {
    degs.insert(e);
  }
  usize ng = n;
  std::vector<usize> ans(n);
  const auto det = [&](const usize v) {
    rem.erase(v);
    ng = a[v];
    {
      auto &d = ideg[a[v]];
      if (d != 0) {
        degs.erase(degs.find(d));
        d -= 1;
        degs.insert(d);
      }
    }
    {
      auto &d = ideg[v];
      if (d != 0) {
        degs.erase(degs.find(d));
        d = 0;
        degs.insert(d);
      }
    }
  };
  for (const usize i : rep(0, n)) {
    if (n - i <= 3) {
      std::vector<usize> r(rem.begin(), rem.end());
      do {
        bool f = r[0] != ng;
        for (const usize i : rep(1, r.size())) {
          if (r[i] == a[r[i - 1]])
            f = false;
        }
        if (f) {
          break;
        }
      } while (std::next_permutation(r.begin(), r.end()));
      for (usize j = 0; j != r.size(); j += 1) {
        ans[i + j] = r[j];
      }
      break;
    }
    if (*degs.rbegin() == n - i - 1) {
      for (const usize j : rep(0, n)) {
        if (ideg[j] == n - i - 1) {
          ans[i] = j;
          det(j);
        }
      }
      continue;
    }
    usize ko = *rem.begin();
    if (ko == ng) {
      ko = *std::next(rem.begin());
    }
    ans[i] = ko;
    det(ko);
  }
  for (const usize i : rep(0, n)) {
    std::cout << ans[i] + 1 << " \n"[i + 1 == n];
  }
}

