	vector<pair<int,int>> p(n);

	rep(i,n) p[i]={-deg[i],i};
	sort(p.begin(),p.end());
	rep(i,min(50,n)) V.emplace_back(-p[i].first,p[i].second);

	bool ok=dfs(0);

	if(ok){
		rep(i,n) printf("%d%c",ans[i]+1,i<n-1?' ':'\n');
	}
	else{
		puts("-1");
	}

	return 0;
}

