typedef pair<ll,int> P;
ll const INF = INT64_MAX;
struct SegmentTree {
private:
    int n;
    vector<P> node;
public:
    SegmentTree(vector<P> v) {
        int sz = v.size();
        n = 1;
        while (n < sz) n *= 2;
        node.resize(2*n-1,P(INF,-1));
        for (int i = 0;i < sz;++i) node[i+n-1] = v[i];
        for (int i = n-2;i >= 0;--i) node[i] = max(node[2*i+1],node[2*i+2]);
    }

    void update(int x,P val) {
        x += (n-1);
        node[x] = val;
        while (x > 0) {
            x = (x-1)/2;
            node[x] = max(node[2*x+1],node[2*x+2]);
        }
    }

    P getmax(int a,int b,int k = 0,int l = 0,int r = -1) {
        if (r < 0) r = n;
        if (r <= a || b <= l) return P(INF,-1);
        if (a <= l && r <= b) return node[k];
        P vl = getmax(a,b,2*k+1,l,(l+r)/2);
        P vr = getmax(a,b,2*k+2,(l+r)/2,r);
        return max(vl,vr);
    }
};

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    vector<P> cnt(n,P(0,0));
    for (int i = 0;i < n;++i) {
        cin >> a[i];
        a[i]--;
        cnt[a[i]].first++;
    }
    for (int i = 0;i < n;++i) cnt[i].second = i;
    SegmentTree seg(cnt);
    if (n == 2) {
        cout << -1 << endl;
        return 0;
    }
    P m = seg.getmax(0,n);
    set<int> st;
    for (int i = 0;i < n;++i) st.insert(i);
    vector<int> ans(n);
    if (m.first == n-1) {
        st.erase(m.second);
        ans[0] = m.second;
        seg.update(m.second,P(0,m.second));
        seg.update(a[m.second],P(seg.getmax(a[m.second],a[m.second]+1).first-1,a[m.second]));
        m = seg.getmax(0,n);
    } else {
        int c = *st.begin();
        ans[0] = c;
        st.erase(c);
        seg.update(a[c],P(seg.getmax(a[c],a[c]+1).first-1,a[c]));
        m = seg.getmax(0,n);
    }
    for (int i = 1;i < n;++i) {
        if (m.first == n-i-2 && a[ans[i-1] != m.second]) {
            st.erase(m.second);
            ans[i] = m.second;
            seg.update(m.second,P(0,m.second));
            seg.update(a[m.second],P(seg.getmax(a[m.second],a[m.second]+1).first-1,a[m.second]));
            m = seg.getmax(0,n);
        } else {
            auto it = st.begin();
            if (a[ans[i-1]] == *it) ++it;
            int c = *it;
            ans[i] = c;
            st.erase(c);
            seg.update(a[c],P(seg.getmax(a[c],a[c]+1).first-1,a[c]));
            m = seg.getmax(0,n);
        }
    }
    // p_ary(ans,0,n);
    for (int i = 0;i < n;++i) cout << ans[i]+1 << " \n"[i == n-1];
}

