bool check(const vector<int> &res) {
    for (int i = 0; i + 1 < res.size(); ++i) {
        if (res[i+1] == p[res[i]]) return false;
    }
    return true;
}

void last(vector<int> &res, vector<int> &rem) {
    do {
        if (rem[0] == p[res.back()]) continue;
        if (check(rem)) {
            for (int i = 0; i < res.size(); ++i) cout << res[i] + 1 << " ";
            for (int i = 0; i < rem.size(); ++i) cout << rem[i] + 1 << " ";
            cout << endl;
            return;
        }
    } while (next_permutation(rem.begin(), rem.end()));

    cout << -1 << endl;
    return;
}

void solve() {
    if (N <= 9) {
        vector<int> res(N);
        for (int i = 0; i < N; ++i) res[i] = i;
        do {
            if (check(res)) {
                for (int i = 0; i < res.size(); ++i) cout << res[i]+1 << " ";
                cout << endl;
                return;
            }
        } while (next_permutation(res.begin(), res.end()));

        cout << -1 << endl;
        return;
    }

    int need = 0;
    vector<vector<int>> pnum(N, vector<int>());
    for (int i = 0; i < N; ++i) {
        pnum[p[i]].push_back(i);
    }
    for (int i = 0; i < N; ++i) {
        if (pnum[i].size() == N-1) need = i;
    }

    int con = 0;
    vector<int> res({need});
    set<int> se;
    for (int i = 1; i < N; ++i) if (i != need) se.insert(i);
    while (N - (int)res.size() > 9) {
        int from = res.back();
        int dame = p[from];
        int i = -1;
        for (auto it : se) {
            if (it != dame) {
                i = it;
                break;
            }
        }

        //COUT(i);

        res.push_back(i);
        se.erase(i);

        //COUT(res);
    }
    vector<int> rem;
    for (auto it : se) rem.push_back(it);
    last(res, rem);
}

