#define MAX_N 3030303
long long extgcd(long long a, long long b, long long& x, long long& y) {
    long long d = a;
    if (b != 0) {
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    } else {
        x = 1; y = 0;
    }
    return d;
}
long long mod_inverse(long long a, long long m) {
    long long x, y;
    if(extgcd(a, m, x, y) == 1) return (m + x % m) % m;
    else return -1;
}
vector<long long> fact(MAX_N+1, inf);
long long mod_fact(long long n, long long& e) {
    if(fact[0] == inf) {
        fact[0]=1;
        if(MAX_N != 0) fact[1]=1;
        for(ll i = 2; i <= MAX_N; ++i) {
            fact[i] = (fact[i-1] * i) % mod;
        }
    }
    e = 0;
    if(n == 0) return 1;
    long long res = mod_fact(n / mod, e);
    e += n / mod;
    if((n / mod) % 2 != 0) return (res * (mod - fact[n % mod])) % mod;
    return (res * fact[n % mod]) % mod;
}
// return nCk
long long mod_comb(long long n, long long k) {
    if(n < 0 || k < 0 || n < k) return 0;
    long long e1, e2, e3;
    long long a1 = mod_fact(n, e1), a2 = mod_fact(k, e2), a3 = mod_fact(n - k, e3);
    if(e1 > e2 + e3) return 0;
    return (a1 * mod_inverse((a2 * a3) % mod, mod)) % mod;
}

using mi = modint;

mi mod_pow(mi a, ll n) {
    mi ret = 1;
    mi tmp = a;
    while(n > 0) {
        if(n % 2) ret *= tmp;
        tmp = tmp * tmp;
        n /= 2;
    }
    return ret;
}

ll gcd(ll a, ll b) {
    if (b == 0) return a;
    return gcd(b, a % b);
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> a(n);
    REP(i, n) cin >> a[i];
    vector<int> ans;
    vector<bool> used(n, false);
    vector<int> c(n, 0);
    REP(i, n) c[a[i] - 1]++;
    priority_queue<pair<int, int>> pq;
    REP(i, n) pq.push({c[i], i});
    set<int> q;
    for(int i = n - 1; i >= 0; i--) q.insert(i + 1);
    while(1) {
        while(!pq.empty() && (used[pq.top().second] || c[pq.top().second] != pq.top().first)) {
            pq.pop();
        }
        if((int)q.size() <= 8) {
            vector<int> v;
            while(!q.empty()) {
                v.push_back(*(q.begin()));
                q.erase(q.begin());
            }
            int m = (int)v.size();
            vector<int> w(m, inf);
            do {
                bool ok = true;
                if((int)ans.size() != 0 && a[ans.back() - 1] == v[0]) ok = false;
                REP(i, m - 1) if(a[v[i] - 1] == v[i + 1]) ok = false;
                if(ok) w = min(w, v);
            } while(next_permutation(ALL(v)));
            if(w[0] == inf) {
                cout << -1 << endl;
                return 0;
            }
            REP(i, m) ans.push_back(w[i]);
            break;
        }
        if(pq.top().first == (int)q.size() - 1) {
            int t = pq.top().second;
            ans.push_back(t + 1);
            c[a[t] - 1]--; pq.push({c[a[t] - 1], a[t] - 1});
            q.erase(t + 1);
            continue;
        }
        int t = *(q.begin());
        if(!ans.empty() && a[ans.back() - 1] == t) {
            q.erase(q.begin());
            ans.push_back(*(q.begin()));
            used[*(q.begin()) - 1] = true;
            c[a[*(q.begin()) - 1] - 1]--; pq.push({c[a[*(q.begin()) - 1] - 1], a[*(q.begin()) - 1] - 1});
            q.erase(q.begin());
            q.insert(t);
        } else {
            ans.push_back(t);
            used[t - 1] = true;
            c[a[t - 1] - 1]--; pq.push({c[a[t - 1] - 1], a[t - 1] - 1});
            q.erase(q.begin());
        }
    }
    cout << ans << endl;
    return 0;
}

