Printer pr = Printer(stdout);

V<int> solve(V<int> p, int s, int t) {
    int n = int(p.size());
    if (n == 2) {
        return {};
    }
    V<int> b(n, -1);
    if (s != -1) b[s] = t;

    const int L = 3;
    int l = min(n, L);

    set<int> st;
    for (int i = 0; i < n; i++) {
        st.insert(i);
    }

    for (int i = 0; i < n - L; i++) {
        if (b[i] == -1) {
            b[i] = *st.begin();
            if (i && p[b[i - 1]] == b[i]) {
                b[i] = *next(st.begin());
            }
        }
        st.erase(b[i]);
    }
    for (int i = max(0, n - L); i < n; i++) {
        b[i] = *st.begin();
        st.erase(b[i]);
    }
    do {
        bool ok = true;
        for (int i = max(0, n - 10); i < n - 1; i++) {
            if (p[b[i]] == b[i + 1]) ok = false;
        }
        if (!ok) continue;
        return b;
    } while (next_permutation(b.end() - l, b.end()));
    assert(s == -1);
    V<int> buf(3);
    for (int i = 0; i < 3; i++) buf[i] = p[b[n - 1 - i]];
    sort(buf.begin(), buf.end());
    int sp = buf[1]; // mid
    for (int i = max(0, n - l - 1); i >= -1; i--) {
        if (i == -1 || p[b[i]] != sp) {
            return solve(p, i + 1, sp);
        }
    }
    assert(false);
}

