using namespace std;

constexpr int N = 100000;

struct Event {
	int idx, hated;

	bool operator < (const Event &e) const {
		if (this->hated == e.hated) {
			return this->idx > e.idx;
		}

		return this->hated < e.hated;
	}
};

priority_queue<Event> pq;
int indegree[N + 1];
int ans[N + 1];
int a[N + 1];
set<int> s;

bool valid(const Event &e) {
	return s.count(e.idx) and e.hated == indegree[e.idx];
}

int main() {
	int n, i;

	scanf("%d", &n);

	for (i = 1; i <= n; i++) {
		scanf("%d", a + i);
		indegree[a[i]]++;
	}

	if (n == 2) {
		printf("-1\n");
		return 0;
	}

	for (i = 1; i <= n; i++) {
		pq.push({i, indegree[i]});
		s.insert(i);
	}

	if (pq.top().hated == n - 1) {
		ans[1] = pq.top().idx;
		pq.pop();
	}
	else {
		ans[1] = 1;
	}

	s.erase(ans[1]);

	for (i = 2; i <= n; i++) {
		while (!valid(pq.top())) {
			pq.pop();
		}

		if (pq.top().hated >= n - i) {
			if (pq.top().idx == a[ans[i - 1]]) {
				if (*s.begin() == a[ans[i - 1]]) {
					ans[i] = *next(s.begin());
				}
				else {
					ans[i] = *s.begin();
				}
			}
			else {
				ans[i] = pq.top().idx;
			}
		}
		else {
			if (*s.begin() == a[ans[i - 1]]) {
				ans[i] = *next(s.begin());
			}
			else {
				ans[i] = *s.begin();
			}
		}

		s.erase(ans[i]);
		indegree[a[ans[i - 1]]]--;
		pq.push({a[ans[i - 1]], indegree[a[ans[i - 1]]]});
	}

	for (i = 1; i <= n; i++) {
		printf("%d ", ans[i]);
	}

	printf("\n");

	return 0;
}

