				} else {
					ans.pop_back();
					s.insert(start);
				}
			}
			cout << "-1" << endl;
			return false;
		} else {
			int prev = 0;
			for (int i = 0; i < s.size(); i++) {
				auto it = s.upper_bound(prev);
				if (it == s.end())
