const int N = 1e6;

int n;
int a[N];
int cnt[N];
int used[N];
set<pair<int, int> > mm, mm2;
vector<int> ans;

int get2(int x)
{
    auto it = mm2.lower_bound({x, -1});
    return (*it).second;
}

int ch(int lst, int x, int t)
{
    if (a[lst] == x)
    {
        return 0;
    }
    int cn = get2(x);
    mm.erase({cn, x});
    mm2.erase({x, cn});
    if (t == 0)
    {
        int nxt = a[x];
        if (!used[nxt])
        {
            int cnnxt = get2(nxt);
            mm.erase({cnnxt, nxt});
            mm.insert({cnnxt - 1, nxt});
            mm2.erase({nxt, cnnxt});
            mm2.insert({nxt, cnnxt - 1});
        }
        return 1;
    }
    auto it = mm.end();
    it--;
    if ((*it).first + 1 == mm.size())
    {
        mm.insert({cn, x});
        mm2.insert({x, cn});
        return 0;
    }
    mm.insert({cn, x});
    mm2.insert({x, cn});
    return 1;
}

signed main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n;
    for (int i = 1; i <= n; i++)
    {
        cin >> a[i];
        cnt[a[i]]++;
    }
    for (int i = 1; i <= n; i++)
    {
        mm.insert({cnt[i], i});
        mm2.insert({i, cnt[i]});
    }
    for (int i = n; i >= 5; i--)
    {
        int lst = 0, t = n;
        if (ans.size()) lst = ans.back();
        auto it1 = mm.end();
        it1--;
        auto it2 = mm.end();
        it2--;
        it2--;
        auto it3 = mm2.begin();
        auto it4 = mm2.begin();
        it4++;
        pair<int, int> i1 = *it1;
        pair<int, int> i2 = *it2;
        pair<int, int> i3 = *it3;
        pair<int, int> i4 = *it4;
        if (ch(lst, i1.second, 1)) t = min(t, i1.second);
        if (ch(lst, i2.second, 1)) t = min(t, i2.second);
        if (ch(lst, i3.first, 1)) t = min(t, i3.first);
        if (ch(lst, i4.first, 1)) t = min(t, i4.first);
        if (t == n) cout << -1, exit(0);
        ch(lst, t, 0);
        used[t] = 1;
        ans.push_back(t);
    }
    vector<int> p;
    int lst = 0;
    if (ans.size()) lst = ans.back();
    for (int i = 1; i <= n; i++) if (used[i] == 0) p.push_back(i);
    while (1)
    {
        int t = 1;
        if (a[lst] == p[0]) t = 0;
        for (int i = 1; i < p.size(); i++)
            if (a[p[i - 1]] == p[i]) t = 0;
        if (t)
        {
            for (int i = 0; i < p.size(); i++)
                ans.push_back(p[i]);
            break;
        }
        if (!next_permutation(all(p)))
        {
            cout << -1, exit(0);
        }
    }
    cout << ans.size() << endl;
    for (int i = 0; i < ans.size(); i++) cout << ans[i] << " ";
}

