int N;
vector<int> p;

bool check(const vector<int> &res) {
    for (int i = 0; i + 1 < res.size(); ++i) {
        if (res[i+1] == p[res[i]]) return false;
    }
    return true;
}

void last(vector<int> &res, vector<int> &rem) {
    do {
        if (res.size() > 0 && rem[0] == p[res.back()]) continue;
        if (check(rem)) {
            for (int i = 0; i < res.size(); ++i) cout << res[i] + 1 << " ";
            for (int i = 0; i < rem.size(); ++i) cout << rem[i] + 1 << " ";
            cout << endl;
            return;
        }
    } while (next_permutation(rem.begin(), rem.end()));

    cout << -1 << endl;
    return;
}

void solve() {
    if (N <= 7) {
        vector<int> res, rem(N);
        for (int i = 0; i < N; ++i) rem[i] = i;
        last(res, rem);
        return;
    }

    map<int, set<int>> inv;
    for (int i = 0; i < N; ++i) {
        inv[p[i]].insert(i);
    }

    vector<int> res;
    set<int> rem;
    for (int i = 0; i < N; ++i) rem.insert(i);
    while (N - (int)res.size() > 7) {
        if (inv.size() <= 2) res.push_back(inv.begin()->first);
        else {
            int dame = !res.empty() ? p[res.back()] : -1;
            int i = -1;
            for (auto it : rem) {
                if (it != dame) { i = it; break; }
            }
            res.push_back(i);
        }

        {
            rem.erase(res.back());
            int from = res.back();
            int to = p[from];
            if (inv.count(to) && inv[to].count(from)) {
                inv[to].erase(from);
                if (inv[to].empty()) inv.erase(to);
            }
        }
    }
    vector<int> vrem;
    for (int i = 0; i < N; ++i) if (rem.count(i)) vrem.push_back(i);
    last(res, vrem);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    while (cin >> N) {
        p.resize(N);
        for (int i = 0; i < N; ++i) cin >> p[i], --p[i];
        solve();
    }
}

