int ans_idx = 0, pre = 0;

void solve(int sz) {
    while ((int)cand.size() > sz) {
        int tpcand = *cand.begin(), nxt;
        auto tp = pq.rbegin();
        if (tp->first == (int)cand.size() - 1) {
            int cur = tp->second;
            pq.erase(prev(pq.end()));
            ans[ans_idx++] = cur;
            cand.erase(cur);
            nxt = cur;
        } else if (a[pre] == tpcand) {
            cand.erase(cand.begin());
            int cur = *cand.begin();
            cand.erase(cand.begin());
            ans[ans_idx++] = cur;
            cand.insert(tpcand);
            nxt = cur;
        } else {
            cand.erase(cand.begin());
            ans[ans_idx++] = tpcand;
            nxt = tpcand;
        }
        visit[nxt] = 1;
        if (!visit[a[nxt]]) {
            int to = a[nxt];
            pq.erase(make_pair(indeg[to], to));
            indeg[to]--;
            pq.insert(make_pair(indeg[to], to));
        }
        pq.erase(make_pair(indeg[nxt], nxt));
        pre = nxt;
    }
}

