        cand.insert(i);
    }
    solve(3);
    for (int i = 0; i < 3; i++) {
        int tp = *cand.begin();
        cand.erase(cand.begin());
        rem[i] = tp;
    }
    int ans1 = MAXN, ans2 = MAXN, ans3 = MAXN;
    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            if (j == i) continue;
            for (int k = 0; k < 3; k++) {
                if (k == i || k == j) continue;
                if (a[pre] == rem[i]) continue;
                if (a[rem[i]] == rem[j]) continue;
                if (a[rem[j]] == rem[k]) continue;
                if (rem[i] < ans1) {
                    ans1 = rem[i];
                    ans2 = rem[j];
                    ans3 = rem[k];
                } else if (rem[i] == ans1) {
                    if (rem[j] < ans2) {
                        ans1 = rem[i];
                        ans2 = rem[j];
                        ans3 = rem[k];
                    }
                }
            }
        }
    }
    ans[ans_idx++] = ans1;
    ans[ans_idx++] = ans2;
    ans[ans_idx++] = ans3;
    for (int i = 0; i < N; i++)
        printf("%d ", ans[i]);
    puts("");
    return 0;
}

