    BigInt operator +(BigInt obj) {
        string c;
        while (max(obj.s.length(), this->s.length()) + 1 > c.length()) {
            c.pb('0');
        }
        for (int q = 0; q < obj.s.length(); ++q) {
            c[c.length() - 1 - q] = obj.s[obj.s.length() - q - 1];
        }
        for (int q = 0; q < this->s.length(); ++q) {
            c[c.length() - 1 - q] += this->s[this->s.length() - 1 - q] - '0';
            if (c[c.length() - 1 - q] > '9') {
                c[c.length() - 2 - q]++;
                c[c.length() - 1 - q] -= 10;
            }
        }
        if (c.front() == '0') {
            c.erase(c.begin());
        }
        return BigInt{ c };
    }
    BigInt operator *(BigInt obj) {
        BigInt ans;
        for (int i = this->s.length() - 1; i >= 0; --i) {
            REP(q, this -> s[i] - '0') {
                ans = ans + obj;
            }
            obj.s.pb('0');
        }
        return ans;
    }
}BigInt;

int pow(int a, int b) {
    int ans = 1;
    while (b != 0) {
        if (b % 2) {
            ans *= a;
            ans %= MAX_MOD;
        }
        a *= a;
        a %= MAX_MOD;
        b /= 2;
    }
    return ans;
}
int inv(int a) {
    return pow(a, MAX_MOD - 2LL);
}
int minus_calc(int a) {
    return MAX_MOD - (a % MAX_MOD);
}
void solve() {
    int n;
    cin >> n;
    vector<int> inputs;
    REP(i, n) {
        int a;
        cin >> a;
        inputs.pb(a-1);
    }
    vector<int> ans;
    vector<int> remaining;
    REP(i, n) {
        remaining.pb(n - i - 1);
    }
    while (remaining.size() >= 4) {
        if (ans.empty() == true) {
            ans.pb(remaining.back());
            remaining.pop_back();
            continue;
        }
        if (remaining.back() != inputs[ans.back()]) {
            //not bad
            ans.pb(remaining.back());
            remaining.pop_back();
            continue;
        }
        else {
            int hoge = remaining.back();
            remaining.pop_back();
            ans.pb(remaining.back());
            remaining.pop_back();
            remaining.pb(hoge);
            continue;
        }
    }
    sort(ALL(remaining));
    do {
        int back = remaining[0];
        if (ans.empty() == false) {
            back = ans.back();
        }
        int ok = 1;
        for (int i = 0; i < remaining.size(); ++i) {
            if (inputs[back] == remaining[i]) {
                ok = 0;
                break;
            }
            back = remaining[i];
        }
        if (ok == 1) {
            REP(i, ans.size()) {
                cout << ans[i] + 1 << " ";
            }
            REP(i, remaining.size()) {
                cout << remaining[i] + 1 << " ";
            }
            cout << endl;
            return;
        }
    } while (next_permutation(ALL(remaining)));
    cout << -1 << endl;
    return;
}
