        in[i].second = i;
    }
    SegmentTree<pair<int, int>> seg(in, f, unit);
    set<int> unused;
    for (int i = 0; i < n; ++i) {
        unused.insert(i);
    }
    vector<int> ret;
    int ng = -1;
    for (int i = 0; i < n - 5; ++i) {
