struct BIT{
	int d[N],r;
	inline void Add(int x){ while (x <= n) ++d[x],x += x&-x; }
	inline void Dev(int x){ while (x <= n) --d[x],x += x&-x; }
	inline int Ask(int x){ r=0; while (x>0) r+=d[x],x -= x&-x; return r; }
	inline int Query(int l,int r){ return Ask(r) - Ask(l-1); }
}T;
int cnt[N],ans[N],vis[N];
inline void solve(int s){
	int i,p,l,r,ap,mi;
	for (i = 1; i <= n; ++i) T.Add(i); ans[1] = s; vis[s] = 1; T.Dev(s);
	for (i = 2; i <= n; ++i){
		if (!vis[p = a[ans[i-1]]]) T.Dev(p);
		l = 1,r = n,ap = n+1;
		while (l <= r){
			mi = l+r>>1; if (T.Query(1,mi) > 0) ap = mi,r = mi-1; else l = mi+1;
		}
		ans[i] = ap; T.Dev(ans[i]); vis[ans[i]] = 1;
		if (!vis[p]) T.Add(p);
	}
	for (i = 1; i <= n; ++i) write(ans[i]),putchar((i<n)?(' '):('\n'));
}
