vector<int> solve(int n, set<int>& ids, multiset<int>& all_ai) {
	int cur_banned = 0;
	vector<int> ans;
	for (int i = n; i >= 1; --i) {
		if (i <= 4) {
			vector<int> temp;
			for (auto& id : ids) {
				temp.pb(id);
			}
			do {
				if (cur_banned == temp[0]) {
					continue;
				}
				int sz = temp.size();
				bool ok = true;
				for (int j = 0; j < sz - 1; ++j) {
					if (a[temp[j]] == temp[j + 1]) {
						ok = false;
						break;
					}
				}
				if (ok) {
					for (auto& id : temp) {
						ans.pb(id);
					}
					return ans;
				}
			} while (next_permutation(temp.begin(), temp.end()));
			return {-1};
		} else if (*all_ai.begin() == *prev(all_ai.rbegin()) and ids.count(*all_ai.begin())) {
			int id = *all_ai.begin();
			if (cur_banned == id) {
				return {-1};
			}
			ans.pb(id);
			ids.erase(id);
			all_ai.erase(all_ai.find(a[id]));
			cur_banned = a[id];
		} else if (*next(all_ai.begin()) == *all_ai.rbegin() and ids.count(*all_ai.rbegin())) {
			int id = *all_ai.rbegin();
			if (cur_banned == id) {
				return {-1};
			}
			ans.pb(id);
			ids.erase(id);
			all_ai.erase(all_ai.find(a[id]));
			cur_banned = a[id];
		} else {
			int id = *ids.begin();
			if (cur_banned == id) {
				id = *next(ids.begin());
			}
			ans.pb(id);
			ids.erase(id);
			all_ai.erase(all_ai.find(a[id]));
			cur_banned = a[id];
		}
	}
	return ans;
}

