void sch(int n, int now, const vi &a, vi &ans, set<int> &st) {
  if(n == now) {
    return;
  }
  if(n - now <= 100) {
    vi v;
    for(auto &e: st) v.push_back(e);
    REP(i, SZ(v)) {
      if(SZ(ans) != 0 && a[ans.back()] == v[i]) continue;
      ans.push_back(v[i]);
      st.erase(v[i]);
      sch(n, now+1, a, ans, st);
      if(SZ(ans) == n) return;
      st.insert(v[i]);
      ans.pop_back();
    }
  } else {
    int nxt = -1;
    for(auto &e: st) {
      if(SZ(ans) == 0 || a[ans.back()] != e) {
        nxt = e;
        break;
      }
    }
    if (nxt != -1) {
      ans.push_back(nxt);
      st.erase(nxt);
      sch(n, now+1, a, ans, st);
    }
  }
}

