bool solve_slow(int banned, vector<int> &ans, vector<int> v) {
    sort(all(v));

    do {
        if (v[0] == banned)
            continue;

        bool ok = true;
        for (int i = 0; i + 1 < v.size(); i++) {
            if (a[v[i]] == v[i + 1]) {
                ok = false;
                break;
            }
        }
        if (ok) {
