		// cout<<"$"<<(*it1).f<<" "<<n-i-1<<endl;
		if((*it1).f==n-i-1 && v[st]!=(*it1).s) {
			if(v[st]==(*it1).s) break;
			st = (*it1).s;
			hatred.erase(it1);

			set1.erase(st);
			ans.pb(st);
			// cout<<">>"<<i<<" "<<st<<endl;

			hatred.erase({hate[v[st]],v[st]});
			hate[v[st]]--;
			if(set1.count(v[st])) hatred.insert({hate[v[st]],v[st]});

			continue;
