			int ptr = *it;
			if(st!=-1&&v[st]==ptr) it++;
			else break;
		}
		if(it==set1.end()) break;
		// cout<<">"<<i<<" "<<*it<<endl;

		st = *it;
		// if(*it==1) cout<<hate[v[st]]<<","<<v[st]<<endl;
		hatred.erase({hate[v[st]],v[st]});
		hate[v[st]]--;
		if(set1.count(v[st])) hatred.insert({hate[v[st]],v[st]});
		hatred.erase({hate[st],st});
		set1.erase(it);
		ans.pb(st);
	}

