      res.push_back(e+1);
      if(SZ(res) == n) return true;
      st.erase(e);
      bool tmp = dfs(n, e, a, st, res);
      if(tmp) {
        ok = true;
        break;
      } else {
        st.insert(e);
        res.pop_back();
      }
    }
  }
  return ok;
}

