set<int> alive;
set<pair<int, int>> forb_cnts;

void del (int u) {
  alive.erase(u);
  forb_cnts.erase(make_pair(fc[forb[u]], forb[u]));
  fc[forb[u]]--;
  if (fc[forb[u]] > 0) {
    forb_cnts.insert(make_pair(fc[forb[u]], forb[u]));
  }
}

int special () {
  if ((int) alive.size() == 3) {
    int u = *alive.begin();
    int v = *next(alive.begin());
    int w = *alive.rbegin();

    if (forb[u] == v && forb[v] == u && forb[w] != u && forb[w] != v) {
      return min(u, v);
    }
    swap(u, w);
    if (forb[u] == v && forb[v] == u && forb[w] != u && forb[w] != v) {
      return min(u, v);
    }
    swap(u, w);
    swap(v, w);
    if (forb[u] == v && forb[v] == u && forb[w] != u && forb[w] != v) {
      return min(u, v);
    }
  }

  if ((int) forb_cnts.size() == 2) {
    pair<int, int> fst = *forb_cnts.begin();
    pair<int, int> snd = *forb_cnts.rbegin();

    swap(fst, snd);

    if (snd.first == 1) {
      if (alive.count(fst.second)) return fst.second;
      else if (fst.first == 1 && alive.count(snd.second)) return snd.second;
    }
  }
  return 0;
}

