    for(int i = 0; i < n; i++) seg.set(i, l[i]);
    seg.build();
    int b[100002];
    bool used[100002]{0};
    int k = 0;
    for(int i = 0; i < n; i++){
        if(used[i]) continue;
        if(k == n - 1){
            b[k] = i;
            break;
        }
        if(seg.query(0, n) == n - k - 1){
            for(int j = 0; j < n; j++){
                if(seg[j] == n - k - 1){
                    b[k] = j;
                    k++;
                    used[j] = true;
                    seg.update(j, 0);
                    seg.update(a[j], seg[a[j]] - 1);
                    break;
                }
            }
            i--;
            continue;
        }
        if(k == n - 3){
            bool g = false;
            for(int j = 0; j < n; j++){
                if(!used[j] && !used[a[j]] && a[a[j]] == j){
                    if(a[b[k - 1]] != j){
                        g = true;
                        b[k] = j;
                        used[j] = true;
                        seg.update(j, 0);
                        seg.update(a[j], seg[a[j]] - 1);
                        i--;
                        break;
                    }
                }
            }
            if(g){
                k++;
                continue;
            }
        }
        if(k == 0){
            b[k] = 0;
            used[0] = true;
            seg.update(0, 0);
            seg.update(a[0], seg[a[0]] - 1);
        }
        else if(a[b[k - 1]] == i){
            for(int j = i + 1; j < n; j++) if(!used[j]){
