                used[j] = true;
                seg.update(j, 0);
                seg.update(a[j], seg[a[j]] - 1);
                i--;
                break;
            }
        }
        else{
            b[k] = i;
            used[i] = true;
            seg.update(i, 0);
            seg.update(a[i], seg[a[i]] - 1);
        }
        k++;
    }
    for(int i = 0; i < n; i++) cout << b[i] + 1 << " ";
