bool colide(int i)
{	return T[res[i]] == res[i+1];	}

int main()
{
	int n;
	scanf ("%d", &n);
	FOR(i, 1, n+1)
		scanf ("%d", T+i);
	if (n == 2)
		fail();

	int list = 1, mx = 0;

	FOR(i, 0, n)
	{
		int v = res[i];
		if (T[v] != list)
			res[i+1] = list;
		else
			res[i+1] = mx == list-1 ? mx+2 : mx+1;
		juz[res[i+1]] = true;

		while (juz[list])
			list++;
		mx = max(mx, res[i+1]);
	}

	if (res[n] > n)
		res[n] = list;

	int i = n;
	while (colide(i-1))
		swap(res[i], res[i-1]), i--;
	sort(res+i+1, res+n+1);

	if (!colide(i))
		ans(n);
	if (i <= n-2)
		swap(res[i+1], res[i+2]), ans(n);

	assert(i == n-1);
	swap(res[n-2], res[n-1]);
	swap(res[n-2], res[n]);
	if (colide(n-3))
		swap(res[n-2], res[n]);
	ans(n);
	assert(false);
}

