int main() {
  int n;
  cin>>n;
  if (n == 2) {
    cout<<-1<<endl;
    return 0;
  }
  vecint rules(n);
  for(auto&& e:rules)cin>>e;
  vecint cnt(n+1);
  for(auto&& e:rules) ++cnt[e];
  map<int,int> m;
  for(auto&& e:cnt) {
    ++m[e];
  }
  set<int> s;
  REP(i,n) s.insert(i+1);
  vecint ans;
  REP(i,n-3) {
    int rem = n-i;
    if (rbegin(m)->first == rem-1) { // 1 vs others
      REP(j,n+1) {
        if (s.count(j) && cnt[j] == rem-1) {
          ans.push_back(j);
          s.erase(j);
          --m[cnt[j]];
          if (m[cnt[j]] == 0) {
            m.erase(cnt[j]);
            break;
          } else {
            cout<<-1<<endl;
            return 0;
          }
        }
      }
    } else if (ans.empty()) {
      ans.push_back(1);
      s.erase(1);
      int v = cnt[1];
      --m[v];
      if (m[v] == 0) {
        m.erase(v);
      }
      if (s.count(rules[0])) {
        int u = cnt[rules[0]];
        --cnt[rules[0]];
        --m[u];
        if (m[u] == 0) {
          m.erase(u);
        }
        if (u > 0) ++m[u-1];
      }
    } else {
      int taboo = rules[ans.back()-1];
      auto itr = begin(s);
      if (*itr == taboo) ++itr;
      ans.push_back(*itr);
      int v = cnt[*itr];
      --m[v];
      if (m[v] == 0) {
        m.erase(v);
      }
      if (s.count(rules[*itr-1])) {
        int u = cnt[rules[*itr-1]];
        --cnt[rules[*itr-1]];
        --m[u];
        if (m[u] == 0) {
          m.erase(u);
        }
        if (u > 0) ++m[u-1];
      }
      s.erase(itr);
    }
  }
  vecint ary(ALL(s));
  do {
    bool ok = true;
    if (!ans.empty() && rules[ans.back()-1] == ary[0]) ok = false;
    REP(i,2) {
      if (rules[ary[i]-1] == ary[i+1]) ok = false;
    }
    if (ok) {
      ans.insert(end(ans), ALL(ary));
      break;
    }
  } while (next_permutation(ALL(ary)));
  if (ans.size() < n) {
    cout<<-1<<endl;
    return 0;
  }
  REP(i,n) {
    if (i)cout<<" ";
    cout<<ans[i];
  }
  cout<<endl;
  return 0;
}

