const int BRUTE = 10;

int N;
vector<int> A;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    A.assign(N + 1, 0);

    for (int i = 1; i <= N; i++)
        cin >> A[i];

    vector<int> B(N);
    priority_queue<int, vector<int>, greater<int>> remaining;

    for (int i = 1; i <= N; i++)
        remaining.push(i);

    int initial = max(N - BRUTE, 0);
    int previous = 0;

    for (int i = 0; i < initial; i++) {
        int minimum = remaining.top(); remaining.pop();

        if (minimum == A[previous]) {
            B[i] = remaining.top(); remaining.pop();
            remaining.push(minimum);
        } else {
            B[i] = minimum;
        }

        previous = B[i];
    }

    vector<int> finish;

    while (!remaining.empty()) {
        finish.push_back(remaining.top());
        remaining.pop();
    }

    do {
        previous = initial == 0 ? 0 : B[initial - 1];
        bool good = true;

        for (int i = 0; i < (int) finish.size(); i++) {
            if (finish[i] == A[previous]) {
                good = false;
                break;
            }

            previous = finish[i];
        }

        if (good) {
            for (int i = initial; i < N; i++)
                B[i] = finish[i - initial];

            for (int i = 0; i < N; i++)
                cout << B[i] << (i < N - 1 ? ' ' : '\n');

            return 0;
        }
    } while (next_permutation(finish.begin(), finish.end()));

    cout << -1 << '\n';
}

