int N;
vector<int> A;

vector<int> find_path(int v, vector<int> &path, vector<bool> &visited) {
  if (visited[v]) return vector<int>();
  visited[v] = true;
  path.push_back(v);

  if (path.size() == N) {
    return path;
  }

  for (int u = 0; u < N; ++u) {
    if (A[v] == u) continue;

    vector<int> ret = find_path(u, path, visited);

    if (ret.size() == N) {
      return ret;
    }
  }

  visited[v] = false;
  path.pop_back();

  return path;
}

int main() {
