  map<int, int> counter;
  int r = 0;

  for (int i = 0; i < N; ++i) {
    cin >> a;
    ++counter[a - 1];
    A.push_back(a - 1);

    if (counter[a - 1] == N - 1 && r == a - 1) {
      ++r;
    }
  }

  vector<bool> visited(N, false);
  vector<int> ans;

  for (int v = r; v < N; ++v) {
    ans = find_path(v, ans, visited);

    if (ans.size() == N) break;
  }

  if (ans.size() != N) {
    cout << -1 << endl;
    return 0;
  }

  for (int i = 0; i < ans.size(); ++i) {
    cout << ans[i] + 1;

    if (i < N - 1) {
      cout << " ";
    }
  }

