void solve(long long N, std::vector<long long> a){
	if (N == 2) {
		cout << -1 << endl;
		return;
	}
	vector<int> res;
	priority_queue<int, vector<int>, greater<>> q;
	rep(i, N) q.push(i);
	int ng = -1;
	while (q.size() != 3) {
		int r = q.top(); q.pop();
		if (r == ng) {
			int t = r;
			r = q.top();
			res.push_back(r);
			q.pop();
			q.push(t);
		} else {
			res.push_back(r);
		}
		ng = a[r] - 1;
	}
	rep(i, N-3) {
		if (i) cout << ' ';
		cout << res[i] + 1;
	}
	vector<int> rest(3);
	vector<int> ans(3, INT_MAX);
	rep(i, 3) {
		rest[i] = q.top(); q.pop();
	}
	sort(all(rest));
	do {
		if (rest[0] == ng) continue;
		if (rest[1] == a[rest[0]] - 1) continue;
		if (rest[2] == a[rest[1]] - 1) continue;
		chmin(ans, rest);
	} while (PERM(rest));
	rep(i, 3) cout << ' ' << ans[i] + 1;
	cout << endl;
}

