template<class Monoid> struct SegmentTree {
    using Function = function< Monoid(Monoid, Monoid) >;

    int N; vector<Monoid> segment;
    const Function func;
    const Monoid id;

    SegmentTree(int n, const Function func, const Monoid id) : func(func), id(id) {
        N = 1;
        while (N < n) N <<= 1;
        segment.assign(2 * N, id);
    }

    void set(int num, Monoid x) {
        segment[N + num] = x;
    }
    void build() {
        for (int k = N - 1; k > 0; k--) {
            segment[k] = func(segment[2*k], segment[2*k+1]);
        }
    }
    void update(int k, Monoid x) {
        k = k + N; segment[k] = x;
        while(k >>= 1) {
            segment[k] = func(segment[2*k], segment[2*k+1]);
        }
    }

    // query:[a, b)
    Monoid query(int a, int b) {
        Monoid L = id; Monoid R = id; a += N; b += N;
        for (; a < b; a >>= 1, b >>= 1) {
            if (a & 1) L = func(L, segment[a++]);
            if (b & 1) R = func(segment[--b], R);
        }
        return func(L, R);
    }
    // 0-based numbering;
    Monoid operator[](const int k) const {
        return segment[N+k];
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n; cin >> n;
    vector<int> a(n+1), p(n+1, 0), u(n+1, 0);
    for (int i = 1; i <= n; i++) cin >> a[i];
    if (n == 2) {
        if (a[1] == 2 && a[2] == 1) cout << -1 << "\n";
        else {
            if (a[1] == 2) cout << 2 << " " << 1 << "\n";
            else cout << 1 << " " << 2 << "\n";
        }
        return 0;
    }
    for (int i = 1; i <= n; i++) if (i != a[i]) p[a[i]]++;
    using dat = pair<int, int>;
    SegmentTree<dat> s(n+1, [](dat a, dat b){return max(a, b);}, {-1, 1});
    for (int i = 1; i <= n; i++) {
        s.set(i, {p[i], -i});
    }
    s.build();
    vector<int> v;
    int curr = 1;
    for (int i = 0; i < n; i++) {
        while (u[curr]) curr++;
        auto maxi = s.query(0, n+1);
        //cout << maxi.first << " " << maxi.second << "\n";
        int x = curr;
        if (i && a[v[i-1]] == x) {
            x++;
            while (u[x]) x++;
        }
        if (maxi.first >= (n-i-1)) x = -maxi.second;
        v.emplace_back(x);
        u[x] = true;
        auto y = a[x];
        auto z = s[y];
        s.update(x, {-1, 1});
        if (x != y) s.update(y, {z.first-1, z.second});        
    }
    for (int i = 0; i < n; i++) {
        if (i) cout << " ";
        cout << v[i];
    }
    cout << "\n";
    return 0;
}

