template <class T, class Op> struct SegmentTree {
  const Op op;
  const T e;
  const int n;
  vector<T> t;
  SegmentTree(int _n, Op _op, T _e) : op(_op), e(_e), n(_n), t(2 * n, e) {}
  T& operator[](int i) { return t[n + i]; }
  void build() { for (int i = n; i-- > 1; ) t[i] = op(t[2 * i], t[2 * i + 1]); }
  T fold(int l, int r) const {
    T a = e, b = e;
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) a = op(a, t[l++]);
      if (r & 1) b = op(t[--r], b);
    }
    return op(a, b);
  }
  void set(int i, T a) {
    t[i += n] = a;
    while (i >>= 1) t[i] = op(t[2 * i], t[2 * i + 1]);
  }
};
template <class T, class Op> auto make_segment_tree(int n, Op op, T e) {
  return SegmentTree<T, Op>(n, op, e);
}
