		if(s.find(v) != s.end()){
			p.erase(make_pair(deg[v],v));
			p.insert(make_pair(deg[v]-1,v));
			deg[v]--;
		}
	}
	for(int i=1; i<=n; ++i) cout<<ans[i]<<' ';
}

