int main() {
  int n;
  cin >> n;
  vector<int> forbid(n), deg(n);
  for (int i = 0; i < n; ++i) {
    int j;
    cin >> j; --j;
    deg[j]++;
    forbid[i] = j;
  }
  vector<int> ret(n);
  set<int> A;
  set<ii> B;
  vector<bool> visit(n);
  for (int i = 0; i < n; ++i) {
    A.insert(i);
    B.insert({deg[i], i});
  }
  function<bool(int, int)> search =
    [&](int pre, int pos) -> bool {
      if (pos == n) return true;
      // trace(pre, pos, ret, A, B);
      auto it = std::prev(B.end());
      int k = it->second;
      if (it->first == n - pos - 1) {
        if (pre != -1 && forbid[pre] == k) return false;
        ret[pos] = k;
        visit[k] = true;
        B.erase(it);
        int nk = forbid[k];
        if (!visit[nk]) {
          B.erase({deg[nk], nk});
          --deg[nk];
          B.insert({deg[nk], nk});
        }
        A.erase(k);
        return search(k, pos + 1);
      }
      int low = 0;
      while (true) {
        auto it = A.lower_bound(low);
        if (it == A.end()) break;
        int k = *it;
        low = k + 1;
        if (pre != -1 && forbid[pre] == k) continue;
        ret[pos] = k;
        visit[k] = true;
        A.erase(k);
        B.erase({deg[k], k});
        int nk = forbid[k];
        if (!visit[nk]) {
          B.erase({deg[nk], nk});
          --deg[nk];
          B.insert({deg[nk], nk});
        }
        if (search(k, pos + 1)) return true;
        if (!visit[nk]) {
          B.erase({deg[nk], nk});
          ++deg[nk];
          B.insert({deg[nk], nk});
        }
        B.insert({deg[k], k});
        A.insert(k);
      }
      return false;
    };
  bool found = search(-1, 0);
  if (found) {
    for (int i = 0; i < n; ++i) {
      cout << ret[i] + 1 << " \n"[i + 1 == n];
    }
  } else {
    cout << -1 << '\n';
  }
  return 0;
}

