bool dfs(int pos) {
	if (pos == N + 1) return true;

	int v = 0;
	while (true) {
		auto itr = Set.lower_bound(v);
		if (itr == Set.end()) break;
		if ((*itr) == A[B[pos - 1]]) {
			v = (*itr) + 1;
			continue;
		}

		int val = (*itr);

		v = val + 1;
		B[pos] = val;
		Set.erase(val);
		bool I = dfs(pos + 1);
		Set.insert(val);
		if (I == true) return true;
	}
	return false;
}

