int main() {
	int N; cin >> N;
	vector<int> A(N+1,0);
	for(int i = 1; i <= N; ++i) cin >> A[i];
	corner(N==2,-1);
	queue<int> q;

	vector<int> ans1;
	ans1.push_back(1);
	PQR<int> pq1;
	for(int i = 2; i <= N; ++i) pq1.push(i); 
	int inc = 0;
	while(1){
		inc++;
		if(inc>3) break;
		while (pq1.size()) {
			int b = ans1.back();
			int t = pq1.top();
			pq1.pop();
			if(A[b]!=t) {
				ans1.push_back(t);
				inc = 0;
				break;
			}
			else{
				q.push(t);
			}
		}
		while (q.size()){
			pq1.push(q.front());
			q.pop();
		}
	}

	vector<int> ans2;
	ans2.push_back(2);
	inc = 0;
	PQR<int> pq2;
	pq2.push(1); for(int i = 3; i <= N; ++i) pq2.push(i);
	while (1) {
		inc++;
		if(inc>3) break;
		while (pq2.size()) {
			int b = ans2.back();
			int t = pq2.top();
			pq2.pop();
			if(A[b]!=t) {
				ans2.push_back(t);
			}
			else{
				q.push(t);
			}
		}
		while (q.size()){
			pq2.push(q.front());
			q.pop();
		}
	}
	vector<int> ans;
	if(ans1.size()!=N) ans = ans2;
	else if(ans2.size()!=N) ans = ans1;
	else ans = min(ans1,ans2);
	for(int e:ans) cout << e << " ";
	cout << endl;
    return 0;
}

