    indeg[a[i]]--;
    bool z = dfs(a[i]);
    used[i] = false;
    indeg[a[i]]++;
    return z;
}

bool dfs(int ng) {
    if (st.empty()) return true;
    int N = st.size();
    if (ng != -1 && !used[ng] && indeg[ng] == N - 1) return false;
    auto it = st.begin();
    rep(t, N) {
        int i = *it;
        if (i != ng) {
            st.erase(i);
            if (f(i)) {
                ans.pb(i);
                return true;
            }
            st.insert(i);
        }
        it++;
    }
    return false;
}

vector<int> solve(vector<int> _a) {
    st.clear();
    a = _a;
    int N = a.size();
    used = vector<bool>(N);
    indeg = vector<int>(N);
    rep(i, N) indeg[a[i]]++;
    rep(i, N) st.insert(i);
    ans.clear();
    dfs(-1);
    reverse(all(ans));
    return ans;
}

vector<int> naive(vector<int> a) {
    int N = a.size();
    vector<int> p(N);
    rep(i, N) p[i] = i;
    do {
        bool ok = true;
        rep(i, N - 1) if (a[p[i]] == p[i + 1]) ok = false;
        if (ok) return p;
    } while (next_permutation(all(p)));
    return {};
}

