int read()
{
    int s=0,f=1;
    char ch=getchar();
    while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
    while(ch>='0'&&ch<='9'){s=s*10+ch-'0';ch=getchar();}
    return s*f;
}
struct node
{
    int id,val;
}arr[MAXN];
int vis[MAXN];
int main()
{
    int n;cin>>n;
    stack<int>s;
    for(int i=1;i<=n;i++)
    {
        cin>>arr[i].val;
        arr[i].id=i;
    }
    for(int i=n;i>=1;i--)s.push(i);
    stack<int>que;
    while(!s.empty()&&vis[s.top()]!=n+1)
    {
        //cout<<s.top()<<endl;
        if(!que.empty())
        {
            if(arr[que.top()].val!=s.top())
            {
                que.push(s.top());s.pop();
            }
            else
            {
                int id=s.top();s.pop();
                vis[id]++;
                if(!s.empty())
                {
                    que.push(s.top());s.pop();
                }
                s.push(id);
            }
        }
        else
        {
            que.push(s.top());s.pop();
        }
    }
    if(que.size()!=n)cout<<"-1"<<endl;
    else
    {
        stack<int>ans;
        while(!que.empty())
        {
            ans.push(que.top());que.pop();
        }
        while(!ans.empty())
        {
            cout<<ans.top()<<" ";ans.pop();
        }
        cout<<endl;
    }
    return 0;
}

