#define SIZE 200010


int main() {
  int N;
  int a[SIZE], counter[SIZE] = {};

  scanf("%d", &N);

  set<int> ss;

  for (int i=0; i<N; i++) ss.insert(i);

  for (int i=0; i<N; i++) {
    scanf("%d", a+i);
    a[i]--;
    counter[a[i]]++;
  }

  set<int> v;

  for (int i=0; i<N; i++)
    if (counter[i]) v.insert(i);

  if (N == 2) {
    puts("-1");
    return 0;
  }

  int now = -1;

  vector<int> ans;

  for (int i=0; i<N-3; i++) {
    auto it = ss.begin();
    int p1 = *it; it++;
    int p2 = *it;

    int pp;

    if (now == -1 || p1 != a[now]) {
      auto t = v.begin();

      if (counter[a[p1]] == 1 && v.size() == 2) {
        pp = p2;
      } else {
        pp = p1;
      }
    } else {
      pp = p2;
    }

    ans.push_back(pp);
    ss.erase(pp);
    now = pp;

    counter[a[pp]]--;

    if (counter[a[pp]] == 0) {
      v.erase(a[pp]);
    }
  }

  int vv[3];
  auto it = ss.begin();
  for (int i=0; i<3; i++) {
    vv[i] = *it;
    it++;
  }


  do{
    bool ok = N <= 3 || a[*ans.rbegin()] != vv[0];

    for (int i=0; i<2; i++) {
      ok &= a[vv[i]] != vv[i+1];
    }

    if (ok) {
      ans.push_back(vv[0]);
      ans.push_back(vv[1]);
      ans.push_back(vv[2]);
      break;
    }

  }while(next_permutation(vv, vv+3));

  if (ans.size() < N) {
    puts("-1");
    return 0;
  }

  for (int i=0; i<N; i++) {
    printf("%d%c", ans[i]+1, " \n"[N==i+1]);
  }

  return 0;
}

