int main() {
    cin.sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int n;
    cin >> n;

    vector <int> a(n + 1, 0);
    vector <int> count(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        count[a[i]]++;
    }

    int cur = 1;
    for (int i = 1; i <= n; i++) {
        if (count[i] == n) {
            cur = i;
        } else if (count[i] == n - 1 && a[i] != i) {
            cur = i;
        }
    }

    if (n == 2) {
        cout << -1 << '\n';
        return 0;
    } else if (n == 3) {
        vector <int> tmp;
        for (int i = 1; i <= n; i++) tmp.push_back(i);

        do {
            if (a[tmp[0]] != tmp[1] && a[tmp[1]] != tmp[2]) {
                cout << tmp[0] << ' ' << tmp[1] << ' ' << tmp[2] << '\n';
                return 0;
            }
        } while (next_permutation(tmp.begin(), tmp.end()));
    } else if (n == 4) {
        vector <int> tmp;
        for (int i = 1; i <= n; i++) tmp.push_back(i);

        do {
            if (a[tmp[0]] != tmp[1] && a[tmp[1]] != tmp[2] && a[tmp[2]] != tmp[3]) {
                cout << tmp[0] << ' ' << tmp[1] << ' ' << tmp[2] << ' ' << tmp[3] << '\n';
                return 0;
            }
        } while (next_permutation(tmp.begin(), tmp.end()));
    }

    cout << cur << ' ';

    priority_queue <int, vector<int>, greater<int>> q;
    for (int i = 1; i <= n; i++) {
        if (i != cur) q.push(i);
    }

    while (q.size() > 4) {
        int p = q.top();
        q.pop();

        if (a[cur] == p) {
            int p2 = q.top();
            q.pop();
            q.push(p);
            cout << p2 << ' ';
            cur = p2;
        } else {
            cout << p << ' ';
            cur = p;
        }
    }

    vector <int> tmp;
    while (q.size()) {
        tmp.push_back(q.top());
        q.pop();
    }

    do {
        if (a[cur] != tmp[0] && a[tmp[0]] != tmp[1] && a[tmp[1]] != tmp[2] && a[tmp[2]] != tmp[3]) {
            cout << tmp[0] << ' ' << tmp[1] << ' ' << tmp[2] << ' ' << tmp[3] << '\n';
            return 0;
        }
    } while (next_permutation(tmp.begin(), tmp.end()));

    return 0;
}

