        out << value.first << ' ' << value.second;
    }

public:
    Output(ostream& out) : out(out) {
        out << fixed << setprecision(20);
    }

    void print() {}

    template <typename T, typename...Targs>
    void print(const T& first, const Targs... args) {
        printSingle(first);
        if (sizeof...(args) != 0) {
            out << ' ';
            print(args...);
        }
    }

    template <typename...Targs>
    void printLine(const Targs... args) {
        print(args...);
        out << '\n';
    }

    void flush() {
        out.flush();
    }
};


class DArrangement {
public:
    void solve(istream& inp, ostream& outp) {
        Input in(inp);
        Output out(outp);

        int n = in.readInt();
        auto a = in.readIntArray(n);
        decreaseByOne(a);

        if (n == 2) {
            out.printLine(-1);
            return;
        }
        arr<bool> was(n, false);
        for (int i : a) {
            was[i] = true;
        }
        auto addOne = [](arri& a) {
            for (int& i : a) {
                i++;
            }
        };
        if (count(all(was), false)) {
            int at = find(all(was), false) - was.begin();
            arri answer(n);
            set<int> rem;
            for (int i : range(n)) {
                rem.insert(i);
            }
            answer[1] = at;
            rem.erase(at);
            for (int i : range(2, n)) {
                int first = *rem.begin();
                if (a[answer[i - 1]] != first) {
                    answer[i] = first;
                    rem.erase(first);
                } else {
                    int last = *rem.rbegin();
                    answer[i] = last;
                    rem.erase(last);
                }
            }
            answer[0] = *rem.begin();
            for (int i : range(n - 1)) {
                if (a[answer[i]] == answer[i + 1]) {
                    while (true);
                }
            }
            addOne(answer);
            out.printLine(answer);
            return;
        }
        for (int j : range(n)) {
            if (a[a[j]] != j) {
                arri answer(n);
                set<int> rem;
                for (int i : range(n)) {
                    rem.insert(i);
                }
                answer[1] = a[j];
                answer[2] = j;
                rem.erase(a[j]);
                rem.erase(j);
                for (int i : range(3, n)) {
                    int first = *rem.begin();
                    if (a[answer[i - 1]] != first) {
                        answer[i] = first;
                        rem.erase(first);
                    } else {
                        int last = *rem.rbegin();
                        answer[i] = last;
                        rem.erase(last);
                    }
                }
                answer[0] = *rem.begin();
                for (int i : range(n - 1)) {
                    if (a[answer[i]] == answer[i + 1]) {
                        throw ":(";
                    }
                }
                addOne(answer);
                out.printLine(answer);
                return;
            }
        }
        arr<bool> used(n, false);
        arri answer(n);
        int at = 0;
        for (int i : range(n)) {
            if (!used[i]) {
                answer[at] = i;
                answer[at + n / 2] = a[i];
                at++;
                used[i] = true;
                used[a[i]] = true;
            }
        }
        for (int i : range(n - 1)) {
            if (a[answer[i]] == answer[i + 1]) {
                out.printLine(":(");
            }
        }
        addOne(answer);
        out.printLine(answer);
    }
};


