void dfs(int c, int lim) {
    if (c == n) {
        for (int i = 0; i < n; ++i)
            std::cout << ans[i] + 1 << " \n"[i == n - 1];
        exit(0);
    }
    for (int i = 0; i < int(b.size()); ++i) {
        if (used[b[i]] || b[i] == lim)
            continue;
        ans[c] = b[i];
        used[b[i]] = true;
        dfs(c + 1, a[b[i]]);
        used[b[i]] = false;
    }
}
int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
