        used[u] = true;
        if (!used[a[u]]) {
            d.erase({-deg[a[u]], a[u]});
            --deg[a[u]];
            d.emplace(-deg[a[u]], a[u]);
        }
        lim = a[u];
        ans[i] = u;
    }
