				if(a[b[i-1]-1]!=t){
					b[i] = t;
					index = i;
					break;
				}
			}
			se.erase(t);
			for(ll i=index; i<n-4; i++){
				auto itr = se.begin();
				if(*itr==a[b[i]-1]) itr++;
				b[i+1] = *itr;
				se.erase(itr);
			}
			for(auto i : se){
				nxt.push_back(i);
			}
		}
		do{
			bool flag = true;
			REP(i,n-4,n-1){
				if(nxt[i-n+4]==a[b[i]-1]){
					flag = false;
					break;
				}else{
					b[i+1] = nxt[i-n+4];
				}
			}
			if(flag) break;
			else REP(i,n-3,n) b[i] = 0;
		}while(next_permutation(all(nxt)));
	}
	for(auto i : b) cout << i << " ";
	cout << endl;
}

