namespace BST {
#define par(x) (a[x].fa)
#define lch(x) (a[x].ch[0])
#define rch(x) (a[x].ch[1])

// info
int root;
int memory[N], pool;
struct node { int fa, ch[2], val, rec, size; } a[N], Zero;

// maintain
inline int creNode(int val) {
	int u = memory[pool--];
	a[u].val = val, a[u].rec = a[u].size = 1;
	return u;
}
inline void connect(int u, int f, bool ind) { par(u) = f, a[f].ch[ind] = u; }
inline void update(int u) { a[u].size = a[lch(u)].size + a[u].rec + a[rch(u)].size; }

inline void init() {
	for(int i = n + 50; i; --i) memory[++pool] = i;
	connect(creNode(-inf), root = creNode(inf), 0), update(root);
}

// splay
inline void rotate(int u) {
	int f = par(u), g = par(f); bool ind = (rch(f) == u);
	connect(a[u].ch[!ind], f, ind), connect(f, u, !ind), connect(u, g, rch(g) == f);
	update(f);
}
inline void splay(int u, int tar = 0) {
	int f, g;
	while((f = par(u)) != tar) {
		if((g = par(f)) != tar)
			rotate((rch(g) == f) ^ (rch(f) == u) ? u : f);
		rotate(u);
	}
	if(!tar) root = u;
	update(u);
}

// operations
inline void insert(int val) {
	int u = root, las = 0;
	while(u && a[u].val != val)
		las = u, u = a[las].ch[val > a[las].val];
	if(!u) {
		u = creNode(val);
		connect(u, las, val > a[las].val);
	} else {
		++a[u].rec, ++a[u].size;
	}
	splay(u);
	return;
}

inline int find(int val) {
	int u = root;
	while(u && a[u].val != val)
		u = a[u].ch[val > a[u].val];
	return u;
}
inline int queryRank(int val) {
	splay(find(val));
	return a[lch(root)].size;
}
inline int queryNum(int rem) { // k - th 
	int u = root;
	while(true) {
		if(a[lch(u)].size >= rem) u = lch(u);
		else if(a[lch(u)].size + a[u].rec >= rem) return splay(u), u;
		else rem -= a[lch(u)].size + a[u].rec, u = rch(u);
	}
}
inline int near(int u, bool ind) {
	splay(u); u = a[u].ch[ind];
	ind = !ind;
	while(a[u].ch[ind]) u = a[u].ch[ind];
	return u;
}

inline void erase(int val) {
	int u = find(val);
	if(a[u].rec > 1) {
		--a[u].rec, --a[u].size;
		splay(u);
	} else {
		int lNode = near(u, false), rNode = near(u, true);
		splay(lNode), splay(rNode, lNode);
		a[u] = Zero, memory[++pool] = u;
		lch(rNode) = 0, update(rNode), update(lNode);
	}
}

#undef par
#undef lch
#undef rch
