void rm(int t){
	lft.erase(t);
	st.erase(make_pair(fr[a[t]], a[t]));
	--fr[a[t]];
	st.insert(make_pair(fr[a[t]], a[t]));
}

void ad(int t){
	lft.insert(t);
	st.erase(make_pair(fr[a[t]], a[t]));
	++fr[a[t]];
	st.insert(make_pair(fr[a[t]], a[t]));
}

bool go(int i = 1, int bad = 0){
	if (i == n){
		int t = *lft.begin();
		if (t == bad)return false;
		an[i] = t;
		return true;
	}
	int m = n - i + 1;
	int t = st.rbegin()->second;
	if (fr[t] == m - 1){
		an[i] = t;
		rm(t);
		bool ok = go(i + 1, a[t]);
		ad(t);
		return ok;
	}
	vector<int> v;
	int z = 5;
	for (auto it = lft.begin(); it != lft.end() && z; ++it, --z)v.push_back(*it);
	for (int u: v)if (bad != u){
