int main()
{
    auto N = in<int>();
    std::vector<int> a(N);
    for (int i = 0; i < N; i++) { a[i] = in<int>() - 1; }
    unionfind uf(N);
    graph g(N);
    for (int i = 0; i < N; i++) {
        uf.unite(i, a[i]);
        g.add_edge(a[i], i);
    }
    std::vector<std::vector<int>> cs(N);
    for (int i = 0; i < N; i++) { cs[uf.root_of(i)].push_back(i); }
    std::vector<std::vector<int>> cycles(N);
    std::vector<bool> isc(N, false);
    std::vector<std::vector<int>> oks;
    std::vector<int> fs, bs;
    for (int j = 0; j < N; j++) {
        const auto& vs = cs[j];
        if (vs.empty()) { continue; }
        int v = vs[0];
        for (int i = 0; i < vs.size(); i++) { v = a[v]; }
        for (int i = 0; i < vs.size(); i++) {
            if (not isc[v]) { cycles[j].push_back(v); }
            isc[v] = true, v = a[v];
        }
        if (cycles[j].size() == 2) {
            fs.push_back(cycles[j][0]);
            bs.push_back(cycles[j][1]);
            if (vs.size() > cycles[j].size()) { oks.push_back({}); }
        } else {
            std::reverse(cycles[j].begin(), cycles[j].end());
            oks.push_back(cycles[j]);
        }
        for (int v : cycles[j]) {
            mfp([&](auto&& self, const int s) -> void {
                for (const int to : g[s]) {
                    if (isc[to]) { continue; }
                    oks.back().push_back(to);
                    self(self, to);
                }
            })(v);
        }
    }
    SHOW(fs, bs, oks);
    if (oks.empty() and fs.size() == 1) { return outln(-1); }
    std::vector<int> ans;
    for (const int f : fs) { ans.push_back(f + 1); }
    for (const auto& ok : oks) {
        for (const int v : ok) { ans.push_back(v + 1); }
    }
    for (const int b : bs) { ans.push_back(b + 1); }
    out(ans);
    auto check = [&]() {
        std::vector<int> pos(N);
        for (int i = 0; i < N; i++) { pos[ans[i] - 1] = i; }
        for (int i = 0; i < N; i++) { assert(pos[a[i]] - pos[i] != 1); }
    };
    check();
    return 0;
}

