bool work(int k,int len,int last,int rst,int j){
	if (k>len){
		ans[cnt].clear();
		int i; for (i=1; i<=len; i++) ans[cnt].pb(path[i]);
		return 1;
	}
	if ((*T.rbegin()).fi==S.size()-1){
	//	cerr<<"!\n";
		int x; for (int p:S) if (dgr[p]==S.size()-1){ x=p; break; }
	//	cerr<<x<<'\n';
		if (x==a[last]) return 0;
		path[k]=x; S.erase(x); T.erase(mpr(dgr[x],x));
		if (S.find(a[x])!=S.end()){
			T.erase(mpr(dgr[a[x]]--,a[x]));	
			T.insert(mpr(dgr[a[x]],a[x]));
		}
		return work(k+1,len,x,0,j);	
	}
	for (auto it=S.begin(); it!=S.end(); ) if ((*it)!=a[last]){
		path[k]=*it; S.erase(it);
		int x=*it; T.erase(mpr(dgr[x],x));
		bool flag=0;
		if (S.find(a[x])!=S.end()){
			flag=1;
			T.erase(mpr(dgr[a[x]]--,a[x]));	
			T.insert(mpr(dgr[a[x]],a[x]));
		}
		if (work(k+1,len,*it,rst,j)) return 1;
		S.insert(path[k]); it=S.upper_bound(path[k]);
		T.insert(mpr(dgr[x],x));
		if (flag){
			T.erase(mpr(dgr[a[x]]++,a[x]));
			T.insert(mpr(dgr[a[x]],a[x]));	
		}
	} else it++;
	return 0;
}
