void solve(long long N, std::vector<long long> a){
  REP(N){
    --a[i];
  }
  set<ll> s,t;
  REP(N){
    s.insert(i);
  }
  REP(N){
    s.erase(a[i]);
    t.insert(a[i]);
  }
  if(s.empty()&&N==2){
    cout<<-1<<endl;
    return;
  }
  deque<ll> ans(N);
  for (auto &&i : s)
  {
    ans.push_back(i);
  }
  while(!t.empty()){
    set<ll> u;
    vector<ll> stack;
    ll cur=*t.begin();
    while(u.find(cur)==u.end()){
      stack.push_back(cur);
      t.erase(cur);
      u.insert(cur);
      cur=a[cur];
    }
    if(stack.size()==2){
      if(a[ans.back()]!=stack[0]){
        ans.push_back(stack[0]);
        ans.push_front(stack[1]);
      }else{
        ans.push_back(stack[1]);
        ans.push_front(stack[0]);
      }
    }else{
      REP(stack.size()){
        ans.push_front(stack[i]);
      }
    }
  }
  REP(N){
    cout<<ans[i]+1<<" ";
  }
  cout<<endl;
}

