			if(a[d[i]]==d[j]&&a[d[j]]==d[i]&&!flag)
			{
				flag=true;
				int k;
				for(k=0;k<d.size();k++)
					if(k!=i&&k!=j) break;
				if(a[d[k]]!=d[j]) ans.push_back(d[i]);
				else ans.push_back(d[j]);
				ans.push_back(d[k]);
				if(a[d[k]]!=d[j]) ans.push_back(d[j]);
				else ans.push_back(d[i]);
				break;
			}
	if(!flag)
	{
		for(int i=n-2;i<=n;i++)
		{
			int u;
			if(-(e.begin()->first)==n-i) u=e.begin()->second;
			else if(*S.begin()!=pre) u=*S.begin();
			else if(S.size()>=2) u=*(++S.begin());
