void solve(long long N, std::vector<long long> a){
	if (N == 2) {
		cout << -1 << endl;
		return;
	}
	vector<int> res;
	priority_queue<int, vector<int>, greater<>> q;
	rep(i, N) q.push(i);
	int ng = -1;
	while (q.size() > 8) {
		int r = q.top(); q.pop();
		if (r == ng) {
			int t = r;
			r = q.top();
			res.push_back(r);
			q.pop();
			q.push(t);
		} else {
			res.push_back(r);
		}
		ng = a[r] - 1;
	}
	rep(i, res.size()) {
		if (i) cout << ' ';
		cout << res[i] + 1;
	}
	int qs = q.size();
	vector<int> rest(q.size());
	vector<int> ans(q.size(), INT_MAX);
	rep(i, qs) {
		rest[i] = q.top(); q.pop();
	}
	sort(all(rest));
	do {
		if (rest[0] == ng) continue;
		bool f = true;
		reps(i, 1, qs) {
			if (rest[i] == a[rest[i-1]] - 1) f = false;
		}
		if (f) chmin(ans, rest);
	} while (PERM(rest));
	rep(i, ans.size()) {
		if (res.size() || i) cout << ' ';
		cout << ans[i] + 1;
	}
	cout << endl;
}

