struct SegmentTree{
    pair<int, int> ide = {-1, -1};

    inline void updatef(pair<int, int> &x, int y){
        x.first = y;
    }

    inline pair<int, int> queryf(pair<int, int> x, pair<int, int> y){
        return max(x, y);
    }

    int n;
    vector<pair<int, int>> node;

    SegmentTree(int sz, vi &v){
        n = 1;
        while(n < sz) n <<= 1;
        node.resize(2 * n - 1, ide);
        for(int i = 0; i < sz; i++) node[i + n - 1] = {v[i], i};
        for(int i = n - 2; i >= 0; i--) node[i] = queryf(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void reset(int k){
        k += n - 1;
        node[k] = ide;
        while(k){
            k = (k - 1) / 2;
            node[k] = queryf(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    void update(int k){
        k += n - 1;
        updatef(node[k], -1);
        while(k){
            k = (k - 1) / 2;
            node[k] = queryf(node[2 * k + 1], node[2 * k + 2]);
        }
    }

    pair<int, int> get(int a, int b, int k = 0, int l = 0, int r = -1){
        if(r < 0)r = n;
        if(r <= a || b <= l) return ide;
        if(a <= l && r <= b) return node[k];
        pair<int, int> xl = get(a, b, 2 * k + 1, l, (l + r) / 2);
        pair<int, int> xr = get(a, b, 2 * k + 2, (l + r) / 2, r);
        return queryf(xl, xr);
    }
};


