const int MAXN = 123456;
int ans[MAXN], indeg[MAXN];
int a[MAXN], rem[5];
int visit[MAXN];
set<pii> pq;
set<int> cand;
int ans_idx = 0, pre = 0;

void solve(int sz) {
    while ((int)cand.size() > sz) {
        int tpcand = *cand.begin(), nxt;
        auto tp = pq.rbegin();
        if (tp->first == (int)cand.size() - 1) {
            int cur = tp->second;
            pq.erase(prev(pq.end()));
            ans[ans_idx++] = cur;
            nxt = cur;
            cand.erase(cur);
        } else if (a[pre] == tpcand) {
            cand.erase(cand.begin());
            int cur = *cand.begin();
            cand.erase(cand.begin());
            ans[ans_idx++] = cur;
            cand.insert(tpcand);
            nxt = cur;
        } else {
            cand.erase(cand.begin());
            ans[ans_idx++] = tpcand;
            nxt = tpcand;
        }
        visit[nxt] = 1;
        if (!visit[a[nxt]]) {
            int to = a[nxt];
            pq.erase(make_pair(indeg[to], to));
            indeg[to]--;
            pq.insert(make_pair(indeg[to], to));
        }
        pq.erase(make_pair(indeg[nxt], nxt));
        pre = nxt;
    }
}

int main() {
    int N;
    scanf("%d", &N);
    for (int i = 1; i <= N; i++) {
        scanf("%d", &a[i]);
        indeg[a[i]]++;
    }
    if (N == 2) return !printf("-1\n");
    for (int i = 1; i <= N; i++) {
        pq.insert(make_pair(indeg[i], i));
        cand.insert(i);
    }
    solve(3);
    for (int i = 0; i < 3; i++) {
        int tp = *cand.begin();
        cand.erase(cand.begin());
        rem[i] = tp;
    }
    if (a[rem[2]] == rem[1] && a[rem[1]] == rem[2]) {
        if (a[pre] == rem[1]) {
            ans[ans_idx++] = rem[2];
            ans[ans_idx++] = rem[0];
            ans[ans_idx++] = rem[1];
        } else {
            ans[ans_idx++] = rem[1];
            ans[ans_idx++] = rem[0];
            ans[ans_idx++] = rem[2];
        }
    } else {
        for (int i = 0; i < 3; i++)
            cand.insert(rem[i]);
        solve(0);
    }
    for (int i = 0; i < N; i++)
        printf("%d ", ans[i]);
    puts("");
    return 0;
}

