bool dfs(int u){
	if(u==n+1) return 1;
	int ex=a[b[u-1]];
	if(t>h){
		if(q[h]==ex){
			if(t>h+1){
				b[u]=q[h+1];
				q[h+1]=q[h];
				h++;
				if(dfs(u+1)) return 1;
				q[h+1]=b[u];
				h--;
			}
		}
		else{
			b[u]=q[h++];
			if(dfs(u+1)) return 1;
			h--;
		}
	}
	if(ex==p){
		if(p+1>n) return 0;
		q[t++]=p;
		b[u]=p+1;
		p+=2;
		if(dfs(u+1)) return 1;
		p-=2;
		t--;
	}
	else{
		if(p>n) return 0;
		b[u]=p++;
		if(dfs(u+1)) return 1;
		--p;
	}
	return 0;
}
