void dfs(int cnt,vector<int>& l,vector<int> &r,vector<int>& ans,multiset<int>& ms){
    if(cnt==n){
        for(int i=0;i<n;i++) cout<<ans[i]<<" ";
        cout<<endl;
        exit(0);
    }
    int iter=0;
    while(iter<n){
        iter=r[iter];
        if(iter>n) break;
        if(ms.size()>3){
            if(*ms.begin()==*next(ms.rbegin())){
                if(iter==*ms.begin()) continue;
            }
            if(*next(ms.begin())==*ms.rbegin()){
                if(iter==*ms.rbegin()) continue;
            }
        }
        if(!ans.empty() && a[ans.back()-1]==iter) continue;
        int pre0=r[l[iter]];
        r[l[iter]]=r[iter];
        int pre1=l[r[iter]];
        l[r[iter]]=l[iter];
        ans.push_back(iter);
        ms.erase(ms.find(a[iter-1]));

        dfs(cnt+1,l,r,ans,ms);

        ms.insert(a[iter-1]);
        ans.pop_back();
        r[l[iter]]=pre0;
        l[r[iter]]=pre1;
    }

}
int main(){
    cin>>n;
    a.resize(n);
    for(int i=0;i<n;i++) cin>>a[i];

