    }
    vector<int> l(n+1);
    vector<int> r(n+1);
    for(int i=0;i<=n;i++) l[i]=i-1;
    for(int i=0;i<=n;i++) r[i]=i+1;
    multiset<int> ms;
    for(int i=0;i<n;i++) ms.insert(a[i]);
    vector<int> ans;
    dfs(0,l,r,ans,ms);

    return 0;
}

