  for (auto& e : a) {
    cin >> e;
    e--;
  }
  if (n == 2) {
    cout << -1 << endl;
    return 0;
  }

  vector<bool> paired(n);
  for (int i = 0; i < n; i++) paired[i] = a[a[i]] == i;

  vector<int> r;
  set<int> s;
  for (int i = 0; i < n; i++) s.insert(i);
  while (!s.empty()) {
    auto it = s.begin();
    int e1 = *it;
    if (s.size() == 1) {
      r.push_back(e1);
      break;
    }
    it++;
    int e2 = *it;

    if (s.size() == 3 && !paired[e1] && paired[e2]) {
      r.push_back(e2);
    } else if (!r.empty() && e1 == a[r.back()]) {
      r.push_back(e2);
    } else {
      r.push_back(e1);
    }

    s.erase(r.back());
    if (paired[r.back()]) paired[r.back()] = paired[a[r.back()]] = false;
  }

  for (auto e : r) cout << e + 1 << ' ';
  cout << endl;
