struct RangeMax {
    using Value = pair<int,int>;
    constexpr static Value unit() { return {-INF,-1}; }
    constexpr static Value merge(Value x, Value y) { return max(x,y); }
};

int32_t main() {
    int n; cin >> n;
    vector<int> a(n); cin >> a;
    rep (i,n) a[i]--;
    if (n == 2) quit(-1);

    Segtree<RangeMax> seg(n);
    {
        vector<pair<int,int> > cnt(n);
        rep (i,n) cnt[a[i]].fst++;
        rep (i,n) cnt[i].snd = i;
        seg.init(all(cnt));
    }
    set<int> s;
    rep (i,n) s.insert(i);

    vector<int> ans;
    auto add = [&](int i) {
        ans.eb(i);
        seg.set(a[i],{seg[a[i]].fst-1,seg[a[i]].snd});
        seg.set(i,RangeMax::unit());
        s.erase(i);
    };
    rep (i,n) {
        assert(sz(s) == n-sz(ans));
        const int NN = 5;
        if (sz(s) <= NN) {
            vector<int> v;
            for (int x : s) v.eb(x);
            sort(all(v));
            dump(v);
            do {
                bool flag = false;
                rep (i,sz(v)-1) if (a[v[i]] == v[i+1]) flag = true;
                if (!ans.empty() && a[ans.back()] == v[0]) flag = true;
                if (!flag) {
                    for (int x : v) ans.eb(x);
                    rep (i,sz(ans)) cout << (i ? " " : "") << ans[i]+1;
//                    for (int x : ans) cout << x+1 << " ";
                    cout << endl;
                    exit(0);
                }
            } while (next_permutation(all(v)));
        } else if (i == 0) {
            add(i);
        } else {
            auto p = seg.get(0,n);
            if (p.fst == sz(s)-1) {
                add(p.snd);
            } else {
                int x = *s.begin();
                assert(!ans.empty());
                if (a[ans.back()] == x) {
                    x = *++s.begin();
                }
                add(x);
            }
        }
    }
    assert(0);

}

