struct Heap_int{
  priority_queue < int,vector<int>,greater<int> > que,lazy;
  void push(int x){ que.push(x); }
  void pop(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    assert(!que.empty());
    que.pop();
  }
  void erase(int x){ lazy.push(x); }
  int top(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    return que.top();
  }
  int top2(){
    int tmp = top(); pop();
    int ret = top(); push(tmp);
    return ret;
  }
  int size(){ return que.size() - lazy.size(); }
};
struct Heap_P{
  priority_queue <P> que,lazy;
  void push(P x){ que.push(x); }
  void pop(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    assert(!que.empty());
    que.pop();
  }
  void erase(P x){ lazy.push(x); }
  P top(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    return que.top();
  }
  int size(){ return que.size() - lazy.size(); }
};
