        if(ban == v) u = w;
        else u = v;
      }
    }
  }
  if(!vis[a[u]]){
    deg.erase(mp(in[a[u]],a[u]));
    in[a[u]]--;
    deg.push(mp(in[a[u]],a[u]));
  }
  vis[u] = true;
  hp.erase(u);
  deg.erase(mp(in[u],u));
  in[u] = 0;
