#define mid ((l + r) >> 1)
using namespace std;
typedef long long LL;

LL n,m,k;
LL a[500005],b[500005];
LL cnt[500005] = {0};

LL cnn[800005],cid[800005],tot[800005],mii[800005];

void pushup(LL x){
	cnn[x] = max(cnn[lson],cnn[rson]);
	if(cnn[lson] > cnn[rson]) cid[x] = cid[lson];
	else cid[x] = cid[rson];

	tot[x] = tot[lson] + tot[rson];
	if(tot[lson]) mii[x] = mii[lson];
	else mii[x] = mii[rson];
}

void build(LL x,LL l,LL r){
	if(l == r){
		cnn[x] = cnt[l];
		cid[x] = l;
		tot[x] = 1;
		mii[x] = l;
		return;
	}
	build(lson,l,mid);
	build(rson,mid + 1,r);
	pushup(x);
}

LL getmin(LL x,LL l,LL r,LL L,LL R){
	if(L > R) return n + 1;
	if(L <= l && r <= R) return mii[x];
	LL ret = n + 1;
	if(L <= mid) ret = min(ret,getmin(lson,l,mid,L,R));
	if(R > mid) ret = min(ret,getmin(rson,mid + 1,r,L,R));
	return ret;
}

LL getmax(){
	return cid[1];
}

void modify(LL x,LL l,LL r,LL L,LL R,LL v){
	if(L <= l && r <= R){
		cnn[x] --;
		return;
	}
	if(L <= mid) modify(lson,l,mid,L,R,v);
	if(R > mid) modify(rson,mid + 1,r,L,R,v);
	pushup(x);
}

void modify2(LL x,LL l,LL r,LL L,LL R,LL v){
	if(L <= l && r <= R){
		tot[x] --;
		mii[x] = n + 1;
		cnn[x] = -1;
		cid[x] = n + 1;
		return;
	}
	if(L <= mid) modify2(lson,l,mid,L,R,v);
	if(R > mid) modify2(rson,mid + 1,r,L,R,v);
	pushup(x);
}

