ll find(ll num){
    vector<ll> tmp;
    ll res = -1;
    ll cnt = 0;
    while(true){
        ll v = waiting.back();
        waiting.pop_back();
        if(used[v]){
            // 使われているのでノーカウント
        }else{
            // 使われていないのでカウント
            res = v;
            tmp.pb(v);
            cnt ++;
            if(cnt == num)break;
        }
    }
    res = tmp[num - 1];
    for(ll i=0;i<tmp.size();i++){
        waiting.pb(tmp[tmp.size() - 1 -i]);
    }
    return res;
}

