    priority_queue<int, vector<int>, greater<int> > que;
    rep(i, N){
        cin >> a[i]; a[i]--;
        seg1.change(i, a[i]), seg2.change(i, -a[i]);
        que.push(i);
    }
    if(N == 2) {cout << -1 << endl; return 0;}
    int pre = -1;
    bool used[N];
    fill(used, used+N, false);
    int n = N;
    vector<int> ans;
    while(n > 3){
        vector<int> memo;
        while(true){
            int i = que.top();
            que.pop();
            if(used[i]) continue;
            if(pre != -1 && a[pre] == i){
                memo.pb(i);
                continue;
            }
            int j = a[i];
            seg1.change(i, inf), seg2.change(i, inf);
            seg1.change(j, inf), seg2.change(j, inf);
            if(!used[j] && seg1.query(0, N) == j && seg2.query(0, N) == -j){
                if(pre != -1 && a[pre] == j) {cout << -1 << endl; return 0;}
                memo.pb(i);
                ans.pb(j);
                pre = j, used[j] = true, n--;
                seg1.change(i, a[i]), seg2.change(i, -a[i]);
            }
            else{
                ans.pb(i);
                pre = i, used[i] = true, n--;
                seg1.change(j, a[j]), seg2.change(j, -a[j]);
            }
            break;
        }
        for(auto &e: memo) que.push(e);
    }
    vector<int> rem;
    while(!que.empty()){
        int i = que.top(); que.pop();
        if(!used[i]) rem.pb(i);
    }
    bool able = false;
    do{
        if(pre != -1 && a[pre] == rem[0]) continue;
        if(a[rem[0]] == rem[1] || a[rem[1]] == rem[2]) continue;
        rep(i, 3) ans.pb(rem[i]);
        able = true;
        break;
    } while(next_permutation(all(rem)));
    if(!able) cout << -1 << endl;
    else{
        for(auto &e: ans) cout << e+1 << ' '; cout << endl;
    }
}

