        {
            while(!del.empty()&&!q.empty()&&del.top()==q.top()) del.pop(),q.pop();
            if(v.size()==0||a[v.back()]!=q.top()) v.push_back(q.top()),q.pop();
            else
            {
                int s=q.top();q.pop();
