bool work(int k,int len,int last){
	if (k>len){
		ans[cnt].clear();
		int i; for (i=1; i<=len; i++) ans[cnt].pb(path[i]);
		return 1;
	}
	for (auto it=S.begin(); it!=S.end(); ) if ((*it)!=a[last]){
		path[k]=*it; S.erase(it);
		if (work(k+1,len,*it)) return 1;
		S.insert(path[k]); it=S.upper_bound(path[k]);
	} else it++;
	return 0;
}
bool dfs2(int x,int y,int A,int B,int u,int v,int last){
	if (x==A && y==B){
		ans[cnt].clear();
		int i=0;
		for (i=0; i<A+B; i++) ans[cnt].pb(path[i]); return 1;	
	}
	if (y==B || x<A && f[x]<g[y]){
		if (u!=min(last,f[x]) || v!=max(last,f[x])){
			path[x+y]=f[x];
			if (dfs2(x+1,y,A,B,u,v,f[x])) return 1;	
		}
		if (y<B && (u!=min(last,g[y]) || v!=max(last,g[y]))){
			path[x+y]=g[y];
			if (dfs2(x,y+1,A,B,u,v,g[y])) return 1;	
		}
	} else{
		if (u!=min(last,g[y]) || v!=max(last,g[y])){
			path[x+y]=g[y];
			if (dfs2(x,y+1,A,B,u,v,g[y])) return 1;	
