template <typename T>
class SegmentTree {
private:
    using F = function<T(T, T)>;
    int n, sz;
    vector<T> node;
    T u;
    F f;

    T query(int a, int b, int i, int l, int r) {
        if(r <= a || b <= l) {
            return u;
        }
        else if(a <= l && r <= b) {
            return node[i];
        }
        else {
            T vl = query(a, b, 2 * i + 1, l, (l + r) / 2);
            T vr = query(a, b, 2 * i + 2, (l + r) / 2, r);
            return f(vl, vr);
        }
    }

public:
    /**
     *
     * @param v  初期配列
     * @param func  nodeに対する操作
     * @param u2  Tの単位元
     */
    SegmentTree(vector<T> &v, const F func, T u2) : f(func), u(u2) {
        sz = v.size();
        n = 1;
        while(n < sz) {
            n *= 2;
        }
        node.resize(2 * n - 1, u2);
        for(int i = 0; i < sz; i++) {
            node[i + n - 1] = v[i];
        }
        for(int i = n - 2; i >= 0; i--) {
            node[i] = f(node[2 * i + 1], node[2 * i + 2]);
        }
    }

    void update(int i, T val) {
        i += (n - 1);
        node[i] = val;
        while(i > 0) {
            i = (i - 1) / 2;
            node[i] = f(node[2 * i + 1], node[2 * i + 2]);
        }
    }

    T query(int l, int r){
        return query(l, r, 0, 0, n);
    }

    T operator[](const int &i) const { return node[i + n - 1]; }
};



int main(){
    int N;  cin >> N;
    vector<int> a(N);
    for(int i = 0; i < N; i++){
        cin >> a[i];
        a[i]--;
    }

    if(N == 2){
        cout << -1 << endl;
        return 0;
    }

    vector<int> count(N, 0);
    for(int i = 0; i < N; i++){
        count[a[i]]++;
    }
    SegmentTree<int> st(count, [](int u, int v){ return max(u, v); }, 0);

    set<int> candidate;
    for(int i = 0; i < N; i++){
        candidate.insert(i);
    }

    int remain = N;
    vector<int> res;
    auto judge1 = [&](int x){
        int num = st.query(0, N);
        if(num == remain-1 && st[x] != num){
            return false;
        }
        else{
            return true;
        }
    };
    auto judge2 = [&](int x){
        if(remain != 3) return true;
        int nex1 = -1, nex2 = -1;
        for(auto e: candidate){
            if(e == x)  continue;

            if(nex1 == -1)  nex1 = e;
            else nex2 = e;

            if(nex1 != -1 && nex2 != -1){
                break;
            }
        }
        if(a[nex1] == nex2 && a[nex2] == nex1){
            return false;
        }
        else{
            return true;
        }
    };

    int ng = -1;
    while(remain > 0){
        auto itr = candidate.begin();
        int nex = *itr;
        if(remain == 1){
            res.push_back(nex);
            break;
        }

        while(true) {
            if(nex != ng && judge1(nex) && judge2(nex)){
                res.push_back(nex);
                ng = a[nex];
                st.update(a[nex], st[a[nex]] - 1);
                candidate.erase(nex);
                break;
            }
            else{
                itr++;
                nex = *itr;
            }
        }
        remain--;
    }

    for(auto r: res){
        cout << r + 1 << " ";
    }
    cout << endl;

    return 0;
}

