  alive.erase(u);
  forb_cnts.erase(make_pair(fc[forb[u]], forb[u]));
  fc[forb[u]]--;
  if (fc[forb[u]] > 0) {
    forb_cnts.insert(make_pair(fc[forb[u]], forb[u]));
  }
