int special () {
  if ((int) forb_cnts.size() == 2) {
    pair<int, int> fst = *forb_cnts.begin();
    pair<int, int> snd = *forb_cnts.rbegin();

    if (snd.first == 1) {
      if (alive.count(fst.second)) return fst.second;
      else if (fst.first == 1 && alive.count(snd.second)) return snd.second;
    }
  }
  return 0;
}

