#define PQS(T) priority_queue<T, vector<T>, greater<T> >

int N, ng, a[100010], ans[100010];
PQS(int) pq;

void OUT(void){
	rep(index, N) cout << ans[index] << " ";
	cout << "\n";
}

int main(){
	cin >> N;
	rep(i, N){ cin >> a[i+1]; pq.push(i+1); }
	if(N==2){ cout << -1 << endl; return 0; }
	if(N==3){
		vector<int> aa = {1, 2, 3};
		do{
			if(a[aa[0]] != aa[1] && a[aa[1]] != aa[2]){
				cout << aa[0] << " " << aa[1] << " " << aa[2] << "\n";
				return 0;
			}
		}while(next_permutation(aa.begin(), aa.end()));
	}
	rep(i, N-1){
		if(i==0){ ans[i] = 1; pq.pop(); }
		else{
			int t = pq.top(); pq.pop();
			if(t == a[ans[i-1]]){
				ans[i] = pq.top(); pq.pop();
				pq.push(t);
			}else ans[i] = t;
		}
	}
	ans[N-1] = pq.top(); pq.pop();
	if(a[ans[N-2]] != ans[N-1]){ OUT(); return 0; }
	if(a[ans[N-3]] != ans[N-1] && a[ans[N-1]] != ans[N-2]){
		swap(ans[N-2], ans[N-1]); OUT(); return 0;
	}
	for(int i=N-4; i>=0; i--){
		if(i==N-4){
			ng = a[ans[i]];
			for(int j=N-3; j<N; j++){
				if(ans[j] != ng) pq.push(ans[j]);
				if(ans[j] != ng && a[ans[j]] != ng){
					int n1 = ans[N-2]+ans[N-1]-ng;
					int n2 = ans[N-3];
					if(n2 > ng) swap(n2, ng);
					ans[N-3] = n1, ans[N-2] = n2, ans[N-1] = ng;
					if(a[ans[N-3]] != ans[N-2] && a[ans[N-2]] != ans[N-1]){
						OUT(); return 0;
					}
					swap(ans[N-2], ans[N-1]);
					OUT(); return 0;
				}
			}
			pq.push(ans[i]);
		}else{
			if(a[ans[i]] != ng){
				ans[i+1] = ng;
				rep(j, N-i-2){
					int t = pq.top(); pq.pop();
					if(j != 0){ ans[j+i+2] = t; continue; }
					if(a[ans[i+1]] != t) ans[i+2] = t;
					else{
						ans[i+2] = pq.top(); pq.pop();
						pq.push(t);
					}
				}
				OUT();
				return 0; 
			}
			pq.push(ans[i]);
		}
	}
	ans[0] = ng;
	rep(i, N-1){
		int t = pq.top(); pq.pop();
		if(i != 0){ ans[i+1] = t; continue; }
		if(a[ans[i]] != t) ans[i+1] = t;
		else{
			ans[i+1] = pq.top(); pq.pop();
			pq.push(t);
		}
	}
	OUT();
	return 0;
}

