const int  INF = 1 << 29;
const ll INFL = 1LL << 60;
const ll mod = 1000000007;


struct Segment_tree {
	using T = ll;

	int n;
	vector<T> data;
	const T out = (1LL << 31) - 1;

	inline T vmerge(T l, T r) { return min(l, r); }

	Segment_tree(int n) :n(n) { data.assign(2 * n, out); }

	void update(int p, T x) {  // set value at position p
		for (data[p += n] = x; p > 1; p >>= 1) {
			data[p >> 1] = vmerge(data[p], data[p ^ 1]);
		}
	}

	T query(int l, int r) {  // sum on interval [l, r)
		T resl = out, resr = out;
		for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
			if (l & 1) resl = vmerge(data[l++], resl);
			if (r & 1) resr = vmerge(resr, data[--r]);
		}
		return vmerge(resl, resr);
	}
};

int main() {



	int n;
	cin >> n;

	Segment_tree rmq(n);
	REP(i, n) {
		rmq.update(i, i);
	}

	vector<int> v(n);
	REP(i, n) {
		cin >> v[i];
		v[i]--;
	}

	vector<int> ans(n,-1);
	ans[0] = 0;
	rmq.update(0, INF);
	FOR(i, 1, n) {
		int a = rmq.query(0, n);

		if (v[ans[i - 1]] != a) {
			ans[i] = a;
			rmq.update(a, INF);
		}
		else {
			rmq.update(a, INF);
			int b = rmq.query(0, n);
			if (b == INF) {
				cout << -1 << endl;
				return 0;
			}
			ans[i] = b;
			rmq.update(b, INF);
			rmq.update(a, a);
		}
	}

	REP(i, n)cout << ans[i] + 1 << ' ';
	return 0;

}

