int main() {
	int n; scanf("%d", &n); std::vector<int> p(n + 1);
	for(int i = 1; i <= n; i++) scanf("%d", &p[i]);

	if(n == 2) {
		printf("-1\n");
		return 0;
	}

	auto comp = [](std::vector<int> & x, std::vector<int> & y) {
		if(y.size() == 0) return true;
		for(int i = 0; i < x.size(); i++) {
			if(x[i] == y[i]) continue;
			return x[i] < y[i];
		}
		return false;
	};

	std::priority_queue<int, std::vector<int>, std::greater<int>> qu;
	for(int i = 2; i <= n; i++) qu.push(i);

	std::vector<int> ans(1, 1);
	for(int i = 0; i < n - 3; i++) {
		int x = qu.top(); qu.pop();
		int y = qu.top(); qu.pop();

		if(p[ans[i]] != x) {
			ans.push_back(x);
			qu.push(y);
		} else {
			ans.push_back(y);
			qu.push(x);
		}
	}
	int x = ans.back();
	ans.pop_back();
	int y = qu.top(); qu.pop();
	int z = qu.top(); qu.pop();
	std::vector<int> val = {x, y, z}, v;
	for(int i = 0; i < 3; i++) {
		for(int j = 0; j < 3; j++) {
			for(int k = 0; k < 3; k++) {
				if(i == j or j == k or k == i) continue;
				std::vector<int> u = {val[i], val[j], val[k]};

				if((ans.empty() or p[ans.back()] != u[0]) and p[u[0]] != u[1] and p[u[1]] != u[2]) {
					if(comp(u, v)) v = u;
				}
			}
		}
	}
	ans.push_back(v[0]);
	ans.push_back(v[1]);
	ans.push_back(v[2]);

	for(auto v: ans) printf("%d ", v);
	printf("\n");
	return 0;
}

