int const MAXN = 1e5 + 5;
int a[MAXN], ans[MAXN];
int fa[MAXN], val[MAXN], size[MAXN];

int Find(int x) { return !fa[x] ? x : Find(fa[x]); }

void Dfs(int level, int n) {
  if (level == n + 1) {
    for (RI i = 1; i <= n; ++i)
      printf("%d ", ans[i]);
    exit(0);
  }
  int f = Find(0);
  int pos = val[f];
  while (pos != n + 1) {
    if (pos != a[ans[level - 1]]) {
      int fx = Find(pos + 1);
      if (size[fx] > size[f]) {
        fa[f] = fx;
        size[fx] += size[f];
        ans[level] = pos;
        Dfs(level + 1, n);
        size[fx] -= size[f];
        fa[f] = 0;
      }
      else {
        fa[fx] = f;
        size[f] += size[fx];
        int tmp = val[f];
        val[f] = val[fx];
        ans[level] = pos;
        Dfs(level + 1, n);
        size[f] -= size[fx];
        val[f] = tmp;
        fa[fx] = 0;
      }
    }
    f = Find(pos + 1);
    pos = val[f];
  }
  return;
}

