	  }
	  int64 p1 = pq.top(); pq.pop();
	  int64 p2 = pq.top(); pq.pop();
	  int64 use;
	  if (res.size() && a[res.back()] == p1) {
	    res.push_back(p2); used[p2] = 1;
	    pq.push(p1);
	    cnt[in[p2]].erase(p2);
	    use = p2;
	  } else {
