            int i = cur.second;
			b[sz] = i;
			st.erase(pii(cnt[i], i));
			if (!vis[a[i]]) {
				st.erase(pii(cnt[a[i]], a[i]));
				cnt[a[i]] --;
				st.insert(pii(cnt[a[i]], a[i]));
			}
			vis[i] = 1;
			dfs(sz+1, mn);
			vis[i] = 0;
			if (!vis[a[i]]) {
				st.erase(pii(cnt[a[i]], a[i]));
				cnt[a[i]] ++;
				st.insert(pii(cnt[a[i]], a[i]));
			}
			st.insert(pii(cnt[i], i));
        }
        else return;
    }
    else {
        while (vis[mn]) mn ++;
        for (int i = mn; i <= n; i ++) if (!vis[i]) {
            if (sz == 1 || sz > 1 && a[b[sz-1]] != i) {
                b[sz] = i;
                st.erase(pii(cnt[i], i));
