                if (!vis[a[i]]) {
                    st.erase(pii(cnt[a[i]], a[i]));
                    cnt[a[i]] ++;
                    st.insert(pii(cnt[a[i]], a[i]));
                }
				st.insert(pii(cnt[i], i));
            }
        }
    }
    return;
}

