int const maxn = 1e5 + 10;

int N, a[maxn], b[maxn];

int main()
{
  scanf("%d", &N);

  int deg[maxn] = {};
  for(int i = 1; i <= N; i++) {
    scanf("%d", &a[i]);
    deg[a[i]]++;
  }

  bool vis[maxn] = {};
  function<void(int, int)> dfs = [&](int cur, int mn) {
    if(cur == N+1) {
      for(int i = 1; i <= N; i++) printf("%d ", b[i]);
      putchar('\n');
      exit(0);
    }

    if(cur > 1 && !vis[a[b[cur-1]]] && deg[a[b[cur-1]]] == N-cur) return;

