    for(int v = mn; v <= N; v++) {
      if(vis[v] || (cur > 1 && v == a[b[cur-1]])) continue;
      b[cur] = v;
      vis[v] = true;
      deg[a[v]]--;
      dfs(cur+1, v==mn? mn+1 : mn);
      deg[a[v]]++;
      vis[v] = false;
    }
  };

  dfs(1, 1);
  puts("-1");

  return 0;
