int N;
vector<int> p;

bool check(const vector<int> &res) {
    for (int i = 0; i + 1 < res.size(); ++i) {
        if (res[i+1] == p[res[i]]) return false;
    }
    return true;
}

void last(vector<int> &res, vector<int> &rem) {
    do {
        if (rem[0] == p[res.back()]) continue;
        if (check(rem)) {
            for (int i = 0; i < res.size(); ++i) cout << res[i] + 1 << " ";
            for (int i = 0; i < rem.size(); ++i) cout << rem[i] + 1 << " ";
            cout << endl;
            return;
        }
    } while (next_permutation(rem.begin(), rem.end()));

    cout << -1 << endl;
    return;
}

void solve() {
    if (N <= 9) {
        vector<int> res(N);
        for (int i = 0; i < N; ++i) res[i] = i;
        do {
            if (check(res)) {
                for (int i = 0; i < res.size(); ++i) cout << res[i]+1 << " ";
                cout << endl;
                return;
            }
        } while (next_permutation(res.begin(), res.end()));

        cout << -1 << endl;
        return;
    }

    map<int, set<int>> inv;
    for (int i = 0; i < N; ++i) {
        inv[p[i]].insert(i);
    }

    vector<int> res;
    set<int> se;
    for (int i = 0; i < N; ++i) se.insert(i);

    if (inv.size() <= 2) res.push_back(inv.begin()->first);
    else res.push_back(0);

    {
        se.erase(res.back());
        int from = res.back();
        int to = p[from];
        if (inv.count(to) && inv[to].count(from)) {
            inv[to].erase(from);
            if (inv[to].empty()) inv.erase(to);
        }
    }

    while (N - (int)res.size() > 9) {
        if (inv.size() <= 2) {
            res.push_back(inv.begin()->first);
        }
        else {
            int dame = p[res.back()];
            int i = -1;
            for (auto it : se) {
                if (it != dame) {
                    i = it;
                    break;
                }
            }
            res.push_back(i);
        }

        {
            se.erase(res.back());
            int from = res.back();
            int to = p[from];
            if (inv.count(to) && inv[to].count(from)) {
                inv[to].erase(from);
                if (inv[to].empty()) inv.erase(to);
            }
        }
    }
    vector<int> rem;
    for (auto it : se) rem.push_back(it);
    last(res, rem);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    while (cin >> N) {
        p.resize(N);
        for (int i = 0; i < N; ++i) cin >> p[i], --p[i];
        solve();
    }
}

