typedef long long ll;
using P = pair<int, int>;
int main() {
  int n;
  cin >> n;
  vector<int> in(n);
  vector<int> la(n);
  priority_queue<P> pq;
  for (int i = 0; i < n; ++i) {
    int a; cin >> a; --a;
    la[i] = a;
    in[a] += 1;
  }
  for (int i = 0; i < n; ++i) {
    pq.push({in[i], i});
  }
  vector<int> ans;
  vector<int> d(n);
  vector<bool> used(n);
  for (int i = 0; i < n; ++i) {
    if (used[i]) continue;
    int rem = n-ans.size();
    P t = pq.top();
    while (used[t.second]) {
      pq.pop();
      if (pq.empty()) {
        cout << -1 << endl;
        return 0;

      }
      t = pq.top();
    }
    while (d[t.second] > 0) { 
      pq.pop();
      pq.push({t.first-d[t.second], t.second});
      d[t.second] = 0;
    }
    if (t.first == rem-1) { 
      ans.push_back(t.second);
      pq.pop();
      d[la[t.second]] += 1;
      used[t.second] = true;
    }
    int off = 1;
    int n2 = ans.size();
    while (ans.size() > 0 && la[ans[n2-1]] == i) {
      if (used[i+off]) {
        ++off;
        continue;
      }
      ans.push_back(i+off);
      d[la[i+off]] += 1;
      used[i+off] = true;
      if (i+off >= n) {
        cout << -1 << endl;
        return 0;
      }
      n2 += 1;
      ++off;
    }
    ans.push_back(i);
    d[la[i]] += 1;
    used[i] = true;
  }
  if (ans.size() < n) {
    cout << -1 << endl;
  }
  for (int i = 0; i < n; ++i) {
    cout << ans[i]+1;
    if (i < n-1) cout << " ";
  }
  cout << endl;
}

