int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    int n;
    cin >> n;
    vector<int> a(n + 1);
    set<int> unused;
    map<int, int> cnt;
    set<pair<int, int>> xyi;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        cnt[a[i]]++;
        unused.insert(i);
    }

    for (auto p : cnt) {
        xyi.insert({ p.second, p.first });
    }

    vector<int> ans(1);
    for (int i = 1; i <= n; i++) {
        for (int x : unused) {
            xyi.erase({ cnt[a[x]], a[x] });
            cnt[a[x]]--;
            xyi.insert({ cnt[a[x]], a[x] });
            if (a[ans.back()] == x) {
                xyi.erase({ cnt[a[x]], a[x] });
                cnt[a[x]]++;
                xyi.insert({ cnt[a[x]], a[x] });
                continue;
            }
            if (n - i > 2 && xyi.rbegin()->first == n - i - 1 && unused.count(xyi.rbegin()->second) && a[x] == xyi.rbegin()->second) {
                xyi.erase({ cnt[a[x]], a[x] });
                cnt[a[x]]++;
                xyi.insert({ cnt[a[x]], a[x] });
                continue;
            }
            if (n - i == 2 && xyi.rbegin()->first == 1 && unused.count(xyi.rbegin()->second) && unused.count((++xyi.rbegin())->second) &&
               xyi.rbegin()->second != x && (++xyi.rbegin())->second != x) {
                xyi.erase({ cnt[a[x]], a[x] });
                cnt[a[x]]++;
                xyi.insert({ cnt[a[x]], a[x] });
                continue;
            }
            unused.erase(x);
            ans.push_back(x);
            break;
        }
        if (ans.size() == i) {
            cout << "-1\n";
            return 0;
        }
    }

    for (int i = 1; i <= n; i++) {
        cout << ans[i] << " \n"[i == n];
    }
    return 0;
}

