    if (n == 2) {
        cout << -1 << endl;
        return;
    }

    deque<ll> vals;
    srep (val, 1, n+1) vals.push_back(val);

    V<ll> anslist; anslist.pb(0);

    S bool used[100005] = {};

    S ll ngcnts[100005] = {};
    srep (v, 1, n+1) ngcnts[ngs[v]]++;

    S set<t2> m_ngsets;
    srep (v, 1, n+1) m_ngsets.insert(t2(-ngcnts[v], v));

    ll discard = -1;

    while (vals.size() > 3) {
        auto m_ng = *m_ngsets.begin();
        ll ngcnt = -get<0>(m_ng);
        ll ngv = get<1>(m_ng);

        if (discard < 0 && ngcnt >= vals.size() - 1LL && !used[ngv]) {
            anslist.pb(ngv);
            used[ngv] = true;
            m_ngsets.erase(t2(-ngcnts[ngs[ngv]], ngs[ngv]));
            ngcnts[ngs[ngv]]--;
            m_ngsets.insert(t2(-ngcnts[ngs[ngv]], ngs[ngv]));
            discard = ngv;
            queue<ll> tmpq;
            while (vals.size()) {
                ll tmpv = vals.front(); vals.pop_front();
                if (tmpv == ngv) continue;
                tmpq.push(tmpv);
            }
            while (tmpq.size()) {
                ll tmpv = tmpq.front(); tmpq.pop();
                vals.push_back(tmpv);
            }
            continue;
        }

        V<ll> vs;
        while (vs.size() < 2) {
            ll lval = vals.front(); vals.pop_front();
            vs.pb(lval);
        }

        ngv = ngs[*(anslist.end()-1)];
        ll uv, dv;
        if (vs[0] != ngv) {
            uv = vs[0];
            dv = vs[1];
        }
        else {
            uv = vs[1];
            dv = vs[0];
        }

        vals.push_front(dv);
        anslist.pb(uv);
        used[uv] = true;
        m_ngsets.erase(t2(-ngcnts[ngs[uv]], ngs[uv]));
        ngcnts[ngs[uv]]--;
        m_ngsets.insert(t2(-ngcnts[ngs[uv]], ngs[uv]));

    }

