        auto mx = seg.query(0, n);
        if (mx.first >= n - i - 1 && ng == mx.first) {
            cout << -1 << "\n";
            return 0;
        }
        int j = 10000000000;
        if (mx.first >= n - i - 1) {
            j = mx.second;
        } else if (mx.first == n - i - 2) {
            for (auto &u : unused) {
                if (ng != u && a[u] != mx.second) {
                    j = u;
                    break;
                }
                if (ng != mx.second)
                    j = min(j, mx.second);
            }
        } else {
            auto it = unused.begin();
            if (*it == ng)
                it = next(it);
            j = *it;
        }
        ret.push_back(j);
        unused.erase(j);
        ng = a[j];
        seg.update(j, {-1, j});
        int k  = a[j];
        auto u = seg.query(k, k + 1);
        seg.update(u.second, {u.first - 1, u.second});
    }
    vector<int> rest;
    for (auto &u : unused) {
        rest.push_back(u);
    }
    do {
        bool ok = true;
        int ngg = ng;
        for (int i = 0; i < (int)rest.size(); ++i) {
            if (ngg == rest[i])
                ok = false;
            ngg = a[rest[i]];
        }
        if (ok) {
            for (auto &r : rest) {
                ret.push_back(r);
            }
            break;
        }
    } while (next_permutation(rest.begin(), rest.end()));
    if ((int)ret.size() != n) {
        cout << -1 << "\n";
        return 0;
    }
    for (int i = 0; i < n; ++i) {
        if (i)
            cout << " ";
        cout << ret[i] + 1;
    }
    cout << "\n";
    return 0;
}

