	priority_queue<int, vector<int>, greater<int>> que;
	for (int i = 1; i <= n; i++) que.push(i);
	vector<int> ans;
	int cnt = 0;
	while (cnt < n - 9) {
		int p = que.top(); que.pop();
		if (cnt > 0 && a[ans[cnt - 1]] - 1 == p) {
			int q = que.top(); que.pop();
			ans.push_back(q);
			que.push(p);
		}
		else {
			ans.push_back(p);
		}
		cnt++;
	}
	vector<int> x;
	for (int i = 0; i < min(9, n); i++) {
		int p = que.top(); que.pop();
		x.push_back(p);
	}
