		if (n > 9) {
			if (a[ans[n - 10] - 1] == x[0]) flag = false;
		}
		for (int i = 1; i < x.size(); i++) {
			if (a[x[i - 1] - 1] == x[i]) flag = false;
		}
		if (flag) {
			for (int i = 0; i < x.size(); i++) {
				ans.push_back(x[i]);
			}
			break;
