bool solve(int idx, set<int> &s, int ng) {
  // REP(i,idx) printf("%d%c", b[i], i!=idx-1?' ':'\n');
  if (s.size() == 0) {
    return 1;
  }
  set<int>::iterator it = s.begin();
  while (it != s.end()) {
    if (*it == ng) {
