	V<int> b(n);
	std::iota(ALL(b), 0);

	V<int> pos(n, -1);
	REP(i, n) pos[b[i]] = i;

	auto swap = [&](int i, int j) {
		std::swap(pos[b[i]], pos[b[j]]);
		std::swap(b[i], b[j]);
	};

	auto check = [&](int p) {
		if (p < 0) return true;
		if (p + 1 >= n) return true;
		int i = b[p];
		return b[p + 1] != a[i];
	};

	REP(i, n) {
		int p = pos[i];
		if (!check(i)) {
			int k = b[p + 1] + 1;
			while (k < n && (p + 1 >= pos[k] || a[k] == b[p + 1])) ++k;
			if (k >= n) {
				while (p >= 0) {
					swap(p, p + 1);
					if (check(p - 1) && check(p)) break;
					--p;
				}
				if (p < 0) {
					OUT(-1)BR;
					return 0;
				}
			}
			else {
				int q = pos[k];
				while (p + 1 < q) {
					--q;
					swap(q, q + 1);
				}
			}
		}
	}

	REP(i, n) {
		OUT(b[i] + 1)SPBR(i, n);
	}

	return 0;
}

