void dfs(int k, int sz) {
    b[sz] = k;
    vis[k] = 1;
    if (sz == n) {
        for (int i = 1; i <= n; i ++) printf("%d%c", b[i], " \n"[i==n]);
        exit(0);
    }
    for (int t = 1; t <= n; t ++) if (!vis[t] && t != a[k]) {
        vis[t] = 1;
        dfs(t, sz+1);
        vis[t] = 0;
    }
    return;
}

