void dfs (int num) {
	if (num >= n - 9) {
		rem.resize(0);
		int last = ans[num - 1];
		while (!q.empty()) {
			rem.push_back(q.top());
			q.pop();
		}
		do {
			bool check = true;
			check &= (ban[last] != rem[0]);
			for (int i = 1; i < rem.size(); i ++)
				check &= (ban[rem[i - 1]] != rem[i]);
			if (check) {
				// for (int i = 1; i <= n; i ++)
					// cout << ban[i] << " ";
				// cout << " : ";
