					cout << rem[i] << " ";
				cout << endl;

				return ;
			}
		} while (next_permutation (rem.begin(), rem.end()));
		if (num == n - 9) {
			// cerr << "in charge " << endl;
			for (int i = 0; i < rem.size(); i ++)
				if (rem[i] != ban[ans[num - 1]])
					q.push(rem[i]);
			int beg = num - 1;
			while (beg >= 0 && ban[ans[beg]] == ban[ans[num - 1]]) {
				q.push(ans[beg]);
				beg --;
			}
			// cerr << "beg = " << beg << endl;
			ans[beg + 1] = ban[ans[num - 1]];
			dfs (beg + 2);
		}
		cout << -1 << endl;
		return ;
	}
	if (num == 0) {
		ans[num] = 1;
		q.pop();
		dfs (num + 1);
		return ;
	}
	int c = q.top();
	if (ban[ans[num - 1]] != c) {
		ans[num] = c;
		q.pop();
		dfs (num + 1);
	}
	else {
		q.pop();
		int c2 = q.top();
		ans[num] = c2;
		q.pop();
		q.push(c);
		dfs (num + 1);
	}
}


