RMaxQ ema;
vector<int> ans;

signed main(){
    cin >> N;
    if(N == 2){
        cout << -1 << endl;
        return 0;
    }
    rep(i, N){
        cin >> a[i];
        a[i]--;
    }

    rmq.init(N);
    rep(i, N) rmq.update(i, i);
    ema.init(N, 0);
    rep(i, N) ema.add(a[i], 1);
    int ng = -1;
    rep(i, N){
        int idx = rmq.find(0, N);
        if(ng == idx){
            idx = rmq.find(idx+1, N);
        }
        if(ema.max(0, N) == N-1-i){
            idx = ema.find(0, N);
        }
        ans.pb(idx);
        rmq.update(idx, INT_MAX);
        ema.add(a[idx], -1);
        ng = a[idx];
    }

    rep(i, N){
        if(i != 0) cout << " ";
        cout << ans[i]+1;
    }
    cout << endl;
}

