template<class G>
class Fenwick_tree{
	vector<G> a;
public:
	Fenwick_tree(int n):a(n){}
	void add(int i,G val){
		for(i++;i<=a.size();i+=i&-i) a[i-1]+=val;
	}
	G sum(int l,int r)const{
		if(l==0){
			G res{};
			for(;r>0;r-=r&-r) res+=a[r-1];
			return res;
		}
		return sum(0,r)-sum(0,l);
	}
	int lower_bound(G val)const{
		if(val<=G{}) return 0;
		int x=0,k;
		for(k=1;k<=a.size();k<<=1);
		for(k>>=1;k>0;k>>=1) if(x+k<=a.size() && a[x+k-1]<val) val-=a[x+k-1], x+=k;
		return x;
	}
	int upper_bound(G val)const{
		if(val<G{}) return 0;
		int x=0,k;
		for(k=1;k<=a.size();k<<=1);
		for(k>>=1;k>0;k>>=1) if(x+k<=a.size() && a[x+k-1]<=val) val-=a[x+k-1], x+=k;
		return x;
	}
};

int n,bad[100000];

vector<pair<int,int>> V;

Fenwick_tree<int> F(0);
int ans[100000];

bool dfs(int i){
	if(i==n) return true;
//printf("i  = %d\n",i);

	int next=-1;
	for(auto p:V){
		int deg=p.first,x=p.second;
		if(deg==n-1 && F.sum(x,x+1)==1){
			if(next!=-1) return false;
			next=x;
		}
	}
	if(next!=-1){
//printf("next = %d\n",next);
		int x=next;
		if(i==0 || bad[ans[i-1]]!=x){
			F.add(x,-1);
			ans[i]=x;
			for(auto& p:V) if(bad[x]!=p.second) p.first++;
			if(dfs(i+1)) return true;
			for(auto& p:V) if(bad[x]!=p.second) p.first--;
			F.add(x, 1);
		}
		return false;
	}

	for(int p=1;;p++){
		int x=F.lower_bound(p);
		if(x==n) break;
		if(i==0 || bad[ans[i-1]]!=x){
			F.add(x,-1);
			ans[i]=x;
			for(auto& p:V) if(bad[x]!=p.second) p.first++;
			if(dfs(i+1)) return true;
			for(auto& p:V) if(bad[x]!=p.second) p.first--;
			F.add(x, 1);
		}
	}
	return false;
}

