vector<int> bruteforce(int n, int *a) {
    vector<int> ans(n);
    iota(ans.begin(), ans.end(), 0);
    function <bool()> check = [&]() {
        for (int i = 1; i < n; i++) {
            if (a[ans[i-1]] == ans[i]) return false;
        }
        return true;
    };
    do {
        if (check()) return ans;
    } while (next_permutation(ans.begin(), ans.end()));
    return {};
}

