    auto f=[](pii a, pii b) {return max(a,b);};
    const pii id = pii(0,-1);
    SegmentTree seg(f,id);
    seg.init(N+1);
    rep(i,N+1) seg.set(i,pii(0,i));
    seg.build();
    for (int i = 1; i <= N; i++) seg.update(A[i],pii(seg[A[i]].first+1,A[i]));
    vector<int> ans(N+1);
    iota(all(ans),0);
    for (int i = 1; i <= N; i++) {
        if (N+1-i <= 5) {
            do {
                bool ok = true;
                for (int j = i-1; j < N; j++) {
                    if (A[ans[j]]==ans[j+1]) ok = false;
                }
                if (ok) {
                    for (int j = 1; j <= N; j++) {
                        cout << ans[j] << " ";
                    }
                    cout << ln;
                    return 0;
                }
            } while (next_permutation(ans.begin()+i,ans.end()));
            cout << -1 << ln;
            return 0;
        }
        if (seg.get(0,N+1).first==N-i) {
            int t = seg.get(0,N+1).second;
            for (int j = i; j <= N; j++) {
                if (ans[j]==t) {
                    for (int k = j-1; k >= i; k--) {
                        swap(ans[k],ans[k+1]);
                    }
                    break;
                }
            }
            seg.update(t,pii(seg[t].first-1,t));
            continue;
        } 
        if (A[ans[i-1]]==ans[i]) swap(ans[i],ans[i+1]);
        seg.update(ans[i],pii(seg[ans[i]].first-1,ans[i]));
    }
}

