#include <bits/stdc++.h>

using namespace std;

constexpr int N = 100000;

struct Event {
	int idx, hated;

	bool operator < (const Event &e) const {
		if (this->hated == e.hated) {
			return this->idx > e.idx;
		}

		return this->hated < e.hated;
	}
};

priority_queue<Event> pq;
int indegree[N + 1];
int ans[N + 1];
int a[N + 1];
set<int> s;

bool valid(const Event &e) {
	return s.count(e.idx) and e.hated == indegree[e.idx];
}

int main() {
	int n, i;

	scanf("%d", &n);

	for (i = 1; i <= n; i++) {
		scanf("%d", a + i);
		indegree[a[i]]++;
	}

	if (n == 2) {
		printf("-1\n");
		return 0;
	}

	for (i = 1; i <= n; i++) {
		pq.push({i, indegree[i]});
		s.insert(i);
	}

	if (pq.top().hated == n - 1) { // Everyone hates.
		ans[1] = pq.top().idx;
	}
	else {
		ans[1] = 1;
	}

	// Only updates s, but not indegree.
	s.erase(ans[1]);

	for (i = 2; i <= n; i++) {
		while (!valid(pq.top())) {
			pq.pop();
		}

		if (pq.top().hated > n - i) {
			break;
		}

		if (pq.top().hated == n - i) { // Too much hate, needs to be next.
			if (pq.top().idx == a[ans[i - 1]]) { // Actually it is hated by previous, so lets get the smallest one.
				if (*s.begin() == a[ans[i - 1]]) { // Smallest one is actually hated by previous, getting next.
					ans[i] = *next(s.begin());
				}
				else { // Smallest one.
					ans[i] = *s.begin();
				}
			}
			else { // Not hated by previous, for sure needs to be next.
				ans[i] = pq.top().idx;
			}
		}
		else { // Lets get the smallest one.
			if (*s.begin() == a[ans[i - 1]]) { // Smallest one is actually hated by previous, getting next.
				ans[i] = *next(s.begin());
			}
			else {
				ans[i] = *s.begin();
			}
		}

		// Updating s, indegree and pq.
		s.erase(ans[i]);
		indegree[a[ans[i - 1]]]--;
		pq.push({a[ans[i - 1]], indegree[a[ans[i - 1]]]});
	}

	if (i <= n) {
		printf("-1\n");
		return 0;
	}

	for (i = 1; i <= n; i++) {
		printf("%d ", ans[i]);
	}

	printf("\n");

	return 0;
}

