void solve3(vector<LL>& ans, vector<LL>& a, vector<LL>& tri){
    for(LL i = 0; i < 3; ++i){
        for(LL j = 0; j < 3; ++j){
            for(LL k = 0; k < 3; ++k){
                if(i == j || j == k || k == i) continue;
                if(ans.size() > 0 && a[ans[ans.size()-1]] == tri[i]) continue;
                if(a[tri[i]] != tri[j] && a[tri[j]] != tri[k]){
                    ans.push_back(tri[i]);
                    ans.push_back(tri[j]);
                    ans.push_back(tri[k]);
                    return;
                }
            }
        }
    }
}


