        --a[i];
        indegree[a[i]] += 1;
    }
    if(n <= 2){
        cout << -1 << endl;
        return 0;
    }

    set<pair<LL,LL>> ordered;
    set<LL> rest;
    for(LL i = 0; i < n; ++i){
        rest.insert(i);
        ordered.insert(pair<LL,LL>(indegree[i], i));
    }
