    for(LL i = 0; i+3 < n; ++i){
        while(!ordered.empty()){
            LL val = ordered.rbegin()->first;
            LL key = ordered.rbegin()->second;
            if(used[key]){
                ordered.erase(--ordered.end());
                continue;
            }
            if(val != indegree[key]){
                ordered.erase(--ordered.end());
                ordered.insert(pair<LL,LL>(indegree[key], key));
                continue;
            }
            break;
        }
        if(!ordered.empty()){
            LL val = ordered.rbegin()->first;
            LL key = ordered.rbegin()->second;
            if(val == n-1-i){
                ans.push_back(val);
                used[key] = 1;
                indegree[a[key]] -= 1;
                rest.erase(key);
                continue;
            }
        }
        for(LL cur: rest){
            if(i > 0 && a[ans[ans.size()-1]] == cur){
                continue;
            }
            ans.push_back(cur);
            used[cur] = 1;
            indegree[a[cur]] -= 1;
            rest.erase(cur);
            break;
        }
    }
    assert(rest.size() == 3);
    vector<LL> tri(rest.begin(), rest.end());
    solve3(ans, a, tri);
    for(LL i = 0; i < n; ++i){
        cout << ans[i]+1 << ((i+1==n)?"\n":" ");
    }
    return 0;
}

