void output(const V<ll> &anslist, const V<ll> &alist, ll n)
{
    set<ll> ansset;
    for (auto ans : anslist) ansset.insert(ans);
    assert(ansset.size() == n);

    ll prev = 0;
    rep (i, n) {
        assert(alist[prev] != anslist[i]);
        cout << anslist[i] << ((i == n-1) ? "" : " ");
        prev = anslist[i];
    }
