int main() {
  int n;
  cin >> n;
  vector<int> forbid(n), deg(n);
  for (int i = 0; i < n; ++i) {
    int j;
    cin >> j; --j;
    deg[j]++;
    forbid[i] = j;
  }
  vector<int> ret(n);
  set<int> A;
  for (int i = 0; i < n; ++i) A.insert(i);
  function<bool(int, int)> search =
    [&](int pre, int pos) -> bool {
      if (pos == n) return true;
      if (pre != -1 && A.count(forbid[pre]) && deg[forbid[pre]] == n - 1 - pos) return false;
      for (auto it = A.begin(); it != A.end(); ) {
        int k = *it;
        if (pre != -1 && forbid[pre] == k) {
          ++it;
          continue;
        }
        ret[pos] = k;
        A.erase(k);
        int nk = forbid[k];
        --deg[nk];
        if (search(k, pos + 1)) return true;
        ++deg[nk];
        A.insert(k);
        it = A.upper_bound(k);
      }
      return false;
    };
  bool found = search(-1, 0);
  if (found) {
    for (int i = 0; i < n; ++i) {
      cout << ret[i] + 1 << " \n"[i + 1 == n];
    }
  } else {
    cout << -1 << '\n';
