            //cout << (*rs.lower_bound(P(cnt[s],s))).first << " " << (*rs.lower_bound(P(cnt[s],s))).second << endl;
            rs.erase(rs.lower_bound(P(cnt[s],s)));
            //cout << "a" << endl;
            se.erase(id2);
            //cout << "b" << endl;
            ban=a[s];
            if(se.find(a[s])!=se.end()){
                rs.erase(rs.lower_bound(P(cnt[a[s]],a[s])));
                rs.insert(P(cnt[a[s]]-1,a[s]));
                cnt[a[s]]-=1;
            }
        }
        //cout << ans.back() << endl;
