        // cout << " " << endl;
        // for(P p:rs){
        //     cout << p.first << " " << p.second << endl;
        // }
        // cout << "" << endl;
    }
    ans.push_back(*se.begin());
    rep(i,n){
        cout << ans[i]+1 << " ";
    }
    cout << ""  << endl;
}

