bool ok(int i, int pos) {
	if (N - i == 3) {
		vector<int> ps;
		for (int p : st) {
			if (p == pos) continue;
			ps.push_back(p);
		}

		if (a[ps[0]] == ps[1] && a[ps[1]] == ps[0]) return false;
	}
	return con[pos] != i;
}

