template<typename Monoid>
struct SegmentTree {
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1) {
        sz = 1;
        while(sz < n) sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x) {
        seg[k + sz] = x;
    }

    void build() {
        for(int k = sz - 1; k > 0; k--) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    void update(int k, const Monoid &x) {
        k += sz;
        seg[k] = x;
        while(k >>= 1) {
            seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
        }
    }

    Monoid query(int a, int b) {
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
            if(a & 1) L = f(L, seg[a++]);
            if(b & 1) R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const {
        return seg[k + sz];
    }
};

int main()
{
    int n;
    cin >> n;
    if(n == 2){
        cout << -1 << endl;
        return 0;
    }
    int a[100002];
    int l[100002]{0};
    for(int i = 0; i < n; i++){
        cin >> a[i];
        a[i]--;
        l[a[i]]++;
    }
    SegmentTree<int> seg(n, [](int a, int b){return max(a, b);}, 0);
    for(int i = 0; i < n; i++) seg.set(i, l[i]);
    seg.build();
    int b[100002];
    bool used[100002]{0};
    int k = 0;
    for(int i = 0; i < n; i++){
        if(used[i]) continue;
        if(k == n - 1){
            b[k] = i;
            break;
        }
        if(seg.query(0, n) == n - k - 1){
            for(int j = 0; j < n; j++){
                if(seg[j] == n - k - 1){
                    b[k] = j;
                    k++;
                    used[j] = true;
                    seg.update(j, 0);
                    seg.update(a[j], seg[a[j]] - 1);
                    break;
                }
            }
            i--;
            continue;
        }
        if(k == 0){
            b[k] = 0;
            used[0] = true;
            seg.update(0, 0);
            seg.update(a[0], seg[a[0]] - 1);
        }
        else if(a[b[k - 1]] == i){
            for(int j = i + 1; j < n; j++) if(!used[j]){
                b[k] = j;
                used[j] = true;
                seg.update(j, 0);
                seg.update(a[j], seg[a[j]] - 1);
                i--;
                break;
            }
        }
        else{
            b[k] = i;
            used[i] = true;
            seg.update(i, 0);
            seg.update(a[i], seg[a[i]] - 1);
        }
        k++;
    }
    for(int i = 0; i < n; i++) cout << b[i] + 1 << " ";
    cout << endl;
}

