int N;
vector<int> as;
int cnt[114514];
set<int> ls[114514];

signed main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);
  cin >> N;
  rep(i, N) {
    int a;
    cin >> a;
    --a;
    as.eb(a);
    cnt[a]++;
  }

  if (N == 2) {
    cout << "-1\n";
    return 0;
  }

  set<int> cand;
  rep(i, N) {
    cand.insert(i);
    ls[cnt[i]].insert(i);
  }

  vector<int> ans;
  auto Del = [&](int idx) {
    ans.eb(idx);
    cand.erase(idx);
    assert(ls[cnt[idx]].count(idx));
    ls[cnt[idx]].erase(idx);
    int a = as[idx];
    if (cand.count(a)) {
      assert(ls[cnt[a]].count(a));
      ls[cnt[a]].erase(a);
      cnt[a]--;
      assert(cnt[a] >= 0);
      ls[cnt[a]].insert(a);
    }
  };

  rep(i, N) {
    assert(cand.size()+i == N);
    int rem = N-1-i;
    if (!ls[rem].empty()) {
      int idx = *ls[rem].begin();
      Del(idx);
      continue;
    }

    int idx = *cand.begin();
    if (!ans.empty() && as[ans.back()] == idx) {
      assert(cand.size() > 1);
      auto itr = cand.begin();
      ++itr;
      idx = *itr;
    }
    Del(idx);
  }
  assert(cand.empty() && ans.size() == N);

  if (as[ans[N-2]] == ans[N-1]) {
    assert (N > 3);
    swap(as[N-3], as[N-2]);
  }

  rep(i, N) {
    if (i) cout << " ";
    cout << ans[i]+1;
  }cout << endl;
}

