int main(void){
    int n;
    cin >> n;
    map<int, int> dis;
    priority_queue<int, vector<int>, greater<int>> waitQ;
    rep1(i,n) {
        cin >> dis[i];
        waitQ.push(i);
    }
    if (n == 2) {
        cout << -1 << endl;
        return 0;
    }
    vector<int> res = {0};
    rep(i,n-3){
        int t1 = waitQ.top(); waitQ.pop();
        int t2 = waitQ.top(); waitQ.pop();
        if (dis[res.back()] != t1) {
            res.push_back(t1);
            waitQ.push(t2);
        } else {
            res.push_back(t2);
            waitQ.push(t1);
        }
    }
    vector<int> v;
    while(waitQ.size()) {
        v.push_back(waitQ.top());
        waitQ.pop();
    }
    bool ok;
    do {
        ok = true;
        rep(i,3) res.push_back(v[i]);
        rep(i,3) {
            if (dis[res[n-3+i]] == res[n-2+i]) {
                ok = false;
            }
        }
        if (ok) break;
        rep(i,3) res.pop_back();
    } while(next_permutation(all(v)));
    if (!ok) {
        cout << -1 << endl;
        return 1;
    }

    rep1(i,n){
        cout << (res[i]) << (i < n ? " " : "\n");
    }
    return 0;
}

