set<int> S;

bool check(vector <int> &v){
  REP(i, n - 1)
    if(a[ v[i] ] == v[i + 1])
      return false;
  return true;
}

void permutiraj(vector <int> &v){
  vector <int> tmp;
  FOR(i, n - 3, n)
    tmp.pb(v[i]);

  REP(i, 3)
    v.pop_back();

  vector <int> ret;
  do{
    REP(i, 3)
      v.pb(tmp[i]);

    if(check(v)){
      if(ret.empty())
        ret = v;
      else
        ret = min(ret, v);
    }

    REP(i, 3)
      v.pop_back();

  } while(next_permutation(tmp.begin(), tmp.end()));
  v = ret;
}

