        if (A[c] == a) ans[N - 2] = b, ans[N - 1] = a;
        else ans[N - 2] = a, ans[N - 1] = b;
    } else if (A[b] == c && A[c] == b) {
        ans[N - 2] = a;
        if (A[a] == b) ans[N - 3] = b, ans[N - 1] = c;
        else ans[N - 3] = c, ans[N - 1] = b;
    } else {
        ans[N - 3] = a;
        if (A[a] == b) ans[N - 2] = c, ans[N - 1] = b;
        else ans[N - 2] = b, ans[N - 1] = c;
    }

    cout << ans[0];
    for (int i = 1; i < N; i++) cout << " " << ans[i];
    cout << endl;


    return (0);
}

