/*
最後の 2 つが、循環参照をしていたらアウトです。
また、全員に参照されているものがあったら、それはすぐに使わないと最後まで使えなくて詰みます。

各人の参照カウントを管理して、頂点数 - 1 のものがあったら使うをします。
これは、初期状態が 2 点循環参照だったとき以外は絶対に選べます。
また、そうでないときには最小のものを、それが無理なら次を選びます。

参照カウントは、添字をキーにした vector と、値だけの multiset で管理します。
頂点を消したら、それが参照していたものの参照カウントを 1 減らし、自分を 0 にします。
*/

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
  ios::sync_with_stdio(0); cin.tie(0);
  int n;
  cin >> n;
  vector<int> a(n);
  vector<int> indeg(n);
  for (int&ai : a) {
    cin >> ai;
    ai--;
    indeg[ai]++;
  }

  set<int> left;
  set<pair<int,int>> deg;
  for (int i = 0; i < n; i++) {
    left.insert(i);
    deg.insert({indeg[i], i});
  }
  vector<int> ans;
  for (int i = 0; i < n; i++) {
    if (deg.rbegin()->first == n-1-i) {
      ans.push_back(deg.rbegin()->second);
      deg.erase(*deg.rbegin());
      if (deg.size() && deg.rbegin()->first == n-1-i) {
	cout << -1 << endl;
	return 0;
      }
    } else {
      auto it = left.begin();
      if (ans.size() && *it == a[ans.back()]) ++it;
      ans.push_back(*it);
    }
    {
      int p = ans.back();
      left.erase(p);
      deg.erase({indeg[p],p});
      if (left.count(a[p])) {
	deg.erase({indeg[a[p]],a[p]});
	deg.insert({--indeg[a[p]],a[p]});
      }
    }
  }
  for (int i : ans) cout << i+1 << ' ';
  cout << endl;
}

