				if (go(a + 1))
					return 1;
				hv.insert(ans[a]);
				return 0;
			}
	}
	ans[a] = *hv.begin();
	if (a == 0 || x[ans[a - 1]] != ans[a]) {
		hv.erase(hv.begin());
		if (go(a + 1))
			return 1;
		hv.insert(ans[a]);
