                int c,j; tie(c,j)=*out.rbegin();
                if(c+1+i==n)
                {
                    b[i]=j;
                }
                else
                {
                    auto itr=rem.begin();
                    if(i and a[b[i-1]]==*itr)
                    {
                        ++itr;
                    }
                    b[i]=*itr;
                }
            }

            out.erase(pii(cnt[a[b[i]]],a[b[i]]));
            cnt[a[b[i]]]--;
            out.emplace(pii(cnt[a[b[i]]],a[b[i]]));

            out.erase(pii(cnt[b[i]],b[i]));
            rem.erase(b[i]);
        }

        assert(rem.size()==2);

        int i1=*rem.begin();
        int i2=*next(rem.begin());
        assert(i1<i2);
        if(a[i1]!=i2)
        {
            if(b.empty())
            {
                b[n-2]=i1;
                b[n-1]=i2;
            }
            else
            {
                if(a[b[n-3]]!=i1)
                {
                    b[n-2]=i1;
                    b[n-1]=i2;
                }
                else
                {
                    b[n-2]=i2;
                    b[n-1]=i1;
                }
            }
        }
        else // a[i1]==i2
        {
            if(a[i2]!=i1)
            {
                b[n-2]=i2;
                b[n-1]=i1;
            }
            else
            {
                if(n==2)
                {
                    cout << -1 << "\n";
                    return;
                }
                int ins=i1;
                if(n>3 and a[b[n-4]]==i1)
                {
                    ins=i2;
                }
                b[n-2]=b[n-3];
                b[n-3]=ins;
                b[n-1]=i1^i2^ins;
            }
        }

        for(int &i : b)
        {
            i++;
        }
        cout << b << "\n";
    }
}; // struct solver


