    for (int i = 1;i < n;++i) {
        if (m.first == n-i-1 && a[ans[i-1] != m.second]) {
            st.erase(m.second);
            ans[i] = m.second;
            seg.update(m.second,P(-1000,m.second));
            int d = seg.getmax(a[m.second],a[m.second]+1).first-1;
            if (d == 0) d = -1000;
            seg.update(a[m.second],P(d,a[m.second]));
            m = seg.getmax(0,n);
        } else {
            auto it = st.begin();
            if (a[ans[i-1]] == *it) ++it;
            int c = *it;
            ans[i] = c;
            st.erase(c);
            seg.update(c,P(-1000,c));
            int d = seg.getmax(a[c],a[c]+1).first-1;
            if (d == 0) d = -1000;
            seg.update(a[c],P(d,a[c]));
            m = seg.getmax(0,n);
        }
    }
    for (int i = 0;i < n;++i) cout << ans[i]+1 << " \n"[i == n-1];
}

