int find_min(set<int>& s) {
    assert(!s.empty());

    vi l;
    if (by_size.begin()->fst >= s.size() - 1) {
        l.push_back(*(by_size.begin()->snd.begin()));
    } else {
        auto it = s.begin();
        l.push_back(*it);
        it++;
        if (it != s.end()) l.push_back(*it);
    }

    for (int v : l) {
        bool ok = ans.empty() || a[ans.back()] != v;

        if (s.size() == 3) {
            int x = -1, y = -1;
            for (int u : s) {
                if (u == v) continue;
                if (x >= 0)
                    y = u;
                else
                    x = u;
            }

            ok &= a[x] != y || a[y] != x;
        }

        if (ok) {
            return v;
        }
    }
    return -1;
}

bool rec(set<int>& s) {
    if (s.empty()) return true;

    int u = find_min(s);
    //cout << "u=" << u << endl;
    if (u < 0)
        return false;
    else {
        s.erase(u);
        erase(u);
        if (contains(s, a[u])) {
            erase(a[u]);
            in[a[u]].erase(u);
            insert(a[u]);
        }
        ans.push_back(u);

        return rec(s);
    }
}

