void decrease(vector<int>& count, int i, set<pair<int,int>>& count_nums) {
	count[i] -= 1;
	if(count_nums.erase({count[i] + 1, i}) == 1) {
		count_nums.insert({count[i], i});
	}
}

void remove_from_pq(priority_queue<int>& pq, int x) {
	priority_queue<int> tmp;
	while(!pq.empty()) {
		int v = pq.top();
		pq.pop();
		if(v != x) {
			tmp.push(v);
		}
	}
	swap(tmp, pq);
}

