	for(int i = 0; i < n + 1; i++) {
		count_nums.insert({count[i], i});
	}

	int last = n;
	priority_queue<int> rem;
	for(int i = 0; i < n + 1; i++) {
		rem.push(-i);
	}

	vector<int> ans;

	while(rem.size() > 5) {

		dbg(last);

