			int v = most->second;
			ans.push_back(v);
			last = v;
			remove_from_pq(rem, -v);
			continue;
		}

		array<int,3> vs;
		for(int i = 0; i < 3; i++) {
			vs[i] = -rem.top();
			rem.pop();
		}

		int used = 0;
		while(used < 3 && (vs[used] == x || vs[used] == last)) {
			used += 1;
		}
		assert(used < 3);

		for(int i = 0; i < 3; i++) {
			if(i != used) {
				rem.push(-vs[i]);
			}
		}

		int v = vs[used];
		ans.push_back(v);
		last = v;
	}

	vector<int> right(rem.size());
	const int rlen = right.size();

	for(int i = 0; i < rlen; i++) {
		right[i] = -rem.top();
		rem.pop();
