        if (i && p[b[i - 1]] == b[i]) {
            b[i] = *next(st.begin());
        }
        st.erase(b[i]);
    }
    for (int i = n - 4; i < n; i++) {
        b[i] = *st.begin();
        st.erase(b[i]);
    }
    do {
