template<int SZ> struct Counter {
	int Count[SZ];
	set<int> Kinds;
	Counter() { rep(i, 0, SZ) Count[i] = 0; }

	void Increment(int i) {
		if (Count[i] == 0) Kinds.insert(i);
		Count[i]++;
	}

	void Decrement(int i) {
		Count[i]--;
		if (Count[i] == 0) Kinds.erase(i);
	}
};
