[[noreturn]] void impossible() {
    PRINTLN(-1);
    exit(0);
}

void solve() {
    i64 N = RD();
    auto A = RD1_VEC(N);

    set<i64> s;
    REP(i, N) {
        s.emplace(i);
    }

    auto ans = vec_reserve<i64>(N);
    ans.emplace_back(*begin(s));
    s.erase(begin(s));
    REP(_, N-1) {
        auto it = begin(s);
        if(A[ans.back()] != *it) {
            ans.emplace_back(*it);
            s.erase(it);
        }
        else {
            ++it;
            if(it == end(s)) impossible();
            ans.emplace_back(*it);
            s.erase(it);
        }
    }

    for(i64& e : ans) ++e;  // 1-based
    PRINTLN(ans);
}

