int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    vector<int> ng(N);
    // (x, j) -> jはx個のngをもつ
    set<P, greater<P>> ngs;
    set<int> cards;
    for(int i = 0; i < N; i++) {
        int a;
        cin >> a;
        a--;
        A[i] = a;
        ng[a]++;
        cards.insert(i);
