    int l = -1;
    for(int n = 0; n < N; n++) {
        P p = *ngs.begin();
        int j;
        if(p.first == N - 1 - n) { // 先端にしないといけないやつ
            j = p.second;
        } else { // 先端を辞書順最小で決める
            for(int i : cards) {
                if(l < 0 || A[l] != i) {
                    j = i;
