        fre.erase(it);
    }

    vi rest(ALL(fre));

    vi sol = naive(a, rest, fr);
    if (sol.empty()) {
//        assert(n == 2);
        cout << "-1";
        return;
    }
    p.insert(p.end(), ALL(sol));
    for (auto x : p) {
        cout << x << ' ';
    }

}

