using namespace std;

vector<int> solve(int n, const vector<int> & a) {
    if (n == 2) return vector<int>();

    vector<int> freq(n);
    for (int a_i : a) {
        ++ freq[a_i];
    }
    segment_tree<max_monoid<int> > segtree(n);
    REP (i, n) {
        segtree.unsafe_point_set(i, freq[i]);
    }
    segtree.unsafe_rebuild();

    vector<int> b;
    set<int> available;
    vector<int> cur;
    REP (i, n) {
        available.insert(i);
    }
    ([go = [&](auto go) {
        if (available.empty()) {
            b = cur;
            return;
        }
        auto use = [&](int i) {
            if (not cur.empty() and a[cur.back()] == i) return;
            available.erase(i);
            cur.push_back(i);
            segtree.point_set(i, segtree.point_get(i) - n);
            segtree.point_set(a[i], segtree.point_get(a[i]) - 1);
// cerr << "push " << i << endl;
            go(go);
// if (b.empty()) cerr << "pop " << i << endl;
            segtree.point_set(i, segtree.point_get(i) + n);
            segtree.point_set(a[i], segtree.point_get(a[i]) + 1);
            cur.pop_back();
            available.insert(i);
        };
        if (segtree.range_get(0, n) == (int)available.size() - 1) {
            for (auto it = available.begin(); it != available.end(); ++ it) {
                int i = *it;
                if (segtree.range_get(0, n) == segtree.point_get(i)) {
                    use(i);
                }
                it = available.find(i);
            }
            return;
        }
        for (auto it = available.begin(); it != available.end(); ++ it) {
            int i = *it;
            use(i);
            it = available.find(i);
            if (not b.empty()) break;
        }
    }]() { return go(go); })();
    assert (not b.empty());
    return b;
}

