				if (i > 0 && ban[res[i-1]] == *it) ++it;
				j = *it;
				act.erase(it);
			} else {
				act.erase(act.find(j));
			}
			++ins[ban[j]].first;
			rm.set(ins[ban[j]].second, ins[ban[j]]);
			rm.set(j, {n, -1});
