bool check(set <int> &s, int x) {
    int y, z;

    if (s.size() != 3) return true;

    s.erase(x);
    y = *s.begin();
    z = *s.rbegin();
    s.insert(x);

    if (a[y] == z && a[z] == y) return false;

    return true;
}

int main() {
    int n, i;
    vector <int> v;
    set <int> s;
    set <pair<int, int>> s2;
    set <int>::iterator it;

    scanf("%d", &n);

    if (n == 2) {
        puts("-1");

        return 0;
    }

    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);

        a[i]--;
        b[a[i]]++;
    }

    for (i = 0; i < n; i++) s.insert(i);
    for (i = 0; i < n; i++) s2.insert(make_pair(b[i], i));

    for (i = 0; i < n; i++) {
        int x;

        if (s2.size() > 0 && s2.rbegin()->first == n - i - 1) {
            x = s2.rbegin()->second;
        } else {
            for (it = s.begin(); it != s.end(); it++) {
                if (i > 0 && a[v.back()] == *it) continue;
                if (!check(s, *it)) continue;
                x = *it;
                break;
            }

            if (it == s.end()) {
                puts("-1");

                return 0;
            }
        }

        v.push_back(x);
        s.erase(x);
        s2.erase(make_pair(b[x], x));
        s2.erase(make_pair(b[a[x]], a[x]));
        b[a[x]]--;
        if (b[a[x]] > 0 && s.count(a[x])) s2.insert(make_pair(b[a[x]], a[x]));
    }

    for (i = 0; i < n; i++) {
        if (i > 0) putchar(' ');
        printf("%d", v[i] + 1);
    }
    puts("");

    return 0;
}

