const int maxn = 1e5 + 5;



int n;
int a[maxn];
int ans[maxn];
int used[maxn];
int indeg[maxn];

void dfs(int idx, int lo) {
    if (idx == n) {
	for (int i=0; i<n; i++) {
	    cout<<ans[i]+1<<" ";
	}
	cout<<endl;
	exit(0);
    }

    // Prune: a[ans[idx-1]] can't go after anyone
    if (idx>0 && !used[a[ans[idx-1]]] && indeg[a[ans[idx-1]]] == n-idx-1) {
	return;
    }
    while (used[lo]) lo++;
    for (int x=lo; x<n; x++) {
	if (used[x]) continue;
	if (idx>0 && a[ans[idx-1]]==x) continue;
	int _lo = x==lo ? lo+1 : lo;
	used[x]=1;
	ans[idx]=x;
	indeg[a[x]]--;
	dfs(idx+1, _lo);
	indeg[a[x]]++;
	ans[idx]=0;
	used[x]=0;
    }
}

