void sch(int n, int now, const vi &a, vi &ans, set<int> &st) {
  if(n == now) {
    return;
  }
  if(n - now <= 10) {
    vi v;
    for(auto &e: st) v.push_back(e);
    REP(i, SZ(v)) {
      if(SZ(ans) != 0 && a[ans.back()] == v[i]) continue;
      ans.push_back(v[i]);
      st.erase(v[i]);
      sch(n, now+1, a, ans, st);
      if(SZ(ans) == n) return;
      st.insert(v[i]);
      ans.pop_back();
    }
  } else {
    int nxt = -1;
    for(auto &e: st) {
      if(SZ(ans) == 0 || a[ans.back()] != e) {
        nxt = e;
        break;
      }
    }
    if (nxt != -1) {
      ans.push_back(nxt);
      st.erase(nxt);
      sch(n, now+1, a, ans, st);
    }
  }
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(10);

  int n; cin >> n;
  vi a(n);
  REP(i, n) {
    cin >> a[i];
    a[i]--;
  }

  set<int> st;
  REP(i, n) {
    st.insert(i);
  }

  vi ans;
  sch(n, 0, a, ans, st);
  if(SZ(ans) != n) {
    cout << -1 << endl;
  } else {
    REP(i, n) {
      cout << ans[i] + 1;
      if(i == n-1) cout << endl;
      else cout << " ";
    }
  }

}

