const ll MOD = 1000000007;

set<int> S;
int A[100010], B[100010], N;

int dfs(int x) {
	if (x == N)return -1;
	int y = *S.begin(), j;
	if (y == A[B[x]]) {
		S.erase(S.begin());
		if (S.empty()) {
			S.insert(y);
			return y;
		}
		B[x + 1] = *S.begin();
		S.erase(S.begin());
		S.insert(y);
	}
	else {
		S.erase(S.begin());
		B[x + 1] = y;
	}
	j = dfs(x + 1);
	if (j < 0)return -1;

	S.insert(B[x + 1]);
	if (j == A[B[x]]) {
		return j;
	}
	else {
		S.erase(j);
		B[x + 1] = j;
		dfs(x + 1);
		return -1;
	}

}

