void smain() {

//    stress();

    int n;
    cin >> n;
    vi a(n);
    vi deg(n + 1, 0);
    fori (i, n) {
        cin >> a[i];
        deg[a[i]]++;
    }

    set<int> fre;
    for (int i = 1; i <= n; ++i) {
        fre.insert(i);
    }
    vi p;
    int fr = -1;
    set<pii> degver;
    for (int i = 1; i <= n; ++i) {
        degver.insert({deg[i], i});
    }
    for (int i = 0; n - i > 3; ++i) {
        auto it = fre.begin();
        if (*it == fr)
            ++it;

        int x = *it;

        if ((*degver.rbegin()).first == n - i - 1) {
            x = (*degver.rbegin()).second;
        }
//        assert(fr != x);
        p.push_back(x);
        degver.erase({deg[x], x});
        if (fre.count(a[x])) {
            degver.erase({deg[a[x]], a[x]});
            deg[a[x]]--;
            degver.insert({deg[a[x]], a[x]});
        }

        fr = a[x - 1];
        fre.erase(x);
    }

    vi rest(ALL(fre));

    vi sol = naive(a, rest, fr);
    if (sol.empty()) {
//        assert(n == 2);
        cout << "-1";
        return;
    }
    p.insert(p.end(), ALL(sol));
    for (auto x : p) {
        cout << x << ' ';
    }

}

