int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    std::cin >> n;
    a.resize(n);
    deg.resize(n);
    ans.resize(n);
    used.resize(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
        --a[i];
        ++deg[i];
    }
    for (int i = 0; i < n; ++i)
        s.insert(i);
    for (int i = 0; i < n; ++i)
        d.emplace(-deg[i], i);
    int lim = -1;
    for (int i = 0; i < n; ++i) {
        int u;
        if (-d.begin() -> first == n - i - 1) {
            if (d.begin() -> second == lim) {
                std::cout << -1 << "\n";
                return 0;
            }
            u = d.begin() -> second;
        } else if (*s.begin() != lim) {
            u = *s.begin();
        } else if (int(s.size()) == 1) {
            std::cout << -1 << "\n";
            return 0;
        } else {
            u = *std::next(s.begin());
        }
        s.erase(u);
        d.erase({-deg[u], u});
        used[u] = true;
