void last(vector<int> &res, vector<bool> &used) {
    vector<int> rem;
    for (int i = 0; i < N; ++i) if (!used[i]) rem.push_back(i);
    do {
        if (rem[0] == p[res.back()]) continue;
        if (check(rem)) {
            for (int i = 0; i < res.size(); ++i) cout << res[i] + 1 << " ";
            for (int i = 0; i < rem.size(); ++i) cout << rem[i] + 1 << " ";
            cout << endl;
            return;
        }
    } while (next_permutation(rem.begin(), rem.end()));

    cout << -1 << endl;
    return;
}

