set<int> rest;
vector<int> buf;
int cnt = 0;
ll has[101010];
ll ha = 0;
set<ll> ng;
void dfs(int cu) {
	if (ng.count(ha)) return;

	if (cu == N - 1) {
		if (A[buf.back()] == *rest.begin()) return;

		rep(i, 0, N - 1) {
			if (i) printf(" ");
			printf("%d", buf[i] + 1);
		}
		printf(" %d\n", *rest.begin() + 1);
		exit(0);
	}

	int pre = -1;
	int n = rest.size();
	rep(i, 0, n) {
		int nxt = *rest.upper_bound(pre);
		pre = nxt;

		//printf("?%d %d\n", cu, nxt);

		if (0 < cu and A[buf.back()] == nxt) continue;

		//printf("%d %d\n", cu, nxt);

		rest.erase(nxt);
		buf.push_back(nxt);
		ha ^= has[nxt];
		dfs(cu + 1);
		ha ^= has[nxt];
		buf.pop_back();
		rest.insert(nxt);

		cnt++;
		assert(cnt < 2010101);
	}

	ng.insert(ha);
}
