            ans[i]=cur;
            pre=cur;
        }
        vi remain;
        for(auto u:av) remain.push_back(u);
        vi last={n,n,n};
        do
        {
            int cc=pre;
            bool ok=1;
            for(int i=0;i<3;i++)
            {
                if(remain[i]==a[cc])
                {
                    ok=0;
                    break;
                }
                cc=remain[i];
            }
            if(ok)
                last=min(last,remain);
        } while (next_permutation(remain.begin(),remain.end()));
        assert(last!=vi({n,n,n}));
        for(int i=0;i<3;i++) ans[i+n-2]=last[i];
        for(int i=1;i<=n;i++) cout<<ans[i]<<(i==n?'\n':' ');
    }
}

