vector<bool> used;
vector<int> indeg;
vector<int> ans;

bool dfs(int ng);

bool f(int i) {
    used[i] = true;
    indeg[a[i]]--;
    bool z = dfs(a[i]);
    used[i] = false;
    indeg[a[i]]++;
    return z;
}

bool dfs(int ng) {
    if (pq.empty()) return true;
    int N = pq.size();
    if (ng != -1 && !used[ng] && indeg[ng] == N - 1) return false;
    if (pq.size() >= 1) {
        int i = pq.top(); pq.pop();
        if (i != ng && f(i)) {
            ans.pb(i);
            return true;
        }
        pq.push(i);
    }
    if (pq.size() >= 2) {
        int i = pq.top(); pq.pop();
        int j = pq.top(); pq.pop();
        pq.push(i);
        if (j != ng && f(j)) {
            ans.pb(j);
            return true;
        }
        pq.push(j);
    }
    if (pq.size() >= 3) {
        int i = pq.top(); pq.pop();
        int j = pq.top(); pq.pop();
        int k = pq.top(); pq.pop();
        pq.push(i); pq.push(j);
        if (k != ng && f(k)) {
            ans.pb(k);
            return true;
        }
        pq.push(k);
    }
    return false;
}

