int main(){
    using namespace std;
    unsigned long N;
    cin >> N;

    if(N <= 7){
        vector<unsigned long> a(N + 1);
        copy_n(istream_iterator<unsigned long>(cin), N, a.begin() + 1);
        vector<unsigned long> nxt(N + 2), prv(N + 2);
        iota(nxt.begin(), nxt.end(), 1UL);
        iota(prv.begin() + 1, prv.end(), 0UL);
        vector<unsigned long> ans;
        auto ts = chrono::system_clock::now();
        [dfs = [&N, &a, &nxt, &prv, &ans, &ts](auto f, unsigned long b, unsigned long t) -> void {
            if(ans.size() == N){
                for(const auto& i : ans)cout << i << " ";
                cout << endl;
                exit(0);
            }
            if(chrono::duration_cast<chrono::milliseconds>(ts - chrono::system_clock::now()).count() >= 1500){
                puts("-1");
                exit(0);
            }
            auto x{nxt[0]};
            while(x <= N){
                if(x != t){
                    auto n{nxt[x]}, p{prv[x]};
                    nxt[prv[x]] = n;
                    prv[nxt[x]] = p;
                    ans.push_back(x);
                    f(f, x, a[x]);
                    ans.pop_back();
                    nxt[x] = n;
                    prv[x] = p;
                    nxt[prv[x]] = x;
                    prv[nxt[x]] = x;
                }
                x = nxt[x];
            }
        }, &N]{for(unsigned long i{1}; i <= N; ++i)dfs(dfs, i, 0);}();
        puts("-1");
        return 0;
    }

    vector<unsigned long> a(N + 1);
    copy_n(istream_iterator<unsigned long>(cin), N, a.begin() + 1);
    vector<unsigned long> cnt(N + 1);
    set<unsigned long> unused_unchecked, check;
    for(unsigned long i{1}; i <= N; ++i)unused_unchecked.insert(i);
    for(const auto& i : a)if(++cnt[i] == N){
        unused_unchecked.erase(i);
        check.insert(i);
    }
    vector<unsigned long> ans;
    unsigned long taboo{0};
    const auto& add = [&N, &a, &cnt, &unused_unchecked, &check, &ans, &taboo](unsigned long i){
        ans.push_back(i);
        taboo = a[i];
        if(++cnt[a[i]] == N){
            unused_unchecked.erase(a[i]);
            check.insert(i);
        }
    };
    for(unsigned long i{0}; i < N; ++i){
        if(check.empty()){
            auto it = unused_unchecked.begin();
            if(*it == taboo)++it;
            auto t = *it;
            unused_unchecked.erase(it);
            add(t);
        }else{
            auto it = check.begin();
            if(*it == taboo)++it;
            auto t = *it;
            check.erase(it);
            add(t);
        }
    }
    for(const auto& i : ans)cout << i << " ";cout << endl;
    return 0;
}

