int n;
int ban[100010];

priority_queue <int, vector <int>, greater<int> > q;
int ans[100010];


vector <int> rem;

void dfs (int num) {
	if (num >= n - 9) {
		rem.resize(0);
		int last = ans[num - 1];
		while (!q.empty()) {
			rem.push_back(q.top());
			q.pop();
		}
		do {
			bool check = true;
			check &= (ban[last] != rem[0]);
			for (int i = 1; i < rem.size(); i ++)
				check &= (ban[rem[i - 1]] != rem[i]);
			if (check) {
				for (int i = 1; i <= n; i ++)
					cout << ban[i] << " ";
				cout << " : ";
				for (int i = 0; i < num; i ++)
					cout << ans[i] << " ";
				for (int i = 0; i < rem.size(); i ++)
					cout << rem[i] << " ";
				cout << endl;

				return ;
			}
		} while (next_permutation (rem.begin(), rem.end()));
		if (num == n - 9) {
			for (int i = 1; i < rem.size(); i ++)
				if (rem[i] != ban[ans[num - 1]])
					q.push(rem[i]);
			int beg = num - 1;
			while (beg >= 0 && ban[ans[beg]] == ban[ans[num - 1]]) {
				q.push(ans[beg]);
				beg --;
			}
			ans[beg] = ban[ans[num - 1]];
			dfs (beg + 1);
		}
		return ;
	}
	if (num == 0) {
		ans[num] = 1;
		q.pop();
		dfs (num + 1);
		return ;
	}
	int c = q.top();
	if (ban[ans[num - 1]] != c) {
		ans[num] = c;
		q.pop();
		dfs (num + 1);
	}
	else {
		q.pop();
		int c2 = q.top();
		ans[num] = c2;
		q.pop();
		q.push(c);
		dfs (num + 1);
	}
}


