  for(int i=0;i<n;i++)cin>>v[i];
  if(n==2)fin(-1);
  map<int,int> m;
  for(int i=0;i<n;i++)m[v[i]]++;
  vector<int> ans;
  set<int> s;
  for(int i=1;i<=n;i++)s.insert(i);
  while(ans.size()<n){
    int p=*s.begin();
    if(ans.size()==n-1){
      if(p==v[ans[ans.size()-1]-1]){assert(false);fin(-1);}
      ans.push_back(p);break;
    }
    int t=v[p-1];
    int ho=-1;
    if(ans.size())if(v[ans[ans.size()-1]-1]==p){
      ho=p;s.erase(p);s.insert(INF);
      p=*s.begin();
      t=v[p-1];
    }
    if(s.count(t)&&m[t]+1==s.size()){
      s.erase(p);
      int q=*s.begin();
      ans.push_back(q);
      s.erase(q);
      if(--m[v[q]]==0)m.erase(v[q]);
      s.insert(p);
    }
    else{
      ans.push_back(p);
      s.erase(p);
      if(--m[t]==0)m.erase(t);
    }
    if(~ho){
      s.erase(INF);s.insert(ho);
    }
  }
  for(int p:ans)cout<<p<<" ";cout<<endl;
}

