		cin >> p[i];
		p[i]--;
		cnt[p[i]]++;
	}
	vector<set<int>> st(n + 1);
	rep(i, n) st[cnt[i]].insert(i);
	vector<int> ans;
	priority_queue<int, vector<int>, greater<int>> que;
	rep(i, n) que.push(i);
	int x = -1;
	int sz = n;
	while (sz > 3) {
		if (sz > 1 && st[sz].size() && x == -1) {
			if (st[sz].size() > 1) {
				cout << "-1\n";
				return 0;
			}
			int k = *st[sz].begin();
			ans.pb(k);
			st[cnt[k]].erase(k);
			cnt[k]--;
			st[cnt[p[k]]].erase(p[k]);
			cnt[p[k]]--;
			st[cnt[p[k]]].insert(p[k]);
			x = k;
		}
		else {
			int k = que.top(); que.pop();
			if (x == k) {
				k = que.top(); que.pop();
			}
			if (ans.size() == 0 || p[ans.back()] != k) {
