				cnt[k]--;
				st[cnt[p[k]]].erase(p[k]);
				cnt[p[k]]--;
				st[cnt[p[k]]].insert(p[k]);
			}
			else {
				int nk = que.top(); que.pop();
				if (x == nk) {
					nk = que.top(); que.pop();
				}
				ans.pb(nk);
				st[cnt[nk]].erase(nk);
				cnt[nk]--;
				st[cnt[p[nk]]].erase(p[nk]);
