vector <int> rem;

void dfs (int num) {
	if (num >= n - 8) {
		for (int i = 0; i < num; i ++)
			cout << ans[i] << " ";
		int last = ans[num - 1];
		while (!q.empty()) {
			rem.push_back(q.top());
			q.pop();
		}
		do {
			bool check = true;
			check &= (ban[last] != rem[0]);
			for (int i = 1; i < rem.size(); i ++)
				check &= (ban[rem[i - 1]] != rem[i]);
			if (check) {
				for (int i = 0; i < rem.size(); i ++)
					cout << rem[i] << " ";
				cout << endl;
				exit(0);
			}
		} while (next_permutation (rem.begin(), rem.end()));
		cout << -1 << endl;
		exit(0);
	}
	if (num == 0) {
		ans[num] = 1;
		q.pop();
		dfs (num + 1);
		return ;
	}
	int c = q.top();
	if (ban[ans[num - 1]] != c) {
		ans[num] = c;
		q.pop();
		dfs (num + 1);
	}
	else {
		q.pop();
		int c2 = q.top();
		ans[num] = c2;
		q.pop();
		q.push(c);
		dfs (num + 1);
	}
}


