class Solution {
public:
	void solve() {
		int n;
		cin >> n;
		vector<int> a(n, 0);
		for(int i=0; i<n; i++)cin >> a[i];
		if(n == 2){
			cout << -1 << endl;
			return;
		}
		vector<int> cnt(n+1, 0);
		for(int i=0; i < n; i++)cnt[a[i]]++;
		set<pair<int, int>> ci;
		for(int i=1; i <=n; i++)if(cnt[i] != 0)ci.insert({-cnt[i], i});
		vector<int> b(n, 0);
		set<int> av;
		for(int i=0; i < n; i++)av.insert(i+1);
		int ng = -1;
		for(int i=0; i < n; i++){
			b[i] = *av.begin();
			if(b[i] == ng)b[i] = *next(av.begin());
			if(!ci.empty() && -ci.begin()->first == n-1-i)b[i] = ci.begin()->second;
			ci.erase({-cnt[b[i]], b[i]});
			av.erase(b[i]);
			ng = a[b[i]-1];
		}
		for(int i=0; i<n; i++)cout << b[i] << " ";
		cout << "\n";

		return;
	};
};

