const int N=100005;
int n,a[N],ans[N],vis[N];
pii t[N*4];
set<int> S;
void build(int k,int l,int r){
	if (l==r){
		t[k]=pii(0,l);
		return;
	}
	int mid=(l+r)/2;
	build(k*2,l,mid);
	build(k*2+1,mid+1,r);
	t[k]=max(t[k*2],t[k*2+1]);
}
void change(int k,int l,int r,int p,int v){
	if (l==r){
		t[k].fi+=v;
		return;
	}
	int mid=(l+r)/2;
	if (p<=mid) change(k*2,l,mid,p,v);
	else change(k*2+1,mid+1,r,p,v);
	t[k]=max(t[k*2],t[k*2+1]);
}
void erase(int x){
	change(1,1,n,a[x],-1);
	change(1,1,n,x,-(1<<30));
}
void insert(int x){
	change(1,1,n,a[x],1);
	change(1,1,n,x,(1<<30));
}
bool ava(int ban,int l){
	if (!l) return 1;
	int id=t[1].se;
	//printf("%d %d\n",ans[1],t[1].se);
	if (t[1].fi<l-1) return 1;
	if (id==ban){
		int p=id;
		change(1,1,n,p,-1);
		id=t[1].se;
		change(1,1,n,p,1);
		if (!vis[id]) return 0;
	}
	if (a[a[id]]==id&&l==2) return 0;
	return 1;
}
