int const maxn = 1e5 + 10;

int N, a[maxn], b[maxn];

int main()
{
  scanf("%d", &N);

  int deg[maxn] = {};
  for(int i = 1; i <= N; i++) {
    scanf("%d", &a[i]);
    deg[a[i]]++;
  }

  bool vis[maxn] = {};
  function<void(int, int)> dfs = [&](int cur, int mn) {
    if(cur == N+1) {
      for(int i = 1; i <= N; i++) printf("%d ", b[i]);
      putchar('\n');
      exit(0);
    }

    if(cur > 0 && !vis[a[b[cur-1]]] && deg[a[b[cur-1]]] == N-cur+1) return;

    while(vis[mn]) mn++;

    for(int v = mn; v <= N; v++) {
      if(vis[v] || (cur > 0 && v == a[b[cur-1]])) continue;
      b[cur] = v;
      vis[v] = true;
      deg[a[v]]--;
      dfs(cur+1, v==mn? mn+1 : mn);
      deg[a[v]]++;
      vis[v] = false;
    }
  };

  dfs(1, 1);
  puts("-1");

  return 0;
}

