    SegmentTree<dat> s(n+1, [](dat a, dat b){return max(a, b);}, {-1, -1e9});
    for (int i = 1; i <= n; i++) {
        s.set(i, {p[i], -i});
    }
    s.build();
    vector<int> v;
    int curr = 1;
    for (int i = 0; i < n; i++) {
        while (u[curr]) curr++;
        auto maxi = s.query(0, n+1);
        //cout << maxi.first << " " << maxi.second << "\n";
        int x = curr;
        if (i && a[v[i-1]] == x) {
            x++;
            while (u[x]) x++;
        }
        if (maxi.first >= (n-i-1)) x = -maxi.second;
        v.emplace_back(x);
        u[x] = true;
        auto y = a[x];
        auto z = s[y];
        s.update(x, {-1, -1e9});
        if (!u[y]) s.update(y, {z.first-1, z.second});        
    }
    for (int i = 0; i < n; i++) {
        if (i) cout << " ";
        cout << v[i];
    }
    cout << "\n";
    return 0;
}

