                for (int i = 0; i < 3; i++) {
                    b[n - 3 + i] = x[p[i]];
                }
                break;
            }
        } while (next_permutation(p.begin(), p.end()));
        for (int i : b) {
            cout << i + 1 << " ";
        }
        cout << endl;
        return 0;
    }
    for (int i = n - 2; i >= pos; i--) b[i + 1] = b[i];
    b[pos] = c;
    if (a[c] == b[pos + 1]) swap(b[pos + 1], b[pos + 2]);
    for (int i : b) {
        cout << i + 1 << " ";
    }
    cout << endl;
    return 0;
}

