      for(int i=0;i<kaka;i++){
        w[i]=*s.begin();s.erase(w[i]);
      }
      //cout<<"?";for(int i=0;i<3;i++)cout<<w[i]<<" ";cout<<endl;
      do{
        //cout<<"??";for(int i=0;i<3;i++)cout<<w[i]<<" ";cout<<endl;
        bool f=true;
        int T=-1;
        if(ans.size()>0)T=v[ans[ans.size()-1]-1];
        for(int i=0;i<kaka;i++){
          if(i==0){
            if(T==w[0])f=false;
          }
          else{
            if(v[w[i-1]-1]==w[i])f=false;
          }
        }
        if(f){
          for(int i=0;i<kaka;i++)ans.push_back(w[i]);
          break;
        }
      }while(next_permutation(w.begin(),w.end()));
      break;
    }
    int p=*s.begin();
    /*if(ans.size()==n-1){
      if(p==v[ans[ans.size()-1]-1])fin(-1);
      ans.push_back(p);break;
    }*/
    int t=v[p-1];
    int ho=-1;
    if(ans.size())if(v[ans[ans.size()-1]-1]==p){
      ho=p;s.erase(p);s.insert(INF);
      p=*s.begin();
      t=v[p-1];
    }
    if(s.count(t)&&m[t]+1==s.size()){
      s.erase(p);
      int q=*s.begin();
      ans.push_back(q);
      s.erase(q);
      if(--m[v[q]]==0)m.erase(v[q]);
      s.insert(p);
    }
    else{
      ans.push_back(p);
      s.erase(p);
      if(--m[t]==0)m.erase(t);
    }
    if(~ho){
      s.erase(INF);s.insert(ho);
    }
  }
  if(ans.size()<n)fin(-1);
  for(int p:ans)cout<<p<<" ";cout<<endl;
}

