    cout << "-1\n";
    return 0;
  }

  set<int> cand;
  rep(i, N) {
    cand.insert(i);
    ls[cnt[i]].insert(i);
  }

  auto Del = [&](int idx) {
    cand.erase(idx);
    assert(ls[cnt[idx]].count(idx));
    ls[cnt[idx]].erase(idx);
    int a = as[idx];
    if (ls[cnt[a]].count(a)) {
      ls[cnt[a]].erase(a);
      cnt[a]--;
      ls[cnt[a]].insert(a);
    }
  };

  vector<int> ans;
  rep(i, N) {
    int rem = N-1-i;
    if (!ls[rem].empty()) {
      assert(ls[rem].size() == 1);
      int idx = *ls[rem].begin();
      ans.eb(idx);
      Del(idx);
      continue;
    }

    int idx = *cand.begin();
    if (!ans.empty() && as[ans.back()] == idx) {
      assert(cand.size() > 1);
      auto itr = cand.begin();
      ++itr;
      idx = *itr;
    }
    ans.eb(idx);
    Del(idx);
  }
  assert(cand.empty() && ans.size() == N);
