template <class T>
void erase_one(std::multiset<T>& s, const T& v)
{
	s.erase(s.lower_bound(v));
}

std::vector<int> calc(const std::vector<int>& a)
{
	auto N = a.size();
	std::vector<int> from(N, 0), ans;
	for (const auto& t : a) from[t]++;
	std::set<int> set;
	for (int i = 0; i < N; ++i) set.insert(i);
	auto fix = [&ans, &set](int x) {
		if (set.find(x) == set.end()) throw 0;
		ans.push_back(x);
		set.erase(x);
	};
	auto next = [&set](int ng = -1) {
		for (const auto& x : set)
			if (x != ng) return x;
		return -1;
	};
	std::multiset<int> list;
	for (const auto& x : from) list.insert(x);
	for (int i = 0; i + 1 < N; ++i)
	{
		// std::cout << "i = " << i << ", set = " << set << ", ans = " << ans << std::endl;
		// std::cout << "from = " << from << ", list = " << list << std::endl;
		if (*list.rbegin() == N - i - 1)
		{
			int j = 0;
			for (const auto& k : set)
				if (from[k] == N - i - 1) j = k;
			fix(j);
			while (!set.empty()) fix(*set.begin());
			if (i + 1 < N && a[ans[i]] == ans[i + 1]) std::swap(ans[i + 1], ans[i + 2]);
			break;
		}
		auto x = next(i == 0 ? -1 : a[ans[i - 1]]);
		if (set.size() == 3)
		{
			std::set<int> t(set);
			t.erase(x);
			auto it = t.begin();
			auto y = *it;
			if (set.find(y) != set.end() && *(++it) == a[y] && y != a[y] && a[a[y]] == y)
			{
				if (i > 0) t.erase(a[ans[i - 1]]);
				x = y;
			}
		}
		fix(x);
		if (set.find(a[x]) != set.end())
		{
			erase_one(list, from[a[x]]);
			list.insert(--from[a[x]]);
		}
		erase_one(list, from[x]);
	}
	if (!set.empty()) fix(*set.begin());
	for (auto& x : ans) ++x;
	return ans;
}

void solve()
{
	auto N = read<int>()();
