    priority_queue<int, vector<int>, greater<int>> pq;
    for (int i = 1; i <= N; i++)
        pq.push(i);

    int pre = 0, ans_idx = 0;
    while ((int)pq.size() > 3) {
        int tp = pq.top();
        pq.pop();
        //printf("pre = %d tp = %d\n", pre, tp);
        if (a[pre] == tp) {
            pre = pq.top();
            pq.pop();
            ans[ans_idx++] = pre;
            pq.push(tp);
            continue;
        }
        ans[ans_idx++] = tp;
        pre = tp;
    }
    for (int i = 0; i < 3; i++) {
        rem[i] = pq.top();
        pq.pop();
    }
    if (a[rem[1]] == rem[2] && a[rem[2]] == rem[1]) {
        if (a[rem[0]] == rem[2]) {
            ans[ans_idx++] = rem[2];
            ans[ans_idx++] = rem[0];
            ans[ans_idx++] = rem[1];
        } else {
            ans[ans_idx++] = rem[1];
            ans[ans_idx++] = rem[0];
            ans[ans_idx++] = rem[2];
