#define maxn 100005
#define mp make_pair
int n,a[maxn],ban,in[maxn];
struct Heap_int{
  priority_queue < int,vector<int>,greater<int> > que,lazy;
  void push(int x){ que.push(x); }
  void pop(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    que.pop();
  }
  void erase(int x){ lazy.push(x); }
  int top(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    return que.top();
  }
  int top2(){
    int tmp = top(); pop();
    int ret = top(); push(tmp);
    return ret;
  }
  int size(){ return que.size() - lazy.size(); }
};
struct Heap_P{
  priority_queue <P> que,lazy;
  void push(P x){ que.push(x); }
  void pop(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    que.pop();
  }
  void erase(P x){ lazy.push(x); }
  P top(){
    while(lazy.size() && que.top() == lazy.top()) que.pop(), lazy.pop();
    return que.top();
  }
  int size(){ return que.size() - lazy.size(); }
};
Heap_int hp;
Heap_P deg;
bool vis[maxn];
int fin_nxt(int r){ // there are r nodes left.
  P p = deg.top(); int u;
  if(p.first == r - 1){
    u = p.second;
  }else{
    u = hp.top();
    if(u == ban) u = hp.top2();
    if(r == 3){
      int v = 0, w = 0;
      for(int i = 1;i <= n;i++){
        if(u != i && !vis[i]){
          if(v) w = i;
          else v = i;
        }
      }
      if(a[v] == w && a[w] == v){
        if(ban == v) u = w;
        else u = v;
      }
    }
  }
  if(!vis[a[u]]){
    deg.erase(mp(in[a[u]],a[u]));
    in[a[u]]--;
    deg.push(mp(in[a[u]],a[u]));
  }
  vis[u] = true;
  hp.erase(u);
  deg.erase(mp(in[u],u));
  in[u] = 0;
  return u;
}
int main(){
  n = getint();
  for(int i = 1;i <= n;i++){
    a[i] = getint();
    in[a[i]]++;
  }
  if(n == 2){
    puts("-1");
    return 0;
  }
  for(int i = 1;i <= n;i++){
    hp.push(i);
    deg.push(mp(in[i],i));
  }
  for(int i = 1;i <= n;i++){
    int u = fin_nxt(n - i + 1);
    printf("%d%c",u,i == n ? '\n' : ' ');
    if(!vis[a[u]]) ban = a[u];
    else ban = 0;
  }
  return 0;
}

