	std::vector<std::vector<int> > edge(N);
	for (int i = 0; i < N; i++) {
		std::cin >> a[i];
		edge[i].resize(N);
		for (int j = 0; j < N; j++) {
			if (a[i] - 1 == j || i == j) {
				edge[i][j] = 0;
			}
			else {
				edge[i][j] = 1;
			}
		}
	}
	for (int i = 0; i < N; i++) {
		for (int j = 0; j < N; j++) {
			flag[j] = 0;
		}
		int now = i;
		flag[i] = 1;
		int x = 0;
		bool f = true;
		ans[x] = now;
		while (x < N - 1) {
			for (int j = 0; j < N; j++) {
				if (flag[j] == 1 || edge[now][j] == 0) {
					if (j == N - 1) {
						f = false;
						x = N;
					}
					continue;
				}
				flag[j] = 1;
				now = j;
				x++;
				break;
			}
			ans[x] = now;
		}
		if (f) {
			for (int i = 0; i < N; i++) {
				std::cout << ans[i] + 1;
				if (i != N - 1) {
					std::cout << " ";
				}
				else {
					std::cout << std::endl;
				}
			}
			return 0;
		}
	}
	std::cout << "-1" << std::endl;
	return 0;
}

