	for (int i = 0; i < N - 3; i++) {
		auto a = st.begin();
		while ((*a) == dame){
				a++;
			}
		res[i] = (*a);
		dame = A[*a];
		mp[A[*a]]--;
		if (mp[A[*a]] == 0) {
			mp.erase(A[*a]);
		}
