		X.push_back(i);
	}
	bool ok = false;
	do {
		if (X[0] != dame && X[1] != A[X[0]] && X[2] != A[X[1]]) {
			ok = true;
			break;
		}
	} while (next_permutation(X.begin(), X.end()));
	for (int i = 0; i < 3; i++) {
		res[N - 3 + i] = X[i];
	}
	if (!ok) {
		int x = dame;
		vector<int> t;
		for (int i = N - 1; i >= -1; i--) {
			if (i == -1 || res[i] != dame) {
				if (i == -1 || A[res[i]] != dame) {
					sort(t.begin(), t.end());
					res[i + 1] = dame;
					if(A[dame] == t[0]){
						swap(t[0], t[1]);
