bool go(int a) {
	if (a == n)
		return 1;
	if (a != n - 1) {
		map<int, int> m;
		for (int i : hv)
			m[x[i]]++;
		for (auto& i : m)
			if (i.second == hv.size() - 1 && hv.count(i.first)) {
				if (a != 0 && x[ans[a - 1]] == i.first)
					return 0;
				ans[a] = i.second;
				hv.erase(ans[a]);
				if (go(a + 1))
					return 1;
				hv.insert(ans[a]);
				return 0;
			}
	}
	ans[a] = *hv.begin();
	if (a == 0 || x[ans[a - 1]] != ans[a]) {
		hv.erase(hv.begin());
		if (go(a + 1))
			return 1;
		hv.insert(ans[a]);
	}
	while (1) {
		auto it = hv.upper_bound(ans[a]);
		if (it == hv.end())
			break;
		ans[a] = *it;
		if (a == 0 || x[ans[a - 1]] != ans[a]) {
			hv.erase(it);
			if (go(a + 1))
				return 1;
			hv.insert(ans[a]);
		}
	}
	return 0;
