ll pow_long(ll x, ll k){
  ll res = 1;
  while(k > 0){
    if(k % 2) res *= x;
    x *= x; k /= 2;
  }
  return res;
}

ll pow_mod(ll x, ll k){
  ll res = 1;
  while(k > 0){
    if(k % 2){
      res *= x; res %= MOD;
    }
    x *= x; x %= MOD;
    k /= 2;
  }
  return res;
}

ll inverse(ll x){return pow_mod(x, MOD - 2);};

ll gcd(ll a, ll b){
    if(b == 0) return a;
    return gcd(b, a % b);
}

ll lcm(ll x, ll y){return x / gcd(x, y) * y;};

//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}

void solve(){
  ll N;
  cin >> N;
  vector<ll> A(N);
  rep(i, N){
    cin >> A[i];
    A[i]--;
  }

  if(N == 2){
    vector<ll> B = {0, 1};
    if(A[B[0]] != B[1]){
      cout << B[0] << " " << B[1] << endl;
      return;
    }
    B = {1, 0};
    if(A[B[0]] != B[1]){
      cout << B[0] << " " << B[1] << endl;
      return;
    }
    cout << -1 << endl;
    return;
  }
  vector<ll> ans;
  set<ll> rest;
  rep(i, N) rest.insert(i);
  while(rest.size() > 4){
    for(auto itr = rest.begin(); itr != rest.end(); itr++){
      if(ans.size() == 0 || A[ans.back()] != *itr){
        ans.pb(*itr);
        ll x = *itr;
        rest.erase(*itr);
        break;
      }
    }
  }

  vector<ll> R;
  for(auto itr = rest.begin(); itr != rest.end(); itr++){
    R.pb(*itr);
  }
  sort(R.begin(), R.end());

  do {
    if((ans.size() == 0 || A[ans.back()] != R[0]) && (R.size() < 2 || A[R[0]] != R[1]) && (R.size() < 3 || A[R[1]] != R[2]) && (R.size() < 4 || A[R[2]] != R[3])){
      ans.pb(R[0]);
      ans.pb(R[1]);
      ans.pb(R[2]);
      ans.pb(R[3]);
    }
 } while (std::next_permutation(R.begin(), R.end()));


  if(ans.size() < N){
    cout << -1 << endl;
    return;
  }



  rep(i, N){
    cout << ans[i] + 1 << " ";
  }
  cout << endl;


}


int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);
  solve();
}

