int dfs(int a,int b){
	if(a==N){
		return 1;
	}
	sk[a]=-1;
	for(int i=(a?sk[a-1]:0);i<(N/64+1);i++){
		if(!v[i])continue;
		if(sk[a]==-1)sk[a]=i;
		for(int j=0;j<64;j++){
			if(v[i]&(1LL<<j)){
				if(b!=-1&&i*64+j==p[b])continue;
				v[i]-=1LL<<j;
				ret[a]=i*64+j;
				int tmp=dfs(a+1,i*64+j);
				if(tmp)return 1;
				v[i]+=1LL<<j;
			}
		}
	}
	return 0;
}
