struct D{
    int cc,id;
    bool operator<(const D&a) const{
        if(cc==a.cc) return id<a.id;
        return cc>a.cc;
    }
};
int main()
{
    int n;
    cin>>n;
    vi a(n+1);
    vi cnt(n+1);
    for(int i=1;i<=n;i++) cin>>a[i];
    vi ans(n);
    if(n<=2)
        cout<<"-1\n";
    else{
        set<D> all;
        set<int> alln;
        for(int i=n;i>=1;i--)
            cnt[a[i]]++,alln.insert(i);
        for(int i=1;i<=n;i++)
            all.insert({cnt[i],i});
        int pre=0;
        for(int i=1;i<=n;i++)
        {
            if((*all.begin()).cc==n-i)
                ans[i-1]=(*all.begin()).id;
            else {
                for(auto u:alln){
                    if(u!=a[pre])
                    {
                        ans[i-1]=u;
                        break;
                    }
                }
            }
