bool check(vector<int>ans){
	for(int i=0;i+1<ans.size();i++){
		if(ban[ans[i]]==ans[i+1])return false;
	}
	return true;
}
map<int,int>cnt;
set<int>have;
vector<int>ans;
void del(int x){
	used[x]=1;cnt[ban[x]]--;if(!cnt[ban[x]])cnt.erase(ban[x]);
	have.erase(x);while(pos[ban[x]]<out[ban[x]].size()&&used[out[ban[x]][pos[ban[x]]]])pos[ban[x]]++;
	if(pos[ban[x]]!=out[ban[x]].size())have.insert(out[ban[x]][pos[ban[x]]]);
}
bool can_put(int x){
	if(ans.size()&&ban[ans.back()]==x)return false;
	have.erase(x);//cnt[ban[x]]--;if(!cnt[ban[x]])cnt.erase(ban[x]);
	bool ret=cnt.size()==2&&
	((cnt.begin()->second==1&&have.count(cnt.rbegin()->first))||
	((cnt.rbegin()->second==1&&have.count(cnt.begin()->first))));
	//cnt[ban[x]]++;
	have.insert(x);
	return 1^(ret);
}
int perm[6];
int main(){
	cin>>n;cur=n;
	for(int i=1;i<=n;i++)cin>>ban[i];
	for(int i=1;i<=n;i++)cnt[ban[i]]++,out[ban[i]].push_back(i);
	for(int i=1;i<=n;i++)if(out[i].size())have.insert(out[i][0]);
	for(int i=1;i<=n-5;i++){
		int ins=-1;
		if(cnt.size()==2){
			if(cnt.begin()->second==1)ins=cnt.rbegin()->first;
			else if(cnt.rbegin()->second==1)ins=cnt.begin()->first;
		}
		if(~ins)if(!used[ins])have.insert(ins);
		if(can_put(*have.begin())){
			ans.push_back(*have.begin());
			del(*have.begin());
		}else{
			ans.push_back(*next(have.begin()));
			del(*next(have.begin()));
		}
		if(have.count(ins))have.erase(ins);
		cur--;
	}
//	for(auto x:ans)cerr<<x<<" ";cerr<<endl;
	const int sz=min(n,5);
	const int base=max(0,n-5);
	for(int i=1;i<=sz;i++)perm[i]=i;
	vector<int>vec(have.begin(),have.end());
	for(int i=1;i<=n;i++)for(int j=pos[i]+1;j<out[i].size();j++)vec.push_back(out[i][j]);
	vector<int>pre=ans;for(int i=1;i<=sz;i++)ans.push_back(n+1);
	do{
		vector<int>tmp=pre;
		for(int i=1;i<=sz;i++)tmp.push_back(vec[perm[i]-1]);
		if(check(tmp))ans=min(ans,tmp);
	}while(next_permutation(perm+1,perm+sz+1));
	if(ans.back()==n+1){
		cout<<-1<<endl;
		return 0;
	}
	for(auto x:ans)cout<<x<<" ";cout<<endl;
	return 0;
}

