/*
最後の 2 つが、循環参照をしていたらアウトです。
また、全員に参照されているものがあったら、それはすぐに使わないと最後まで使えなくて詰みます。

各人の参照カウントを管理して、頂点数 - 1 のものがあったら使うをします。
これは、初期状態が 2 点循環参照だったとき以外は絶対に選べます。
また、そうでないときには最小のものを、それが無理なら次を選びます。

参照カウントは、添字をキーにした vector と、値だけの multiset で管理します。
頂点を消したら、それが参照していたものの参照カウントを 1 減らし、自分を 0 にします。
*/

#include<bits/stdc++.h>
using namespace std;

#define FOR(i, a, b) for(int i = a; i < b; ++i)
#define REP(i, n) FOR(i, 0, n)
#define _ << " " <<
#define sz(x) ((int) x.size())
#define pb(x) push_back(x)
#define TRACE(x) cerr << #x << " = " << x << endl

typedef long long ll;
typedef pair<int, int> point;

const int mod = 1e9 + 7;

int add(int x, int y) {x += y; if(x >= mod) return x - mod; return x;}
int sub(int x, int y) {x -= y; if(x < 0) return x + mod; return x;}
int mul(int x, int y) {return (ll) x * y % mod;}

const int MAXN = 1e5 + 5;

int n, a[MAXN], deg[MAXN];
set<point> degrees;
set<int> S;

bool check(vector <int> &v){
  REP(i, n - 1)
    if(a[ v[i] ] == v[i + 1])
      return false;
  return true;
}

void permutiraj(vector <int> &v){
  vector <int> tmp;
  FOR(i, n - 3, n)
    tmp.pb(v[i]);

  REP(i, 3)
    v.pop_back();

  vector <int> ret;
  do{
    REP(i, 3)
      v.pb(tmp[i]);

    if(check(v)){
      if(ret.empty())
        ret = v;
      else
        ret = min(ret, v);
    }

    REP(i, 3)
      v.pop_back();

  } while(next_permutation(tmp.begin(), tmp.end()));
  v = ret;
}

void ubaci(int id){
  S.erase(id);
  if(degrees.find( point(deg[a[id]], a[id]) ) != degrees.end()){
    degrees.erase(point(deg[a[id]], a[id]));
    deg[ a[id] ] --;
    degrees.insert(point(deg[a[id]], a[id]));
  }
  if(degrees.find( point(deg[id], id) ) != degrees.end())
    degrees.erase( point(deg[id], id) );
}

int main(){
  ios_base::sync_with_stdio(false); cin.tie(0);

  cin >> n;
  FOR(i, 1, n + 1){
    S.insert(i);
    cin >> a[i];
    deg[a[i]] ++;
  }

  if(n == 2){
    if(a[1] == 2 && a[2] == 1)
      cout << -1;
    else{
      if(a[1] == 1 && a[2] == 1)
        cout << 1 _ 2;
      else
        cout << 2 _ 1;
    }
    return 0;
  }

  FOR(i, 1, n + 1){
    degrees.insert(point(deg[i], i));
  }
  vector <int> sol;
  REP(i, n){
    set<int> :: iterator it = S.begin();

    if(degrees.rbegin() -> first == sz(S) - 1 && sz(S) > 2){
      int id = degrees.rbegin() -> second;
      sol.pb(id);
      ubaci(id);
    }
    else{
      int num1 = *it, num2 = *it;
      if(sz(S) > 1){
        it ++;
        num2 = *it;
      }
      int id = MAXN - 1;
      if(i != 0)
        id = sol.back();

      if(a[id] == num1){
        sol.pb(num2);
        ubaci(num2);
      }
      else{
        sol.pb(num1);
        ubaci(num1);
      }
    }
  }

  if(!check(sol))
    permutiraj(sol);

  for(auto it : sol)
    cout << it << " ";
}

