const int N=100000;

int n,a[N+9],deg[N+9];

void into(){
  scanf("%d",&n);
  for (int i=1;i<=n;++i){
	scanf("%d",&a[i]);
	++deg[a[i]];
  }
}


int tmp[N+9],ct;
int vis[N+9];
int ans[N+9];

bool Dfs_ans(int k,int last){
  if (k>n) return 1;
  for (int i=1;i<=ct;++i)
	if (!vis[i]&&a[last]^tmp[i]){
	  vis[i]=1;
	  ans[k]=tmp[i];
	  if (Dfs_ans(k+1,tmp[i])) return 1;
	  vis[i]=0;
	}
  return 0;
}

struct state{
  int x,v;
  state(int X=0,int V=0){x=X;v=V;}
  bool operator < (const state &p)const{return v>p.v||v==p.v&&x<p.x;}
};
set<state>sdeg;
set<int>sid;

void Get_ans(){
  if (n==2) return;
  for (int i=1;i<=n;++i){
	sdeg.insert(state(i,deg[i]));
	sid.insert(i);
  }
  for (int i=1;i<=n;++i){
	int t=a[ans[i-1]]==*sid.begin()?*++sid.begin():*sid.begin();
	if (sdeg.begin()->v==n-i) t=sdeg.begin()->x;
	ans[i]=t;
	sdeg.erase(state(t,deg[t]));
	sid.erase(t);
	if (sid.find(a[t])!=sid.end()){
	  sdeg.erase(state(a[t],deg[a[t]]));
	  sdeg.insert(state(a[t],--deg[a[t]]));
	}
  }
  ans[0]=1;
}

void work(){
  Get_ans();
}

void outo(){
  if (!ans[0]) puts("-1");
  else{
	for (int i=1;i<=n;++i)
	  printf("%d ",ans[i]);
    puts("");
  }
}

int main(){
  into();
  work();
  outo();
  return 0;
}

