void solve() {
  int n; cin >> n;

  if (n == 2) {
    cout << -1 << endl;
    return;
  }

  vi arr(n+1);
  vi forbid(n+1);
  rep1eq(i,n) {
    cin >> arr[i];
    forbid[arr[i]]++;
  }

  set<int> s;
  rep1eq(i,n) s.emplace_hint(s.end(), i);

  vi ans;

  while (s.size() > 3) {
    auto itr = s.begin();
    if (forbid[arr[*itr]] == s.size() - 1) {
      ans.emplace_back(arr[*itr]);
      forbid[arr[*itr]] = 0;
      forbid[arr[arr[*itr]]]--;
      s.erase(arr[*itr]);
    } else {
      if (!ans.empty() && arr[ans.back()] == *itr) itr++;
      ans.emplace_back(*itr);
      forbid[*itr] = 0;
      forbid[arr[*itr]]--;
      s.erase(itr);
    }
  }

  vi perm;
  for (auto &v : s) perm.emplace_back(v);

  do {
    if (!ans.empty() && arr[ans.back()] == perm[0]) continue;
    if (arr[perm[0]] == perm[1]) continue;
    if (arr[perm[1]] == perm[2]) continue;
    break;
  } while (next_permutation(ALL(perm)));

  if (!ans.empty()) cout << ans << " ";
  cout << perm << endl;
}


