void _main()
{
    ll n; llin(n);
    S V<ll> alist; alist.pb(-1LL); llina(alist, n);

    if (n == 2) {
        cout << -1 << endl;
        return;
    }

    if (n == 3) {
        solve3(alist);
        return;
    }

    S priority_queue_incr<ll> q;
    srep (i, 1, n+1) q.push(i);
    ll ng = -1LL;
    S V<ll> anslist;

    while (!q.empty()) {
        ll v1 = q.top(); q.pop();
        ll v2 = -1LL;
        if (!q.empty()) {
            v2 = q.top(); q.pop();
        }

        if (v2 < 0LL) {
            anslist.pb(v1);
            ng = alist[v1];
            continue;
        }

        if (v1 == ng) {
            anslist.pb(v2);
            ng = alist[v2];
            q.push(v1);
        }
        else {
            anslist.pb(v1);
            ng = alist[v1];
            q.push(v2);
        }
    }

    assert(anslist.size() == n);

    ll swapcnt = 0LL;
    rrep (i, n-1) {
        ll val1 = anslist[i];
        ll val2 = anslist[i+1];
        if (alist[val1] != val2) break;
        ll tmp = anslist[i];
        anslist[i] = anslist[i+1];
        anslist[i+1] = tmp;
        swapcnt++;
    }

    ll val1, val2, val3, val_head, tmp;

    switch (swapcnt) {
    case 0:
        debug_printf("---- output 0\n");
        output(anslist, alist, n);
        break;
    case 1:
        debug_printf("---- output 1\n");
        val1 = anslist[n-2];
        val2 = anslist[n-1];
        if (alist[val1] == val2) {
            debug_printf("-------- swap start\n");
            tmp = anslist[n-2];
            anslist[n-2] = anslist[n-1];
            anslist[n-1] = tmp;

            val_head = anslist[n-4];
            val1 = anslist[n-3];
            val2 = anslist[n-2];
            val3 = anslist[n-1];
            assert(val2 < val3);

            if (alist[val_head] == val2) {
                debug_printf("-------- swap 1\n");
                anslist[n-3] = val3;
                anslist[n-2] = val1;
                anslist[n-1] = val2;
            }
            else {
                debug_printf("-------- swap 2\n");
                anslist[n-3] = val2;
                anslist[n-2] = val1;
                anslist[n-1] = val3;
            }
        }
        output(anslist, alist, n);
        break;
    default:
        debug_printf("---- output 2\n");
        ll idx = n - swapcnt - 1LL;
        sort(anslist.begin() + idx + 1LL, anslist.end());
        val1 = anslist[idx];
        val2 = anslist[idx+1];
        if (alist[val1] == val2) {
            debug_printf("---- swap 1\n");
            tmp = anslist[idx+1];
            anslist[idx+1] = anslist[idx+2];
            anslist[idx+2] = tmp;
        }
        output(anslist, alist, n);
        break;
    }
}

