int64 mark[SIZE];
int64 ans[SIZE];

int main()
{
  int64 N;
  int64 *seq;
  int64 i,n,cnt,fill,ai,skip;

  get_N(&N);
  seq = get_NSeq(N);

  ans[0] = 1;
  mark[0] = 1;
  cnt=1;
  ai=1;
retry:
  fill = 0;
  skip = 0;
  for (i=1; i<N; i++) {
    n = i+1;
    if (mark[i] == 0) {
      if (seq[ans[ai-1] - 1] != n) {
        ans[ai] = n;
        ai++;
        mark[i] = 1;
        cnt++;
        fill++;
        if (skip) {
          goto retry;
        }
      }
      skip++;
    }
  }//for
  if ((cnt < N) &&
      (fill > 0)) {
    goto retry;
  }
  if (cnt < N){
    printf("-1");
    return 0;
  }

  for (i=0; i<N; i++) {
    printf("%lld ", ans[i]);
  }
  return 0;
}

