	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * 第6回 ドワンゴからの挑戦状 予選 D問題
		 * 考察メモ
		 * 各カードについて禁止されているカードは少ないため、殆どのケースは構築可能っぽい
		 * というかかなり小さい数字が構築できそうな気がする
		 * 必要条件を考えていこう
		 * 1. N-1個のa_iが同じ数字を指している⇒その数字が使用済みなら自由、そうでないなら左端にその数字を置くしかない
		 * 逆に、その時その数字の候補外の最小の数字を置いた後は自由に構築できるので終わり
		 * 反例は2 1だけで、これは無理(Sample2)
		 *
		 * 2. 上の条件に当てはまらない⇒とりあえず左端に(直前の禁止を除く)最小の数字を置ける
		 * その時、次の数字は1個の候補を除いて同じように考えることができる
		 * はい
		 *
		 */
		int N = io.nextInt();
		int[] a = io.nextInt(N);
		for (int i = 0;i < N;++ i) -- a[i];

		HashMap<Integer, Integer> map = new HashMap<>(N);
		TreeSet<Integer> set = new TreeSet<>();
		for (int i : a) map.compute(i, (k, v) -> v == null ? 1 : v + 1);
		for (int i = 0;i < N;++ i) set.add(i);
		io.setAutoFlush(true);

		ArrayList<Integer> ans = new ArrayList<>(N);
		int ban = -1;
		cont: for (int i = 0;i < N;++ i) {
			if (map.size() == 2) {
				for (Entry<Integer, Integer> entry : map.entrySet()) {
					if (entry.getValue() == N - i - 1 && set.contains(entry.getKey())) { // となるとその数字を使わないと詰む
						if (entry.getKey() == ban) { // これは詰み
							io.println(-1);
							return;
						}
						ban = a[entry.getKey()];
						ans.add(entry.getKey() + 1);
						set.remove(entry.getKey());
						map.compute(a[entry.getKey()], (k, v) -> v == 1 ? null : v - 1);
						continue cont;
					}
				}
			}
			int min = set.first();
			if (min == ban) {
				if (set.size() == 1) { // ban以外候補が無いので詰み
					io.println(-1);
					return;
				}
				min = set.higher(ban);
			}
			ban = a[min];
			ans.add(min + 1);
			set.remove(min);
			map.compute(a[min], (k, v) -> v == 1 ? null : v - 1);
			continue cont;
		}
		for (int i = 0;i < N - 1;++ i) { // 検証
			if (a[ans.get(i) - 1] == ans.get(i + 1) - 1) {
				io.println(-1);
				return;
			}
		}
		io.println(ans, " ");
	}

