public class Main implements Runnable{

	private void solve(FastIO io, String[] args) {
		/*
		 * author: 31536000
		 * 第6回 ドワンゴからの挑戦状 予選 D問題
		 * 考察メモ
		 * 各カードについて禁止されているカードは少ないため、殆どのケースは構築可能っぽい
		 * というかかなり小さい数字が構築できそうな気がする
		 * 必要条件を考えていこう
		 * 1. N-1個のa_iが同じ数字を指している⇒その数字が使用済みなら自由、そうでないなら左端にその数字を置くしかない
		 * 逆に、その時その数字の候補外の最小の数字を置いた後は自由に構築できるので終わり
		 * ちなみにこれで詰むのは互いを参照する2個を残しちゃったとき
		 * ...従って、これを回避するように動かなければならないね
		 * 残り2個かつ1を呼ばない限りはまず必ずセーフ
		 * よって残り2個の条件で1になるような取り方をしないことを考える
		 * 細かいのは下へ
		 *
		 * 2. 上の条件に当てはまらない⇒とりあえず左端に(直前の禁止を除く)最小の数字を置ける
		 * その時、次の数字は1個の候補を除いて同じように考えることができる
		 * ところで、先のデッドロックは解消しなきゃいけない
		 * これは、残り4個の時点を考える
		 * まず、両方BANはありえないから、デッドロックの片方は取れる
		 * そうするとデッドロックしてるやつは残りの1個を取って、無事に解決できそう？
		 * 仮定よりデッドロック以外も2種以上あって必ず動けるので行けそうね
		 * つまり、デッドロックではない残った1個を見て、そっちがBANしている方を取りに行ける
		 *
		 *
		 */
		int N = io.nextInt();
		if (N == 2) { // 不可能なので
			io.println(-1);
			return;
		}
		int[] a = io.nextInt(N);
		for (int i = 0;i < N;++ i) -- a[i];

		HashMap<Integer, Integer> map = new HashMap<>(N);
		TreeSet<Integer> set = new TreeSet<>();
		for (int i : a) map.compute(i, (k, v) -> v == null ? 1 : v + 1);
		for (int i = 0;i < N;++ i) set.add(i);
		io.setAutoFlush(true); // TODO デバッグ用、消して

		ArrayList<Integer> ans = new ArrayList<>(N);
		int ban = -1;
		cont: for (int i = 0;i < N - 1;++ i) {
			if (map.size() == 2) {// 残り全部がその数字を指定しているなら必ずこれに引っ掛かる
				for (Entry<Integer, Integer> entry : map.entrySet()) {
					if (entry.getValue() == N - i - 1 && set.contains(entry.getKey())) { // となるとその数字を使わないと詰む
						ban = a[entry.getKey()];
						ans.add(entry.getKey() + 1);
						set.remove(entry.getKey());
						map.compute(a[entry.getKey()], (k, v) -> v == 1 ? null : v - 1);
						continue cont;
					}
				}
			} // 構築可能
			if (N - i == 4) { // この時点で、残りを見てヤバいケースをはじきにいく
				Integer[] list = set.toArray(new Integer[4]);
				Arrays.sort(list); // 多分大丈夫だと思うけど……
				if (a[list[2]] == list[3] && a[list[3]] == list[2]) { // 最後2個がデッドロックの時=ヤバい
					int check = ban == list[0] ? 1 : 0;
					ans.add(list[check] + 1);
					if (a[list[1 ^ check]] == list[3]) {
						ans.add(list[3] + 1);
						ans.add(list[1 ^ check] + 1);
						ans.add(list[2] + 1);
					} else {
						ans.add(list[2] + 1);
						ans.add(list[1 ^ check] + 1);
						ans.add(list[3] + 1);
					}
					break cont;
				} // そうでないならまぁ大丈夫でしょ(もしロックしてても良い感じに破壊されるので)
			}
			int min = set.first();
			if (min == ban) min = set.higher(ban);  // これだとダメなので次の候補へ、勿論こっちは作れるよね
			ban = a[min];
			ans.add(min + 1);
			set.remove(min);
			map.compute(a[min], (k, v) -> v == 1 ? null : v - 1);
		}
		if (ans.size() != N) ans.add(set.first() + 1); // 最後の1個は自動で決まるね
		/*for (int i = 0;i < N - 1;++ i) { // 検証、もちろん落ちたらアウトです
			if (a[ans.get(i) - 1] == ans.get(i + 1) - 1) {
				System.exit(1);
			}
		}*/
		io.println(ans, " ");
	}

