    static class DArrangement {
        Debug debug = new Debug(false);

        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] next = new int[n + 1];
            int[] forbidden = new int[n + 1];
            boolean[] used = new boolean[n + 1];
            for (int i = 1; i <= n; i++) {
                next[i] = in.readInt();
                forbidden[next[i]]++;
            }

            int first = 0;
            for (int i = 1; i <= n; i++) {
                if (forbidden[next[i]] < n - 1) {
                    first = i;
                    break;
                }
            }

            if (first == 0) {
                out.println(-1);
                return;
            }

            PriorityQueue<Integer> pq = new PriorityQueue<>(n);
            for (int i = 1; i <= n; i++) {
                if (i == first) {
                    continue;
                }
                pq.add(i);
            }

            int last = first;
            IntegerList seq = new IntegerList(n);
            seq.add(last);
            forbidden[next[last]]--;
            used[last] = true;

            List<Integer> backup = new ArrayList<>();
            while (!pq.isEmpty()) {
                int remain = pq.size();
                debug.debug("seq", seq);
                debug.debug("remain", remain);
                int head = pq.remove();
                if (head == next[last] || !used[next[head]] && forbidden[next[head]] == remain - 1) {
                    backup.add(head);
                    head = pq.remove();
                }
                last = head;
                seq.add(last);
                forbidden[next[last]]--;
                used[last] = true;
                pq.addAll(backup);
                //debug.debug("forbidden", forbidden);
                //debug.debug("backup", backup);
                backup.clear();
            }

            for (int i = 0; i < seq.size(); i++) {
                out.append(seq.get(i)).append(' ');
            }
        }

    }

    static class SequenceUtils {
        public static boolean equal(int[] a, int al, int ar, int[] b, int bl, int br) {
            if ((ar - al) != (br - bl)) {
                return false;
            }
            for (int i = al, j = bl; i <= ar; i++, j++) {
                if (a[i] != b[j]) {
                    return false;
                }
            }
            return true;
        }

    }

    static class IntegerList implements Cloneable {
        private int size;
        private int cap;
        private int[] data;
        private static final int[] EMPTY = new int[0];

        public IntegerList(int cap) {
            this.cap = cap;
            if (cap == 0) {
                data = EMPTY;
            } else {
                data = new int[cap];
            }
        }

        public IntegerList(IntegerList list) {
            this.size = list.size;
            this.cap = list.cap;
            this.data = Arrays.copyOf(list.data, size);
        }

        public IntegerList() {
            this(0);
        }

        public void ensureSpace(int req) {
            if (req > cap) {
                while (cap < req) {
                    cap = Math.max(cap + 10, 2 * cap);
                }
                data = Arrays.copyOf(data, cap);
            }
        }

        private void checkRange(int i) {
            if (i < 0 || i >= size) {
                throw new ArrayIndexOutOfBoundsException();
            }
        }

        public int get(int i) {
            checkRange(i);
            return data[i];
        }

        public void add(int x) {
            ensureSpace(size + 1);
            data[size++] = x;
        }

        public void addAll(int[] x, int offset, int len) {
            ensureSpace(size + len);
            System.arraycopy(x, offset, data, size, len);
            size += len;
        }

        public void addAll(IntegerList list) {
            addAll(list.data, 0, list.size);
        }

        public int size() {
            return size;
        }

        public int[] toArray() {
            return Arrays.copyOf(data, size);
        }

        public String toString() {
            return Arrays.toString(toArray());
        }

        public boolean equals(Object obj) {
            if (!(obj instanceof IntegerList)) {
                return false;
            }
            IntegerList other = (IntegerList) obj;
            return SequenceUtils.equal(data, 0, size - 1, other.data, 0, other.size - 1);
        }

        public int hashCode() {
            int h = 1;
            for (int i = 0; i < size; i++) {
                h = h * 31 + Integer.hashCode(data[i]);
            }
            return h;
        }

        public IntegerList clone() {
            IntegerList ans = new IntegerList();
            ans.addAll(this);
            return ans;
        }

    }

