    static int[] nextPermutation(int[] a){
        int n=a.length;
        for(int i=n-1;i>=1;i--){
            if(a[i]>a[i-1]){
                int fail=n, pass=i;
                while(fail-pass>1){
                    int mid=pass+(fail-pass)/2;
                    if(a[mid]>a[i-1]) pass=mid;
                    else fail=mid;
                }
                int tmp=a[pass];
                a[pass]=a[i-1];
                a[i-1]=tmp;
                reverse(a, i, n);
                return a;
            }
        }
        return null;
    }

    static void reverse(int[] a, int begin, int end){
        for(int i=begin;i<begin+(end-begin)/2;i++){
            int tmp=a[i];
            a[i]=a[begin+end-i-1];
            a[begin+end-i-1]=tmp;
        }
    }
    static void reverse(int[] a){
        reverse(a, 0, a.length);
    }
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;
        private boolean hasNextByte(){
            if(ptr<buflen) return true;
            else{
                ptr = 0;
                try{
                    buflen = in.read(buffer);
                }
                catch(IOException e){
                    e.printStackTrace();
                }
                if(buflen<=0) return false;
            }
        return true;
        }
        private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
        private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
        public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
        public String next() {
            if (!hasNext()) throw new NoSuchElementException();
            StringBuilder sb = new StringBuilder();
            int b = readByte();
            while(isPrintableChar(b)) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        }
        public long nextLong() {
            if (!hasNext()) throw new NoSuchElementException();
            long n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
                minus = true;
                b = readByte();
            }
            if (b < '0' || '9' < b) throw new NumberFormatException();
            while(true){
                if ('0' <= b && b <= '9') {
                    n *= 10;
                    n += b - '0';
                }
                else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
                else throw new NumberFormatException();
                b = readByte();
            }
        }
        public int nextInt() {
            long nl = nextLong();
            if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
            return (int) nl;
        }
        public double nextDouble() { return Double.parseDouble(next());}
        public void close(){
            try{in.close();}
            catch(IOException e){e.printStackTrace();}
        }
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.PriorityQueue;

public class Main {

  private static void solve() {
    int n = ni();
    int[] a = new int[n];
    PriorityQueue<Integer> q = new PriorityQueue<>();
    int[] cnt = new int[n];
    for (int i = 0; i < n; i++) {
      a[i] = ni() - 1;
      cnt[a[i]]++;
      q.add(i);
    }

    PriorityQueue<Integer> q2 = new PriorityQueue<>((o1, o2) -> {
      if (cnt[o2] == cnt[o1]) {
        return o1 - o2;
      } else {
        return cnt[o2] - cnt[o1];
      }
    });
    for (int i = 0; i < n; i++) {
      q2.add(i);
    }

    StringBuilder sb = new StringBuilder();
    int pre = -1;
    Deque<Integer> deq = new ArrayDeque<>();
    boolean[] used = new boolean[n];
    while (q.size() > 0) {
      if (cnt[q2.peek()] >= q.size() - 1 && !used[q2.peek()]) {
        int v = q2.peek();
        q.remove(v);
        q2.remove(v);
        cnt[v]--;
        q2.add(v);
        sb.append(v + 1 + " ");
        used[v] = true;
        pre = v;
      } else {
        while (q.size() > 0 && pre >= 0 && a[pre] == q.peek()) {
          deq.add(q.poll());
        }

        if (q.size() == 0) {
          System.out.println(-1);
          return;
        }
        pre = q.poll();
        sb.append(pre + 1 + " ");
        used[pre] = true;

        for (int v : deq) {
          q.add(v);
