        int[] ng=new int[n+1];
        TreeSet<Integer> set=new TreeSet<>();
        for(int i=1;i<=n;i++){
            ng[i]=fsc.nextInt();
            set.add(i);
        }
        fsc.close();
        int[] ans=new int[n];
        int ngl=0;
        if(n>3){
            ans[0]=set.pollFirst();
            for(int i=1;i<n-3;i++){
                int f=set.pollFirst();
                if(f!=ng[ans[i-1]]){
                    ans[i]=f;
                } else{
                    ans[i]=set.pollFirst();
                    set.add(f);
                }
            }
            ngl=ng[ans[n-4]];
        }
        int size=set.size();
        int[] rest=new int[size];
        for(int r=0;r<size;r++){
            rest[r]=set.pollFirst();
        }
        W:while(true){
            for(int i=0;i<size;i++){
                if((i>0?ng[rest[i-1]]:ngl)==rest[i]){
                    if(Objects.isNull(nextPermutation(rest))){
                        System.out.println(-1);
                        return;
                    }
                    continue W;
                }
            }
            for(int i=0;i<size;i++){
                ans[n-3+i]=rest[i];
