		List<Integer> list = new ArrayList<>();
		while (list.size() < n) {
			Integer o1 = set1.pollFirst();
			if (o1 != null) {
				Integer o2 = set2.pollFirst();
				if (o2 != null && o2 < o1) {
					set2.add(o1);
					o1 = o2;
				}
				if (list.isEmpty() || a[list.get(list.size() - 1)] != o1) {
					list.add(o1);
				} else {
					Integer[] arr = set2.toArray(new Integer[0]);
					for (Integer o : arr) {
						int i = list.get(list.size() - 1);
						if (a[i] != o) {
							list.add(o);
							set2.remove(o);
							break;
						}
					}
					set2.add(o1);
				}
			} else {
				Integer[] arr = set2.toArray(new Integer[0]);
				for (Integer o : arr) {
					for (int i = list.size() - 1; i >= 0; i--) {
						if (a[list.get(i)] != o &&
								(i == list.size() - 1 ||
										!map.containsKey(list.get(i + 1)) ||
										!map.get(list.get(i + 1)).contains(o))) {
							list.add(i + 1, o);
							break;
						}
					}
				}
				if (list.size() < n) {
					throw new Exception();
				}
			}
		}
		StringBuilder sb = new StringBuilder();
		sb.append(list.get(0));
		for (int i = 1; i < n; i++) {
			sb.append(' ').append(list.get(i));
		}
		System.out.println(sb.toString());
	}
}

