                    }
                    for (int i = 0; i < 4; i++) {
                        b[n - 4 + i] = tmp[i];
                    }
                    break;
                }
            } while (ArrayUtils.nextPermutation(c));
            for (int i = 0; i < n; i++) {
                if (i > 0) out.print(" ");
                out.printLine(b[i] + 1);
            }
        }

