        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public int[] nextIntArray(final int n) {
            final int[] res = new int[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextInt();
            }
            return res;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.*;
import java.util.stream.Collectors;
import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
	int N;
	int[] a;
	Queue<Integer> que = new PriorityQueue<>();
	List<Integer> result = new ArrayList<>();

	public static void main(String[] args) throws IOException {
		InputStreamReader reader = new InputStreamReader(System.in, StandardCharsets.UTF_8);
		BufferedReader in = new BufferedReader(reader);
		Main ins = new Main(in);
		ins.calc();
		ins.showResult();
	}

	Main(BufferedReader in) throws IOException {
		N = Integer.parseInt(in.readLine());
		this.a = new int[N];
		String[] tokens = in.readLine().split(" ");
		for (int i = 0; i < N; ++i) {
			this.a[i] = Integer.parseInt(tokens[i]);
		}
		for(int i= 1; i <= N; ++i) {
			que.add(i);
		}
	}

	int getNext(int invalidValue) {
		int result = -1;
		List<Integer> list = new ArrayList<>(que.size());
		while (!que.isEmpty()) {
			int val = que.poll();
			if (val != invalidValue) {
				result = val;
				break;
			} else {
				list.add(val);
			}
		}
		que.addAll(list);
		return result;
	}

	void calc() {
		// 順に入れていく
		// 最初の要素は自由に入れられる
		result.add(que.poll());
		int prevVal = result.get(0) - 1;
		for (int i = 0; i < N - 1; ++i) {
			int next = getNext(a[prevVal]);
			if (next < 0) {
				result = null;
				break;
			}
			result.add(next);
			prevVal = next - 1;
		}
	}

	void showResult() {
		if (result == null) {
			System.out.println("-1");
		} else {
			StringBuilder strBuilder = new StringBuilder();
			strBuilder.append(result.get(0));
			for (int i = 1; i < result.size(); ++i) {
				strBuilder.append(" " + result.get(i));
			}
			System.out.println(strBuilder.toString());
		}
	}
}

