    static class DArrangement {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int[] a = in.readIntArray(n);
            MiscUtils.decreaseByOne(a);

            if (n == 2) {
                out.printLine(-1);
                return;
            }

            if (n <= 5) {
                int[] b = ArrayUtils.createOrder(n);
                do {
                    boolean flg = true;
                    for (int i = 0; i < n - 1; i++) {
                        if (a[b[i]] == b[i + 1]) flg = false;
                    }
                    if (flg) {
                        for (int i = 0; i < n; i++) {
                            if (i > 0) out.print(" ");
                            out.print(b[i] + 1);
                        }
                        out.printLine();
                        return;
                    }
                } while (ArrayUtils.nextPermutation(b));
            }

            int[] b = ArrayUtils.createOrder(n);
            for (int i = 0; i < n - 4; i++) {
                if (a[b[i]] == b[i + 1]) {
                    int tmp = b[i + 1];
                    b[i + 1] = b[i + 2];
                    b[i + 2] = tmp;
                }
            }
            int[] c = ArrayUtils.createOrder(4);
            do {
                boolean flg = true;
                if (a[b[n - 5]] == b[n - 4 + c[0]]) flg = false;
                for (int i = 0; i < 3; i++) {
                    if (a[b[n - 4 + c[i]]] == b[n - 4 + c[i + 1]]) flg = false;
                }
                if (flg) {
                    int[] tmp = new int[4];
                    for (int i = 0; i < 4; i++) {
                        tmp[i] = b[n - 4 + i];
                    }
                    for (int i = 0; i < 4; i++) {
                        b[n - 4 + c[i]] = tmp[i];
                    }
                    break;
                }
            } while (ArrayUtils.nextPermutation(c));
            for (int i = 0; i < n; i++) {
                if (i > 0) out.print(" ");
                out.print(b[i] + 1);
            }
            out.printLine();
        }

    }

