    static class DArrangement {
        public void solve(int testNumber, FastInput in, FastOutput out) {
            int n = in.readInt();
            int[] next = new int[n];
            for (int i = 0; i < n; i++) {
                next[i] = in.readInt() - 1;
            }

            if (n == 2) {
                out.println(-1);
                return;
            }

            PriorityQueue<Integer> queue = new PriorityQueue<>(n);
            IntegerList ans = new IntegerList(n);
            for (int i = 0; i < n; i++) {
                queue.add(i);
            }

            int forbid = -1;
            while (queue.size() > 3) {
                if (queue.peek() != forbid) {
                    ans.add(queue.remove());
                } else {
                    queue.remove();
                    ans.add(queue.remove());
                    queue.add(forbid);
                }
                forbid = next[ans.tail()];
            }

            int[] x = bf(forbid, next, queue);
            if (x == null) {
                ans.clear();
                ans.add(1);
                for (int i = 0; i < n; i++) {
                    if (i != 1)
                        queue.add(i);
                }
                forbid = next[1];
                while (queue.size() > 3) {
                    if (queue.peek() != forbid) {
                        ans.add(queue.remove());
                    } else {
                        queue.remove();
                        ans.add(queue.remove());
                        queue.add(forbid);
                    }
                    forbid = next[ans.tail()];
                }
                x = bf(forbid, next, queue);
            }
            ans.addAll(x);
            for (int i = 0; i < n; i++) {
                out.append(ans.get(i) + 1).append(' ');
            }
        }

        public int[] bf(int forbid, int[] next, PriorityQueue<Integer> pq) {
            int a = pq.remove();
            int b = pq.remove();
            int c = pq.remove();
            int[][] allWay = new int[][]{
                    {a, b, c},
                    {a, c, b},
                    {b, a, c},
                    {b, c, a},
                    {c, a, b},
                    {c, b, a}
            };

            for (int[] way : allWay) {
                if (forbid != way[0] && next[way[0]] != way[1] && next[way[1]] != way[2]) {
                    return way;
                }
            }
            return null;
        }

    }

