        int[] b = new int[n];

        ArrayList<Integer> mstList = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
            mstList.add(i + 1);
        }

        loop:
        for (int x = 0; x < n; x++) {
            if (b[n -1] > 0) {
                break;
            }
            ArrayList<Integer> list = (ArrayList<Integer>)mstList.clone();
            b[0] = list.get(x);
