            for (int i = 1; i <= n; i++) {
                if (forbidden[next[i]] < n - 1) {
                    first = i;
                    break;
                }
            }

            if (first == 0) {
                out.println(-1);
                return;
            }

            PriorityQueue<Integer> pq = new PriorityQueue<>(n);
            for (int i = 1; i <= n; i++) {
                if (i == first) {
                    continue;
                }
                pq.add(i);
            }

            int last = first;
            IntegerList seq = new IntegerList(n);
            seq.add(last);
            forbidden[next[last]]--;
            used[last] = true;

            List<Integer> backup = new ArrayList<>();
            while (!pq.isEmpty()) {
                int remain = pq.size();
                int head = pq.remove();
                if (head == next[last] || !used[next[last]] && forbidden[next[last]] == remain - 1) {
                    backup.add(head);
                    head = pq.remove();
                }
                last = head;
                seq.add(last);
                forbidden[next[last]]--;
                used[last] = true;
                pq.addAll(backup);
                backup.clear();
            }

            for (int i = 0; i < seq.size(); i++) {
