class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        var A = new int[N];
        var ct = new int[N];
        for (var i = 0; i < N; i++)
        {
            A[i] = sc.Next<int>() - 1;
            ct[A[i]]++;
        }
        var q = new PriorityQueue<int>();
        for (var i = 0; i < N; i++) q.Push(i);
        var use = new bool[N];
        var res = new List<int>();
        for (var i = 0; i < N-5; i++)
        {
            var p = q.Pop();
            while (q.Any() && use[q.Top]) q.Pop(); 
            if (i > 0 && A[res[i - 1] - 1] == p)
            {
                var t = p;
                p = q.Pop();
                while (q.Any() && use[q.Top]) q.Pop();
                q.Push(t);
            }
            if (!use[A[p]]&&ct[A[p]] == N - i - 1)
            {
                q.Push(p);
                p = A[p];
            }
            use[p] = true;
            ct[A[p]]--;
            res.Add(p + 1);
            while (q.Any() && use[q.Top]) q.Pop();
        }
        var a = q.data.Where(v=>!use[v]).ToList();a.Sort();
        foreach (var p in Permutations(Enumerable.Range(0, a.Count).ToArray()))
        {
            var b = true;
            if (res.Count > 0)
                b = A[res.Last() - 1] != a[p[0]];
            for (var j = 0; j < a.Count - 1; j++)
                b &= A[a[p[j]]] != a[p[j + 1]];
            if (b) { res.AddRange(Enumerable.Range(0, a.Count).Select(v => a[p[v]] + 1).ToArray()); Console.WriteLine(string.Join(" ", res)); return; }
        }
        WriteLine(-1);
    }
    static IEnumerable<T[]> Permutations<T>(T[] array) where T : IComparable<T>
    {
        int index = 0;
        yield return array;
        while (true)
        {
            for (int i = array.Length - 1; i > 0; i--)
            {
                if (array[i - 1].CompareTo(array[i]) >= 0) continue;
                int j = Array.FindLastIndex(array, x => array[i - 1].CompareTo(x) < 0);
                T tmp = array[i - 1]; array[i - 1] = array[j]; array[j] = tmp;
                Array.Reverse(array, i, array.Length - i);
                yield return array;
                goto end;
            }
            Array.Reverse(array, index, array.Length);
            yield break;
        end:;
        }
    }
}

public class PriorityQueue<T>
{
    public List<T> data = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return data.Count; } }
    public T Top { get { return data[0]; } }
    public PriorityQueue() { cmp = cmp ?? Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Push(T val)
    {
        int i = data.Count;
        data.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(data[p], val) <= 0)
                break;
            data[i] = data[p];
            i = p;
        }
        data[i] = val;
        return val;
    }
    public T Pop()
    {
        var ret = data[0];
        var p = 0;
        var x = data[data.Count - 1];
        while (Left(p) < data.Count - 1)
        {
            var l = Left(p);
            if (l < data.Count - 2 && cmp(data[l + 1], data[l]) < 0) l++;
            if (cmp(data[l], x) >= 0)
                break;
            data[p] = data[l];
            p = l;
        }
        data[p] = x;
        data.RemoveAt(data.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => data.Count > 0;
}
