public static class P
{
    public static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var hate = Console.ReadLine().Split().Select(x => int.Parse(x) - 1).ToArray();
        if (n == 2)
        {
            Console.WriteLine(-1);
            return;
        }
        //残り全員に嫌われているカードがあれば組み込む
        //サイクリックヤバがあれば組み込む
        //嫌われを組み込むことでサイクリックが解決不能になることはあるか
        //ない:ある場合はサイクリックを組み込める
        SortedSet<int> _cyclic = new SortedSet<int>();
        int[] hatedCount = new int[n];
        for (int i = 0; i < n; i++)
        {
            hatedCount[hate[i]]++;
            if (hate[hate[i]] == i && i < hate[i])
            {
                _cyclic.Add(i);
                _cyclic.Add(hate[i]);
            }
        }

        HashSet<int>[] hateds = Enumerable.Range(0, n + 1).Select(_ => new HashSet<int>()).ToArray();
        for (int i = 0; i < n; i++)
            hateds[hatedCount[i]].Add(i);

        bool[] added = new bool[n];
        int prevHated = -1;
        List<int> res = new List<int>();
        int nextTop = 0;
        Action<int> add = x =>
        {
            res.Add(x);
            added[x] = true;
            hateds[hatedCount[x]].Remove(x);
            hatedCount[x] = -1;
            prevHated = hate[x];
            if (nextTop == x) nextTop++;

            var xHate = hate[x];
            if (0 <= hatedCount[xHate])
            {
                hateds[hatedCount[xHate]].Remove(xHate);
                hatedCount[xHate]--;
                hateds[hatedCount[xHate]].Add(xHate);
            }

            if (x == hate[hate[x]])
            {
                _cyclic.Remove(x);
                _cyclic.Remove(hate[x]);
            }
        };

        for (int i = 0; i < n; i++)
        {
            int remainCount = n - i;
            if (hateds[remainCount].Count != 0)
            {
                var target = hateds[remainCount].First();
                add(target);
                continue;
            }
            if (remainCount != 1 && remainCount - 1 <= _cyclic.Count)
            {
                var min = _cyclic.Min;
                if (min == prevHated)
                {
                    _cyclic.Remove(min);
                    var anotherMin = _cyclic.Min;
                    add(anotherMin);
                    if (hate[anotherMin] != min) _cyclic.Add(min);
                }
                else
                {
                    add(min);
                }
                continue;
            }
            var cand = nextTop;
            while (added[cand] || prevHated == cand) cand++;
            add(cand);
        }
        Console.WriteLine(string.Join(" ", res.Select(x => x + 1)));
    }
}

public struct Pair : IEquatable<Pair>
{
    public int A;
    public int B;
    public Pair(int a, int b)
    {
        if (a < b) { A = b; B = a; }
        else { A = a; B = b; }
    }

    public bool Equals(Pair other) => A == other.A && B == other.B;
    public override int GetHashCode() => A * B;
}

