class MultiSet
{
	readonly Dictionary<int, int> cnt = new Dictionary<int, int>();
	readonly SortedSet<int> keys = new SortedSet<int>();
	public int Max => keys.Max;
	public MultiSet() { }
	public void Add(int x)
	{
		if (!cnt.ContainsKey(x))
		{
			cnt[x] = 1;
			keys.Add(x);
		}
		else cnt[x]++;
	}
	public void Remove(int x)
	{
		if (!keys.Contains(x)) throw new Exception();
		if (cnt[x] == 1)
		{
			keys.Remove(x);
			cnt.Remove(x);
		}
		else cnt[x]--;
	}
	public void Decrement(int x)
	{
		Remove(x);
		Add(x - 1);
	}
}
