class Solver
{
    public void Solve(Scanner sc)
    {
        var N = sc.Int;
        if (N == 2) Fail(-1);
        var A = new int[N];
        var ct = new int[N];
        for (var i = 0; i < N; i++)
        {
            A[i] = sc.Next<int>() - 1;
            ct[A[i]]++;
        }
        var q = new PriorityQueue<int>();
        for (var i = 0; i < N; i++) q.Push(i);
        var use = new bool[N];
        var res = new List<int>();
        if (N <= 5) goto CH;
        for (var i = 0; i < N; i++)
        {
            var p = q.Pop();
            while (q.Any() && use[q.Top]) q.Pop(); 
            if (i > 0 && A[res[i - 1] - 1] == p)
            {
                var t = p;
                p = q.Pop();
                while (q.Any() && use[q.Top]) q.Pop();
                q.Push(t);
            }
            if (ct[A[p]] == N - i - 1)
            {
                q.Push(p);
                p = A[p];
            }
            use[p] = true;
            ct[A[p]]--;
            res.Add(p + 1);
            while (q.Any() && use[q.Top]) q.Pop();
        }
    CH:;
        if (q.Count == 0) { Console.WriteLine(string.Join(" ", res));return; }
        var a = q.data;a.Sort();
        foreach (var p in Permutations(Enumerable.Range(0, a.Count).ToArray()))
        {
