        if (dfs(a)) {
            cout.WriteLine(string.Join(" ", ans));
        } else {
            cout.WriteLine(-1);
        }

    }

    bool dfs(int[] a, int depth = 0, int pre = -1) {
        if (depth == a.Length) return true;
        for (int i = 0; i < ans.Length; i++) {
            if (used[i]) continue;
            if (pre >= 0 && a[pre] == i + 1) continue;

            used[i] = true;
            ans[depth] = i + 1;
            if (dfs(a, depth + 1, i)) {
                return true;
            }
            used[i] = false;
        }
        return false;
    }
}

