            a[i] = i == (n - 1) ? 1 : n;
        }*/

        for (int i = 0; i < n; i++) {
            a[i]--;
        }

        var ans = Solve(a, n);

        if (ans.Length > 0) {
            cout.WriteLine(string.Join(" ", ans.Select(x => x + 1)));
        } else {
            cout.WriteLine(-1);
        }

    }

    public class Data {
        public int Index, NgCount;
    }

    private int[] Solve(int[] a, int n) {
        var dislike = new int[n];

        foreach (var x in a) {
            dislike[x]++;
        }

        var result = new List<int>();
        var vertexes = new MultiSet<int>();
        var ngSet = new MultiSet<Data>((d1, d2) => {
            var cmp = d1.NgCount.CompareTo(d2.NgCount);
            if (cmp != 0) return cmp;
            return d1.Index.CompareTo(d2.Index);
        });

        for (int i = 0; i < n; i++) {
            vertexes.Add(i);
            ngSet.Add(new Data { Index = i, NgCount = dislike[i] });
        }

        for (int i = 0; i < n - 3; i++) {
            var count = vertexes.Count;
            int target = -1;
            int pre = -1;
            if (result.Count > 0) pre = result[result.Count - 1];

            if (ngSet.Count > 0) {
                var data = ngSet.Max();
                if (data.NgCount == n - i - 1) {
                    if (pre >= 0 && a[pre] == data.Index) return Array.Empty<int>();
                    target = data.Index;
                }
            }

            if (target == -1) {
                for (int j = 0; j < count; j++) {
                    var p = vertexes.At(j);
                    if (pre >= 0 && a[pre] == p) continue;
                    target = p;
                    break;
                }
            }

            if (target == -1) return Array.Empty<int>();
            result.Add(target);
            var old = new Data { Index = a[target], NgCount = dislike[a[target]] };
            dislike[a[target]]--;
            ngSet.Remove(new Data { Index = target, NgCount = dislike[target] });
            if (ngSet.Remove(old)) {
                old.NgCount--;
                ngSet.Add(old);
            }
            vertexes.Remove(target);
        }

        var rem = vertexes.ToArray();
        Array.Sort(rem);

        do {
            var r = result.ToList();
            r.AddRange(rem);
            bool ok = true;
            for (int i = 0; i + 1 < r.Count; i++) {
                if (a[r[i]] == r[i + 1]) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                result.AddRange(rem);
                break;
            }
        } while (NextPermutation(rem));

        return result.ToArray();
    }

    public static void Swap<T>(ref T a, ref T b) {
        var t = a;
        a = b;
        b = t;
    }

    public static bool NextPermutation<T>(T[] array) where T : IComparable<T> {
        int n = array.Length;
        for (int i = n - 2; i >= 0; i--) {
            if (array[i].CompareTo(array[i + 1]) < 0) {
                int index = Array.FindLastIndex(array, v => array[i].CompareTo(v) < 0);
                Swap(ref array[i], ref array[index]);
                Array.Reverse(array, i + 1, n - (i + 1));
                return true;
            }
        }
        Array.Reverse(array);
        return false;
    }
}


public partial class MultiSet<T> {
    private readonly LLRBTreeNode<T> end = new LLRBTreeNode<T>(default(T));
    private LLRBTreeNode<T> root = null;
    private readonly IComparer<T> _comparer;


    public MultiSet() : this(Comparer<T>.Default) {
    }

    public MultiSet(IComparer<T> comparer) {
        _comparer = comparer;
        root = end;
    }

    public MultiSet(Comparison<T> comp) : this(Comparer<T>.Create(comp)) { }

    protected virtual bool AllowMultiple { get { return true; } }

    public int Count { get { return root == null ? 0 : root.Count + root.LeftTotalCount + root.RightTotalCount - 1; } }

    private LLRBTreeNode<T> FindNode(T value) {
        var node = root;
        while (node != null) {
            int cmp = Compare(value, node);
            if (cmp == 0) {
                return node;
            }
            node = (cmp < 0) ? node.Left : node.Right;
        }
        return null;
    }

    public void Clear() {
        root = end;
    }

    public bool Contains(T value) {
        var node = FindNode(value);
        return node != null;
    }

    public int CountOf(T value) {
        var node = FindNode(value);
        return node != null ? node.Count : 0;
    }

    public int IndexOfLowerBound(T value) {
        var node = root;
        int index = 0;
        while (node != null) {
            int cmp = Compare(value, node);
            if (cmp <= 0) {
                node = node.Left;
            } else {
                index += node.LeftTotalCount + node.Count;
                node = node.Right;
            }
        }
        return index;
    }

    private int Compare(T value, LLRBTreeNode<T> node) {
        if (node == end) {
            return -1;
        }

        return _comparer.Compare(value, node.Value);
    }

    public int IndexOfUpperBound(T value) {
        var node = root;
        int index = 0;
        while (node != null) {
            int cmp = Compare(value, node);
            if (cmp < 0) {
                node = node.Left;
            } else {
                index += node.LeftTotalCount + node.Count;
                node = node.Right;
            }
        }
        return index;
    }

    public T At(int index) {
        var node = root;
        while (node != null) {
            int leftCount = node.LeftTotalCount;
            if (leftCount <= index && index < leftCount + node.Count) {
                return node.Value;
            }

            if (index < leftCount) {
                node = node.Left;
            } else {
                index -= leftCount + node.Count;
                node = node.Right;
            }
        }
        throw new ArgumentOutOfRangeException("index");
    }

    public T Min() {
        return At(0);
    }

    public T Max() {
        return At(Count - 1);
    }

    public LLRBTreeIterator<T> AtIterator(int index) {
        var node = root;
        while (node != null) {
            int leftCount = node.LeftTotalCount;
            if (leftCount <= index && index < leftCount + node.Count) {
                return new LLRBTreeIterator<T>(node, index - leftCount);
            }

            if (index < leftCount) {
                node = node.Left;
            } else {
                index -= leftCount + node.Count;
                node = node.Right;
            }
        }
        throw new ArgumentOutOfRangeException("index");
    }

    public void Add(T value) {
        root = Add(root, value);
        root.Color = LLRBTreeNode<T>.BLACK;
    }

    private LLRBTreeNode<T> Add(LLRBTreeNode<T> h, T value) {
        if (h == null) {
            return new LLRBTreeNode<T>(value);
        }

        int cmp = Compare(value, h);
        if (cmp == 0) {
            if (AllowMultiple) {
                h.Count++;
                FixCount(h);
            }
        } else if (cmp <= 0) {
            h.Left = Add(h.Left, value);
            FixCount(h);
        } else {
            h.Right = Add(h.Right, value);
            FixCount(h);
        }

        if (IsRed(h.Right) && !IsRed(h.Left)) {
            h = RotateLeft(h);
        }

        if (IsRed(h.Left) && IsRed(h.Left.Left)) {
            h = RotateRight(h);
        }

        if (IsRed(h.Left) && IsRed(h.Right)) {
            ColorFlip(h);
        }

        return h;
    }

    private LLRBTreeNode<T> RemoveLeftestNode(LLRBTreeNode<T> h, out LLRBTreeNode<T> leftMost) {
        if (h.Left == null) {
            leftMost = h;
            return null;
        }

        if (!IsRed(h.Left) && !IsRed(h.Left.Left)) {
            h = MoveRedLeft(h);
        }

        h.Left = RemoveLeftestNode(h.Left, out leftMost);
        return FixUp(h);
    }

    private bool TryReduceCount(LLRBTreeNode<T> h, T value, out int num) {
        num = 0;
        if (h == null) {
            return false;
        }

        int cmp = Compare(value, h);
        if (cmp == 0) {
            num = h.Count;
            if (h.Count > 1) {
                h.Count--;
                FixCount(h);
                return true;
            }
            return false;
        }
        if (TryReduceCount((cmp < 0) ? h.Left : h.Right, value, out num)) {
            FixCount(h);
            return true;
        }
        return false;
    }

    public bool Remove(T value) {
        if (AllowMultiple) {
            int num;
            if (TryReduceCount(root, value, out num)) {
                return true;
            }
            if (num == 0) {
                return false;
            }
        } else {
            if (!Contains(value)) {
                return false;
            }
        }

        root = RemoveNode(root, value);
        if (root != null) {
            root.Color = LLRBTreeNode<T>.BLACK;
        }
        return true;
    }

    private LLRBTreeNode<T> RemoveNode(LLRBTreeNode<T> h, T value) {
        if (Compare(value, h) < 0) {
            if (h.Left == null) {
                throw new KeyNotFoundException("value");
            }

            if (!IsRed(h.Left) && !IsRed(h.Left.Left)) {
                h = MoveRedLeft(h);
            }
            h.Left = RemoveNode(h.Left, value);
            FixCount(h);
        } else {
            if (IsRed(h.Left)) {
                h = RotateRight(h);
            }

            if (h.Right == null) {
                if (Compare(value, h) == 0) {
                    return null;
                }

                throw new KeyNotFoundException("value");
            }

            if (!IsRed(h.Right) && !IsRed(h.Right.Left)) {
                h = MoveRedRight(h);
            }

            if (Compare(value, h) == 0) {
                LLRBTreeNode<T> sub;
                h.Right = RemoveLeftestNode(h.Right, out sub);
                h = Substitute(h, sub);
                FixCount(h);
            } else {
                h.Right = RemoveNode(h.Right, value);
                FixCount(h);
            }
        }

        return FixUp(h);
    }

    private LLRBTreeNode<T> Substitute(LLRBTreeNode<T> node, LLRBTreeNode<T> sub) {
        sub.Parent = node.Parent;
        sub.Left = node.Left;
        sub.Right = node.Right;
        sub.TotalCount = node.TotalCount;
        sub.Color = node.Color;

        if (sub.Parent != null) {
            if (sub.Parent.Left == node) {
                sub.Parent.Left = sub;
            }

            if (sub.Parent.Right == node) {
                sub.Parent.Right = sub;
            }
        }
        if (sub.Left != null) {
            sub.Left.Parent = sub;
        }

        if (sub.Right != null) {
            sub.Right.Parent = sub;
        }

        return sub;
    }

    private static LLRBTreeNode<T> MoveRedLeft(LLRBTreeNode<T> h) {
        ColorFlip(h);

        if (IsRed(h.Right.Left)) {
            h.Right = RotateRight(h.Right);
            FixCount(h);
            h = RotateLeft(h);
            ColorFlip(h);
        }

        return h;
    }

    private static LLRBTreeNode<T> MoveRedRight(LLRBTreeNode<T> h) {
        ColorFlip(h);

        if (IsRed(h.Left.Left)) {
            h = RotateRight(h);
            ColorFlip(h);
        }

        return h;
    }

    private static LLRBTreeNode<T> RotateLeft(LLRBTreeNode<T> h) {
        var x = h.Right;
        h.Right = x.Left;
        x.Left = h;

        x.Color = h.Color;
        h.Color = LLRBTreeNode<T>.RED;
        FixCount(h);
        FixCount(x);
        return x;
    }

    private static LLRBTreeNode<T> RotateRight(LLRBTreeNode<T> h) {
        var x = h.Left;
        h.Left = x.Right;
        x.Right = h;

        x.Color = h.Color;
        h.Color = LLRBTreeNode<T>.RED;
        FixCount(h);
        FixCount(x);
        return x;
    }

    private static bool IsRed(LLRBTreeNode<T> h) {
        return h != null && h.Color == LLRBTreeNode<T>.RED;
    }

    private static void ColorFlip(LLRBTreeNode<T> h) {
        h.Color = !h.Color;
        h.Left.Color = !h.Left.Color;
        h.Right.Color = !h.Right.Color;
    }

    private static LLRBTreeNode<T> FixUp(LLRBTreeNode<T> h) {
        if (IsRed(h.Right)) {
            h = RotateLeft(h);
        }

        if (h.Left != null && IsRed(h.Left) && IsRed(h.Left.Left)) {
            h = RotateRight(h);
        }

        if (IsRed(h.Left) && IsRed(h.Right)) {
            ColorFlip(h);
        }
        FixCount(h);
        return h;
    }

    private static void FixCount(LLRBTreeNode<T> node) {
        node.TotalCount = node.Count + node.LeftTotalCount + node.RightTotalCount;
    }

    public void Debug() {
        if (root != null) {
            root.Debug();
        }
    }
}

