                    _cyclic.Push(min);
                    min = anotherMin;
                }
                add(min);
                continue;
            }
            var cand = cands.Top;
            if (prevHated == cand)
            {
                cands.Pop();
                var anotherCand = cands.Top;
                cands.Push(cand);
                cand = anotherCand;
            }
            add(cand);
        }
        Console.WriteLine(string.Join(" ", res.Select(x => x + 1)));
    }
