var N:int
var a:seq[int]

proc solve() =
  tb := initTable[int,int]()
  for i in 0..<N: tb[a[i]] += 1
  rest := initSet[int]()
  for i in 0..<N: rest.insert(i)
  if N <= 5:
    ans := newSeq[int](N)
    for i in 0..<N: ans[i] = i
    while true:
      valid := true
      for i in 0..<N-1:
        if a[ans[i]] == ans[i+1]: valid = false
      if valid:
        for i in 0..<N:
          stdout.write(ans[i]+1)
          if i < N - 1:
            stdout.write(" ")
        echo ""
        return
      if not ans.nextPermutation(): break
    echo -1
    return
  ans := newSeqWith(N, -1)
  for i in 0..<N:
    if i == N - 4:
      assert(false)
      v := newSeq[int]()
      for p in rest.items:
        v.add(p)
      while true:
        valid := true
        if a[ans[i-1]] == v[0]: valid = false
        for j in 0..<v.len - 1:
          if a[v[j]] == v[j+1]: valid = false
        if valid:
          break
        if not v.nextPermutation(): assert(false)
      for j in i..<N:
        ans[j] = v[j - i]
      break
    assert(tb.len > 0)
    flag := false
    if tb.len <= 2:
      target := -1
      for k,v in tb:
        if v == rest.len - 1 and k in rest:
          target = k
          flag = true
          break
      if flag:
        ans[i] = target
        flag = true
        assert(i == 0 or a[ans[i-1]] != ans[i])
    if not flag:
      for p in rest.items:
        if i > 0 and a[ans[i-1]] == p: continue
        ans[i] = p
        break
      assert(ans[i] != -1)
    rest.erase(ans[i])
    tb[ans[i]] -= 1
    if tb[ans[i]] == 0: tb.del(ans[i])
  for i in 0..<N:
    stdout.write(ans[i]+1)
    if i < N - 1:
      stdout.write(" ")
  echo ""
  return

#{{{ main function
proc main() =
  N = nextInt()
  a = newSeqWith(N, nextInt()-1)
  solve()
  return

main()
