from operator import itemgetter

def DFS(Graph, Vertices):
    Unvisited = {vertex:1 for vertex in Vertices}
    FirstVisitedOrder = {vertex:0 for vertex in Vertices}
    LastVisitedOrder = {vertex:0 for vertex in Vertices}
    Label = {vertex:vertex for vertex in Vertices}
    firstorder = 1
    lastorder = 1
    RootVertices = filter(lambda vertex: Unvisited[vertex], Vertices)
    make_q = list
    next_item = itemgetter(-1)
    pop = list.pop
    append = list.append

    for root in RootVertices :
        stack = make_q([(None, root)])
        while stack:
            parent, child = next_item(stack)
            if LastVisitedOrder[child]:
                pop(stack)
            else:
                if Unvisited[child]:
                    Unvisited[child] = 0
                    FirstVisitedOrder[child] = firstorder
                    firstorder += 1
                    Label[child] = Label.get(parent, Label[child])
                    Unvisitedgrandchildren = list(vertex for vertex in Graph[child] if Unvisited[vertex])
                    if Unvisitedgrandchildren:
                        for grandchild in Unvisitedgrandchildren[::-1]:
                            append(stack, (child, grandchild))
                    else:
                        pop(stack)
                        LastVisitedOrder[child] = lastorder
                        lastorder += 1

                else:
                    pop(stack)
                    LastVisitedOrder[child] = lastorder
                    lastorder += 1
    return Label, FirstVisitedOrder, LastVisitedOrder

