class AtCoder:
    def main(self):
        N = int(input())
        a = list(map(int, input().split()))

        next_cards = {}
        for i in range(N):
            a_i = a[i]
            _min = min(i + 1, a_i)
            _max = max(i + 1, a_i)
            next_cards[i + 1] = list(range(1, _min)) + list(range(_min + 1, _max)) + list(range(_max + 1, N + 1))

        deq = collections.deque()
        for i in range(1, N + 1):
            deq.append((i, [i]))

        ans = []
        while deq:
            card, cards = deq.popleft()
            cards_set = set(cards)
            for next_card in next_cards[card][::-1]:
                if next_card not in cards_set:
                    if len(cards) == N - 1:
                        ans = cards + [next_card]
                        break
                    deq.appendleft((next_card, cards + [next_card]))
            if ans:
                break

        if ans:
            print(*ans)
        else:
            print(-1)


