        heappush(h, i)
    res_list = []
    forbidden_list = []
    forbid = 0
    while len(h) > 0:
        i = heappop(h)
        if i != forbid:
            res_list.append(i)
            forbid = a_list[i - 1]
        elif len(h) > 0:
            j = heappop(h)
            res_list.append(j)
            forbid = a_list[j - 1]
            heappush(h, i)
        else:
            # print(i, res_list)
            while len(res_list) > 0:
                j = res_list[-1]
                if a_list[j - 1] == i:
                    heappush(h, res_list.pop())
                else:
                    forbid = a_list[i - 1]
                    res_list.append(i)
                    forbidden_list.append(i)
                    break
            if len(res_list) == 0:
                # print(i, h)
                forbid = a_list[i - 1]
                res_list.append(i)
                forbidden_list.append(i)

        if len(forbidden_list) >= 2:
            if n == 2:
                return "-1"
            else:
                res_list = res_list[:n - 3]
                abc = [i for i in range(1, n + 1) if i not in res_list]
                for a, b, c in permutations(abc):
