fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let forbid = (0..n).map(|_| sc.read::<usize>() - 1).collect::<Vec<_>>();

    if n == 2 {
        println!("-1");
        return;
    }

    let mut q = (0..n).rev().collect::<Vec<_>>();

    let mut ans = vec![];
    while q.len() > 3 {
        let first = q.pop().unwrap();
        if ans.len() > 0 {
            let last = ans[ans.len() - 1];
            if forbid[last] == first {
                let second = q.pop().unwrap();
                ans.push(second);
                q.push(first);
            } else {
                ans.push(first);
            }
        } else {
            ans.push(first);
        }
    }

    assert_eq!(q.len(), 3);
    let mut candidate = vec![
        (q[0], q[1], q[2]),
        (q[0], q[2], q[1]),
        (q[1], q[0], q[2]),
        (q[1], q[2], q[0]),
        (q[2], q[1], q[0]),
        (q[2], q[0], q[1]),
    ];
    candidate.sort();
    for (a1, a2, a3) in candidate.into_iter() {
        if ans.len() > 0 {
            let last = ans[ans.len() - 1];
            if forbid[last] == a1 {
                continue;
            }
        }

        if forbid[a1] == a2 || forbid[a2] == a3 {
            continue;
        }
        ans.push(a1);
        ans.push(a2);
        ans.push(a3);
        break;
    }

    assert_eq!(ans.len(), n);
    for i in 0..n {
        if i > 0 {
            sc.write(" ");
        }
        sc.write(ans[i] + 1);
    }
    sc.write("\n");
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

