use std::collections::BinaryHeap;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();

    let a: Vec<usize> = (0..n).map(|_| sc.read::<usize>() - 1).collect();
    let mut ban_count = vec![0; n];
    for i in 0..n {
        ban_count[a[i]] += 1;
    }

    let mut ban_count_q = BinaryHeap::new();
    for i in 0..n {
        ban_count_q.push((ban_count[i], i));
    }
    let mut remain_q = BinaryHeap::new();
    for i in 0..n {
        remain_q.push(-(i as i64));
    }

    let mut used = vec![false; n];
    let mut ans = vec![];
    for _ in 0..n {
        let remain_size = remain_q.len();
        let mut candidate = vec![];
        while let Some((cur, i)) = ban_count_q.pop() {
            if used[i] {
            } else if cur != ban_count[i] {
                ban_count_q.push((ban_count[i], i));
            } else if ban_count[i] + 1 == remain_size {
                candidate.push(i);
            } else {
                assert!(ban_count[i] + 1 < remain_size);
                ban_count_q.push((ban_count[i], i));
                break;
            }
        }
        if candidate.len() > 1 {
            println!("-1");
            return;
        }
        if candidate.is_empty() {
            let first = pop(&mut remain_q, &used);
            let can_select_first = ans.is_empty() || a[ans[ans.len() - 1]] != first;
            if can_select_first {
                ans.push(first);
                used[first] = true;
                ban_count[a[first]] -= 1;
            } else {
                let second = pop(&mut remain_q, &used);
                ans.push(second);
                used[second] = true;
                ban_count[a[second]] -= 1;
                remain_q.push(-(first as i64));
            }
        } else {
            let select = candidate[0];
            ans.push(select);
            used[select] = true;
            ban_count[a[select]] -= 1;
        }
    }

    for i in 0..n {
        if i > 0 {
            sc.write(" ");
        }
        sc.write(format!("{}", ans[i] + 1));
    }
    sc.write("\n");
}

fn pop(q: &mut BinaryHeap<i64>, used: &Vec<bool>) -> usize {
    while let Some(x) = q.pop() {
        let i = (-x) as usize;
        if !used[i] {
            return i;
        }
    }
    unreachable!()
}

