fn main() {
    input! {
        n: usize,
        forbidden: [usize1; n]
    };

    let mut used = vec![false; n];
    let mut a = vec![0; n];
    let mut available = Treap::new();
    for i in 0..n {
        available.push(i);
    }
    let mut left_f = vec![0; n];
    for i in 0..n {
        left_f[forbidden[i]] += 1;
    }
    for i in 0..n {
        if n - i <= 5 {
            let mut unused = (0..n).filter(|&idx| !used[idx]).collect::<Vec<_>>();
            if let Some(a) = fill_last(a, unused, forbidden) {
                let ans = a.into_iter().map(|i| i+1).collect::<Vec<_>>();
                println!("{}", join!(ans, " "));
            } else {
                println!("-1");
            }
            return;
        }

        let ng = ifv!(i >= 1, forbidden[a[i-1]], n);
        let mut best = available.min().unwrap();
        if ng == best {
            best = available.peek_greater(best).unwrap();
        }
        // debug!(i, best, n-i, left_f[forbidden[best]]);
        if !used[forbidden[best]] && left_f[forbidden[best]] + 1 == n - i {
            assert!(forbidden[best] != ng);
            best = forbidden[best];
        }
        used[best] = true;
        a[i] = best;
        available.remove(best);
        left_f[forbidden[best]] -= 1;
    }
}

