fn solve() {
	let n = read!(usize);
	let a = read!([usize]);
	let mut res = vec![0;n];
	for i in 0..n {
		res[a[i]-1] += 1;
	}
	let mut set: BinaryHeap<Rev<usize>> = BinaryHeap::new();
	for i in 0..n {
		set.push(Rev(i));
	}
	let mut idx = 0;
	let mut ma = 0;
	for i in 0..n {
		ma = max(ma, res[i]);
	}
	let mut ans = vec![];
	let mut prev = n;
	let mut nokori = n;
	while !set.is_empty() {
		if nokori<=4 {break;}
		let mut val = set.pop().unwrap();
		if val.0==prev {
			let tmp = val.clone();
			val = set.pop().unwrap();
			set.push(tmp);
		}
		println!("{}", val.0);
		let target = n-1-idx;
		let tmp_ma = if ma==res[a[val.0]-1] {ma-1} else {ma};
		if tmp_ma>=target {
			let val2 = set.pop().unwrap();
			ma = if ma==res[a[val2.0]-1] {ma-1} else {ma};
			res[a[val2.0]-1] -= 1;
			set.push(val);
			ans.push(val2.0);
			prev = a[val2.0]-1;
		}
		else{
			ma = if ma==res[a[val.0]-1] {ma-1} else {ma};
			res[a[val.0]-1] -= 1;
			ans.push(val.0);
			prev = a[val.0]-1;
		}
		idx += 1;
		nokori -= 1;
	}
	let mut v = vec![];
	while !set.is_empty() {
		let val = set.pop().unwrap();
		v.push(val.0);
	}
	let mut ret = vec![];
	let mut p = vec![];
	let mut seen = vec![false;v.len()];
	search(&v,seen,&a,&mut ret,prev,p,n);
	ret.sort();
	// for &i in &ret {
	// 	println!("{} {} {} {}", i.0, i.1, i.2, i.3);
	// }
	if ret.len()==0 {
		println!("-1");
		return;
	}
	for &i in &ans {
		print!("{} ", i+1);
	}
	if v.len()==2 {
		print!("{} {}", ret[0].0, ret[0].1);
	}
	if v.len()==3 {
		print!("{} {} {}", ret[0].0, ret[0].1, ret[0].2);
	}
	if v.len()==4 {
		print!("{} {} {} {}", ret[0].0, ret[0].1, ret[0].2, ret[0].3);
	}
}

fn search(v: &Vec<usize>, mut seen: Vec<bool>, a: &[usize], mut ans: &mut Vec<(usize,usize,usize,usize)>, prev: usize, mut p: Vec<usize>, n: usize) {
	// println!("{} {} {}", v.len(), prev, p.len());
	if p.len()==v.len() {
		if p.len()==2 {ans.push((p[0],p[1],n,n));}
		if p.len()==3 {ans.push((p[0],p[1],p[2],n));}
		if p.len()==4 {ans.push((p[0],p[1],p[2],p[3]));}
		return;
	}
	for i in 0..v.len() {
		if seen[i] {continue;}
		let val = v[i];
		if val==prev {
			continue;
		}
		let mut seen_c = seen.clone();
		seen_c[i] = true;
		let mut p_c = p.clone();
		p_c.push(val+1);
		search(&v, seen_c, &a, &mut ans, a[val]-1, p_c, n);
	}
}

fn run() {
    solve();
}

// ---------- begin SegmentTree Point update Range query ----------
mod segment_tree {
    pub struct PURQ<T: Clone, F: Fn(T, T) -> T> {
        n: usize,
        a: Vec<T>,
        id: T,
        op: F,
    }
    #[allow(dead_code)]
    impl<T: Clone, F: Fn(T, T) -> T> PURQ<T, F> {
        pub fn new(n: usize, id: T, op: F) -> PURQ<T, F> {
            let mut k = 1;
            while k < n {
                k *= 2;
            }
            PURQ {
                n: k,
                a: vec![id.clone(); 2 * k],
                id: id,
                op: op,
            }
        }
        pub fn update(&mut self, x: usize, v: T) {
            let mut k = self.n + x;
            let a = &mut self.a;
            a[k] = v;
            k >>= 1;
            while k > 0 {
                a[k] = (self.op)(a[2 * k].clone(), a[2 * k + 1].clone());
                k >>= 1;
            }
        }
        pub fn update_tmp(&mut self, x: usize, v: T) {
            self.a[x + self.n] = v;
        }
        pub fn update_all(&mut self) {
            for k in (1..(self.n)).rev() {
                self.a[k] = (self.op)(self.a[2 * k].clone(), self.a[2 * k + 1].clone());
            }
        }
        pub fn find(&self, mut l: usize, mut r: usize) -> T {
            let mut p = self.id.clone();
            let mut q = self.id.clone();
            l += self.n;
            r += self.n;
            while l < r {
                if (l & 1) == 1 {
                    p = (self.op)(p, self.a[l].clone());
                    l += 1;
                }
                if (r & 1) == 1 {
                    r -= 1;
                    q = (self.op)(self.a[r].clone(), q);
                }
                l >>= 1;
                r >>= 1;
            }
            (self.op)(p, q)
        }
    }
}
// ---------- end SegmentTree Point update Range query ----------
