fn valid(a: &[usize], ans: &[usize]) -> bool {
    for i in 1..ans.len() {
        if a[ans[i - 1]] == ans[i] {
            return false;
        }
    }
    true
}

fn dfs(ans: &mut [usize], a: &[usize], k: usize) -> bool {
    if k == 0 {
        return valid(a, ans);
    }
    if dfs(ans, a, k - 1) {
        return true;
    }
    let n = a.len() - 1;
    for i in (n - k + 1)..(n + 1) {
        ans.swap(n - k, i);
        if dfs(ans, a, k - 1) {
            return true;
        }
    }
    let t = ans[n - k];
    for i in (n - k + 1)..(n + 1) {
        ans[i - 1] = ans[i];
    }
    ans[n] = t;
    false
}

fn run() {
    input! {
        n: usize,
        a: [usize; n],
    }
    if n == 2 {
        println!("-1");
        return;
    }
    let mut seg = segment_tree::PURQ::new(n + 1, (0, 0), std::cmp::max);
    let mut deg = vec![0; n + 1];
    let mut a = a;
    a.insert(0, 0);
    for i in 1..(n + 1) {
        deg[a[i]] += 1;
    }
    for i in 1..(n + 1) {
        seg.update_tmp(i, (deg[i], i));
    }
    seg.update_all();
    let mut set: std::collections::BTreeSet<usize> = (1..(n + 1)).collect();
    let mut ans = vec![0; n + 1];
    for i in 1..(n + 1 - 3) {
        let (d, x) = seg.find(0, n + 1);
        let v = if d == n - i {
            x
        } else {
            let mut u = 0;
            for &k in set.iter() {
                if k != a[ans[i - 1]] {
                    u = k;
                    break;
                }
            }
            u
        };
        assert!(v != 0 && set.contains(&v));
        set.remove(&v);
        ans[i] = v;
        deg[a[v]] -= 1;
        seg.update(a[v], (deg[a[v]], a[v]));
        seg.update(v, (0, 0));
    }
    for ans in ans[(n - 2)..].iter_mut() {
        let v = *set.iter().next().unwrap();
        set.remove(&v);
        *ans = v;
    }
    assert!(set.is_empty());
    assert!(*ans.last().unwrap() != 0);
    dfs(&mut ans, &a, 2);
    let mut out = String::new();
    for a in ans[1..].iter() {
        out.push_str(&format!("{} ", *a));
    }
    out.pop();
    println!("{}", out);
}

fn main() {
    run();
