        let mut v = 0;
        for &k in set.iter() {
            if a[ans[i - 1]] != k {
                v = k;
                break;
            }
        }
        set.remove(&v);
        ans[i] = v;
    }
    let b: Vec<usize> = set.into_iter().collect();
    let (x, y, z) = (b[0], b[1], b[2]);
    for &(x, y, z) in [(x, y, z), (x, z, y), (y, x, z), (y, z, x), (z, x, y), (z, y, x)].iter() {
