use std::collections::{BTreeMap, BTreeSet};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    if n == 2 {
        println!("-1");
        return;
    }
    let refer: Vec<usize> = (0..n).map(|_| sc.read::<usize>() - 1).collect();
    let mut inv_refer = vec![0; n];
    for i in 0..n {
        inv_refer[refer[i]] += 1;
    }

    let mut map = BTreeMap::new();
    for i in 0..n {
        map.entry(inv_refer[i])
            .or_insert_with(BTreeSet::new)
            .insert(i);
    }

    let mut remain = (0..n).rev().collect::<Vec<_>>();

    let mut is_removed = vec![false; n];
    let mut ans = vec![];
    while remain.len() > 3 {
        let highest_reference = *map.iter().next_back().unwrap().0;
        if highest_reference + ans.len() + 1 == n {
            let highest = map.remove(&highest_reference).unwrap();
            assert_eq!(highest.len(), 1);
            let highest = highest.into_iter().next_back().unwrap();
            ans.push(highest);
            remove(highest, &refer, &mut inv_refer, &mut map, &mut is_removed);
            continue;
        }

        let first = remain.pop().unwrap();
        if ans.len() > 0 && refer[ans[ans.len() - 1]] == first {
            let second = remain.pop().unwrap();
            remain.push(first);
            ans.push(second);
            remove(second, &refer, &mut inv_refer, &mut map, &mut is_removed);
        } else {
            ans.push(first);
            remove(first, &refer, &mut inv_refer, &mut map, &mut is_removed);
        }
    }

    assert_eq!(remain.len(), 3);

    let mut candidates = vec![
        (remain[0], remain[1], remain[2]),
        (remain[0], remain[2], remain[1]),
        (remain[1], remain[0], remain[2]),
        (remain[1], remain[2], remain[0]),
        (remain[2], remain[1], remain[0]),
        (remain[2], remain[0], remain[1]),
    ];
    candidates.sort();
    for (a1, a2, a3) in candidates.into_iter() {
        if ans.len() > 0 && refer[ans[ans.len() - 1]] == a1 {
            continue;
        }

        if refer[a1] == a2 || refer[a2] == a3 {
            continue;
        }
        ans.push(a1);
        ans.push(a2);
        ans.push(a3);
        break;
    }
    assert_eq!(ans.len(), n);

    for i in 0..n {
        if i > 0 {
            sc.write(" ");
        }
        sc.write(ans[i] + 1);
    }
    sc.write("\n");
}

fn remove(
    selected: usize,
    refer: &[usize],
    inv_refer: &mut Vec<usize>,
    map: &mut BTreeMap<usize, BTreeSet<usize>>,
    is_removed: &mut Vec<bool>,
) {
    let reference_count = inv_refer[selected];
    let set = map.get_mut(&reference_count).unwrap();
    assert!(set.remove(&selected));
    if set.is_empty() {
        assert!(map.remove(&reference_count).unwrap().is_empty());
    }
    is_removed[selected] = true;

    let refer = refer[selected];
    assert!(inv_refer[refer] > 0);
    let current_count = inv_refer[refer];
    inv_refer[refer] -= 1;
    let next_count = inv_refer[refer];

    if is_removed[refer] {
        return;
    }

    assert!(map.get_mut(&current_count).unwrap().remove(&refer));
    if map[&current_count].is_empty() {
        assert!(map.remove(&current_count).unwrap().is_empty());
    }
    map.entry(next_count)
        .or_insert_with(BTreeSet::new)
        .insert(refer);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        Self(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

use std::collections::BinaryHeap;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();

    let a: Vec<usize> = (0..n).map(|_| sc.read::<usize>() - 1).collect();
    let mut ban_count = vec![0; n];
    for i in 0..n {
        ban_count[a[i]] += 1;
    }

    let mut ban_count_q = BinaryHeap::new();
    for i in 0..n {
        ban_count_q.push((ban_count[i], i));
    }
    let mut remain_q = BinaryHeap::new();
    for i in 0..n {
        remain_q.push(-(i as i64));
    }

    let mut used = vec![false; n];
    let mut ans = vec![];
    for _ in 0..n {
        let remain_size = remain_q.len();
        let mut candidate = vec![];
        while let Some((cur, i)) = ban_count_q.pop() {
            if used[i] {
            } else if cur != ban_count[i] {
                ban_count_q.push((ban_count[i], i));
            } else if ban_count[i] + 1 == remain_size {
                candidate.push(i);
            } else {
                assert!(ban_count[i] + 1 < remain_size);
                ban_count_q.push((ban_count[i], i));
                break;
            }
        }
        if candidate.len() > 1 {
            unreachable!();
        }
        if candidate.is_empty() {
            let first = pop(&mut remain_q, &used);
            let can_select_first = ans.is_empty() || a[ans[ans.len() - 1]] != first;
            if can_select_first {
                ans.push(first);
                used[first] = true;
                ban_count[a[first]] -= 1;
            } else {
                let second = pop(&mut remain_q, &used);
                ans.push(second);
                used[second] = true;
                ban_count[a[second]] -= 1;
                remain_q.push(-(first as i64));
            }
        } else {
            let select = candidate[0];
            ans.push(select);
            used[select] = true;
            ban_count[a[select]] -= 1;
        }
    }

    for i in 1..n {
        assert_ne!(a[ans[i - 1]], ans[i]);
    }

    for i in 0..n {
        if i > 0 {
            sc.write(" ");
        }
        sc.write(format!("{}", ans[i] + 1));
    }
    sc.write("\n");
}

fn pop(q: &mut BinaryHeap<i64>, used: &Vec<bool>) -> usize {
    while let Some(x) = q.pop() {
        let i = (-x) as usize;
        if !used[i] {
            return i;
        }
    }
    unreachable!()
}

