/**
 * Segment Tree. This data structure is useful for fast folding on intervals of an array
 * whose elements are elements of monoid I. Note that constructing this tree requires the identity
 * element of I and the operation of I.
 * Verified by: yukicoder No. 259 (http://yukicoder.me/submissions/100581)
 *              AGC015-E (http://agc015.contest.atcoder.jp/submissions/1461001)
 */
struct SegTree<I, BiOp> {
    n: usize,
    dat: Vec<I>,
    op: BiOp,
    e: I,
}

impl<I, BiOp> SegTree<I, BiOp>
    where BiOp: Fn(I, I) -> I,
          I: Copy {
    pub fn new(n_: usize, op: BiOp, e: I) -> Self {
        let mut n = 1;
        while n < n_ { n *= 2; } // n is a power of 2
        SegTree {n: n, dat: vec![e; 2 * n - 1], op: op, e: e}
    }
    /* ary[k] <- v */
    pub fn update(&mut self, idx: usize, v: I) {
        let mut k = idx + self.n - 1;
        self.dat[k] = v;
        while k > 0 {
            k = (k - 1) / 2;
            self.dat[k] = (self.op)(self.dat[2 * k + 1], self.dat[2 * k + 2]);
        }
    }
    /* [a, b) (note: half-inclusive)
     * http://proc-cpuinfo.fixstars.com/2017/07/optimize-segment-tree/ */
    pub fn query(&self, mut a: usize, mut b: usize) -> I {
        let mut left = self.e;
        let mut right = self.e;
        a += self.n - 1;
        b += self.n - 1;
        while a < b {
            if (a & 1) == 0 {
                left = (self.op)(left, self.dat[a]);
            }
            if (b & 1) == 0 {
                right = (self.op)(self.dat[b - 1], right);
            }
            a = a / 2;
            b = (b - 1) / 2;
        }
        (self.op)(left, right)
    }
}

/**
 * Returns the least index of elements that are modified, wrapped with Some.
 * If the entire array is reversed, it returns None instead.
 * v's elements must be pairwise distinct.
 */
fn next_permutation<T: Ord>(v: &mut [T]) -> Option<usize> {
    let mut tail_dec: usize = 1;
    let n = v.len();
    while tail_dec < n {
        if v[n - tail_dec - 1] > v[n - tail_dec] {
            tail_dec += 1;
        } else {
            break;
        }
    }
    // v[n - tail_dec .. n] is strictly decreasing
    if tail_dec < n {
        let x = n - tail_dec - 1;
        let mut y = n;
        {
            let pivot = &v[x];
            for i in (n - tail_dec .. n).rev() {
                if v[i] > *pivot {
                    y = i;
                    break;
                }
            }
            assert!(y < n);
        }
        v.swap(x, y);
    }
    v[n - tail_dec .. n].reverse();
    if tail_dec < n {
        Some(n - tail_dec - 1)
    } else {
        None
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [usize1; n],
    }
    let mut indeg = vec![0; n];
    let mut g = vec![vec![]; n];
    let mut ans = vec![0; n];
    for i in 0..n {
        g[i].push(a[i]);
        indeg[a[i]] += 1;
    }
    let mut st = SegTree::new(n, max, (0, 0));
    for i in 0..n {
        st.update(i, (indeg[i] + 1, i));
    }
    let mut indegmax = st.query(0, n);
    let mut set = BTreeSet::new();
    for i in 0..n {
        set.insert(i);
    }
    let mut used = vec![false; n];
    let brute = min(3, n);
    for i in 0..n - brute {
        assert_eq!(set.len(), n - i);
        assert!(indegmax.0 <= n - i);
        let mut nxt;
        if indegmax.0 == n - i {
            nxt = indegmax.1;
        } else {
            let &mi = set.iter().next().unwrap();
            nxt = mi;
            if i >= 1 && a[ans[i - 1]] == mi {
                assert!(set.len() >= 2);
                let mut iter = set.iter();
                let &mi = iter.nth(1).unwrap();
                nxt = mi;
            }
        }
        if i >= 1 && a[ans[i - 1]] == nxt {
            puts!("-1\n");
            return;
        }
        ans[i] = nxt;
        set.remove(&nxt);
        for &w in &g[nxt] {
            if !used[w] {
                indeg[w] -= 1;
                st.update(w, (indeg[w] + 1, w));
            }
        }
        st.update(nxt, (0, 0));
        used[nxt] = true;
        indegmax = st.query(0, n);
    }
    let mut rem: Vec<usize> = set.into_iter().collect();
    assert_eq!(rem.len(), brute);
    let mut sol;
    loop {
        // rem satisfies the condition?
        let mut ok = if n - brute >= 1 { a[ans[n - brute - 1]] != rem[0] } else {
            true
        };
        for i in 0..brute - 1 {
            ok &= a[rem[i]] != rem[i + 1];
        }
        if ok {
            sol = ans.clone();
            for i in 0..brute {
                sol[n - brute + i] = rem[i];
            }
            break;
        }
        if let None = next_permutation(&mut rem) {
            puts!("-1\n");
            return;
        }
    }
    for i in 0..n {
        puts!("{}{}", sol[i] + 1, if i + 1 == n { "\n" } else { " " });
    }
}

