// error: found
fn dfs(n: usize, a: &[usize], ans: &mut Vec<usize>, poss: &mut Vec<usize>) -> Result<(), ()> {
    if ans.len() == n {
        return Err(());
    }
    let mut round = 0;
    let mut put = vec![];
    while let Some(x) = poss.pop() {
        if round >= 3 {
            break;
        }
        if ans.len() >= 1 && a[ans[ans.len() - 1]] == x {
            put.push(x);
            continue;
        }
        ans.push(x);
        for p in put.drain(..) {
            poss.push(p);
        }
        dfs(n, a, ans, poss)?;
        round += 1;
    }
    Ok(())
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize,
        a: [usize1; n],
    }
    let mut ans = Vec::with_capacity(n);
    let mut poss = vec![0; n];
    for i in 0..n {
        poss[i] = n - 1 - i;
    }
    match dfs(n, &a, &mut ans, &mut poss) {
        Ok(_) => puts!("-1\n"),
        Err(_) => {
            for i in 0..n {
                puts!("{}{}", ans[i] + 1, if i + 1 == n { "\n" } else { " " });
            }
        }
    }

}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

