fn next_permutation(a: &mut Vec<usize>) -> bool {
    let n = a.len();
    let mut x = n-2;
    while x >= 0 && a[x] >= a[x+1] {
        if x == 0 {
            return false;
        }
        x -= 1;
    }
    let mut y = n-1;
    while y > x && a[y] <= a[x] {
        y -= 1;
    }
    let mut tmp = a[x];
    a[x] = a[y];
    a[y] = tmp;

    // sort
    let mut hp = BinaryHeap::new();
    for i in x+1..n {
        hp.push(a[i]);
    }
    for i in (x+1..n).rev() {
        a[i] = hp.pop().unwrap();
    }
    true
}

fn is_valid(a: &Vec<usize>, forbidden: &Vec<usize>) -> bool {
    let n = a.len();
    for i in 0..n-1 {
        if forbidden[a[i]] == a[i+1] {
            return false;
        }
    }
    true
}

fn fill_last(mut a: Vec<usize>, mut left: Vec<usize>, forbidden: Vec<usize>) -> Option<Vec<usize>> {

    let ln = left.len();
    let i = a.len() - ln;
    loop {
        for f in 0..ln {
            a[i+f] = left[f];
        }
        if is_valid(&a, &forbidden) {
            return Some(a.clone());
        }

        let r = next_permutation(&mut left);
        if !r {
            break;
        }
    }
    None
}

